/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200923-9","meetingId":"r02-cm09","date":"2020年9月23日","dateIso":"2020-09-23","committee":"文教委員会","time":"午前１０時００分～午後 ４時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を143件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５８号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第５８号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"成年後見人等の関連の欠格事由が変更になったという、その理由をお伺いしたいのと、ここにある家庭的保育事業等ということと、あと居宅訪問型保育事業は、品川区においては、具体的に何の事業を指すのか伺いたいと思います。事業実績をそれぞれ簡単に教えてください。","respondent":"若生保育支援課長","answer":"それから２点目のご質問ですけれども、家庭的保育事業、それから居宅訪問型保育事業の具体的な内容、当区における実施状況等ですけれども、まず家庭的保育事業につきましては、いわゆる「保育ママ制度」と以前から呼ばれていたものが、子ども・子育て支援法の改正によって。","voiceIndex":6,"id":"exchange-001"}]},{"id":"topic-02","title":"第６１号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第６１号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回は、(1)の公務災害補償の限度額の引上げの改正ということですけれども、この限度額を引き上げることになった改正の理由についてお伺いしたいと思います。","respondent":"篠田学務課長","answer":"今回、大元となった文部科学省の所管する政令、こちらの改正の理由としているのは、労働者災害補償保険法の施行規則が改正されまして、その水準と合わせて、こちらのほうも見直しをしたと聞いているところです。","voiceIndex":21,"id":"exchange-002"},{"speaker":"たけうち委員","kind":"質問","question":"今回改正されるこの介護補償と災害の発生日の法定利率も含めて、毎年、このような条例改正はあるのですけれども、学校歯科医の公務災害補償ですが、直近というか、ここ１０年、２０年で分かる範囲で結構ですけれども、このようなものを使われたケースがあるのか、分かれば教えてください。","respondent":"篠田学務課長","answer":"それ以降、品川区では、１件も公務災害補償に関しては発生していないという状況です。","voiceIndex":23,"id":"exchange-003"}]},{"id":"topic-03","title":"第５６議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第５６議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"教育委員会所管のほうについてお伺いしたいのですが、その中で、修学旅行におけるキャンセル料等の保護者負担軽減ですけれども、私たちとしましても、地域の保護者からご相談もいただきまして、要望させていただいておりました。割と自由に、裁量権がかなり広いのか、それとも国がある程度メニューを示して、そこから選んでもらうような枠組みなのか、そういうことについてお伺いします。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"１点目の修学旅行の実施状況についてですが、現在、１５校中７校が中止となっています。今後の予定を、新型コロナウイルスの感染状況を鑑みて、学校のほうで検討していくところです。先ほど申し上げたほか、国からは、例えばサーモグラフィーの購入経費ですとか、サーキュレーター等の購入費、あるいは学習保障として。","voiceIndex":42,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"７校が修学旅行を中止ということで、これから極力実施できるよう努力するということだと思いますし、そうしていただきたいのですけれども、それでも既に２校が新たに中止ということで、これからもどうなるかということはあると思うのですが、新たに２校中止が出ているということがありますし、もし今後そういった中止または延期して実施ということにならざるを得ない場合は。","respondent":"有馬庶務課長","answer":"ただ、予算計上する上では、実績が出ている分をということでしたけれども、今言ったような考え方でいけば、今後発生した場合については何らかの対応をしていくと、我々も考えているということですので、同じようにキャンセルが今後発生した場合については。","voiceIndex":45,"id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"保育園のほうですけれども、こちらも伺いたいと思います。入園事務業務委託の拡大ということですけれども、現在の委託職員の増員だと事前に伺いましたが、何人を増やすのかを確認したいと思います。保育課では、いつから入園事務業務を委託していたのか、どのような業務を委託していたのか、伺いたいと思います。先ほど、窓口の相談などもやりましたという話ですけれども、それらを伺いたいと思います。","respondent":"立木保育課長","answer":"そこから順次、業務が拡大してまいりまして、今現在お願いしているものは、データ入力および確認業務、印刷封入業務、窓口電話対応業務、延長夜間還付手続事務、在園継続事務、そのほか随時必要と思われる業務をお願いしているところです。","voiceIndex":47,"id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"これが２点目です。リスクと言うのであったら、やはりＰＣＲ検査を実施することが安心と応援になるのではないかと思いまして、今回、他部署で、介護や障害者福祉サービス事業者にはＰＣＲ検査を行う予算が提案されているわけですけれども、安全・安心のため、保育士へのＰＣＲ検査も行うべきだと思いますし、その実施を求めたいと思いますが、保育部門の考えはいかがなのか伺いたいと思います。３点目です。","respondent":"立木保育課長","answer":"それからＰＣＲ検査に関しましては、区全体の方向性もありますので、今のところ、保育現場に対してのＰＣＲ検査の予定はございませんが、今後、情勢に合わせて考えてまいりたいと考えています。","voiceIndex":49,"id":"exchange-007"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からも、それぞれ伺っていきたいと思います。説明順に従って、保育所の感染拡大対策物品購入ですけれども、これは物の形で渡すのでしょうか。それから保育士への支援なのですけれども、これは６月の一般質問でも要望いたしまして、もちろん、ほかの会派からのご要望もあったと思いますけれども、実際にこのような形で支給できることになって、非常にありがたいと思います。","respondent":"若生保育支援課長、立木保育課長","answer":"一定程度そこで必要なものは買っていただけるだろうということは見越していますけれども、今後、コロナ禍が継続していく状況も予想されるところで。窓口に関してですけれども、増員に関しましては、実は、１名増員したことによって、明確な例えば削減効果が見込めるかどうかは。相談支援の件についてのご質問ですが、こちらは一般のメンタル相談窓口、広くほかの方も使うところにというよりは、これは品川区として設置をして。","voiceIndex":51,"id":"exchange-008"},{"speaker":"あべ委員","kind":"質問・要望","question":"システムも初めてだと思うので、最初からスムーズにいくかどうかも分からないことですので、そういった面でも、人を手厚めにしておいていただければというのと、本来であれば、これは年度途中だから仕方ないのですけれども、保育課の職員自体を増やす方向で、特に新型コロナウイルス感染症ですし、子どもたちの入園希望者もまだ増えていますので。","respondent":"若生保育支援課長、立木保育課長","answer":"そういったところで、少しでも保育士の方のふだんの不安ですとかストレスの緩和になればということで、プライバシーが守られる形で。職員のことに関しましても、必要な人員に関しては、きちんと要求していくということで、きちっと向き合う形で対応してまいりたいと考えています。これも体制は業務委託になりますので、請け負うところの体制にもよりますけれども、少なくともこの枠の中で、いつ相談連絡を受けても対応できる体制で。","voiceIndex":55,"id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"要望とはいえ、見通しを教えていただければと思います。ご努力はすばらしいと思うのですが、なかなか残念なことで、修学旅行ではないけれども、何か代替になるような、ちょっとしたイベントですとか機会を設けるという学校もあれば、教えていただきたいと思います。これは渡しきりということでよろしいでしょうか。それとも、何か清算して、使わなかったら返すみたいな感じになるのでしょうか。","respondent":"矢部教育総合支援センター長、篠田学務課長、若生保育支援課長","answer":"修学旅行につきましては、まだこれから実施予定の学校もありますので、中止になった学校につきましては。したがいまして、全額使いきってしまえばそれで問題はないのですが、残った場合は、基本的には学校を通して令達している予算ですので、最終的には。当然、そういった対応にも、コロナではないからといってお断わりすることはないような形で、仕様のほう等も考えていきたいと思ってまいります。","voiceIndex":59,"id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"入園相談窓口案内システムの導入についてですけれども、これは東京都の補助金が含まれていて、それを活用しているものですが、このシステムは、このようなものを使ったほうがいいとか、東京都側から何らかの指針があったのか。そうではなかったにせよ、これは具体的にどのようなシステムなのか。民間とか他の自治体で実際に使われているものなのか、具体的にどのようなシステムになるのかを教えてください。","respondent":"立木保育課長","answer":"以前より窓口の混雑、それから待機場所が少ないところがございましたので、そういったことの改善というところで、いろいろと他区等を調査、それから区内にも戸籍住民課でシステムを持ってありますので、そういったところをいろいろと調査・検討した結果、まずは、今。","voiceIndex":63,"id":"exchange-011"},{"speaker":"筒井委員","kind":"質問","question":"具体的にどのようなシステムにするのか、どのような会社を選定するのかはこれからということでよろしいのでしょうか。","respondent":"立木保育課長","answer":"今、特に随意契約でいくということではなく、必要な機能もこちらで絞り込みまして、それに合致するものを導入するという形で検討しているところです。","voiceIndex":65,"id":"exchange-012"},{"speaker":"筒井委員","kind":"確認","question":"続きまして、メンタルヘルス相談窓口についてですけれども、まず、これの対象は、先ほど来、他の委員からもご質問が出ていますけれども、これは別に公立保育園の保育士も相談を受けてもいいということなのでしょうかということの確認が１点。以上２点をお願いします。","respondent":"吉田保育施設調整担当課長、若生保育支援課長、立木保育課長","answer":"メンタルヘルスの関係につきましては、区立民営保育園が４園ありますけれども、指定管理もしくは委託にしているところが対象になっている次第です。具体的な数字という調査はかけていないところではありますが、１つの例として、全国の社会福祉協議会が実施した保育士等へのアンケート調査がございまして。メンタルヘルスの部分で、区立、公務員の部分に関しましては、区全体で職員の健康管理部門のほうで仕組みを持っておりまして。","voiceIndex":67,"id":"exchange-013"},{"speaker":"たけうち委員","kind":"確認","question":"保育士の支援です。これは、この間の一般質問でも、会派の議員から質問させていただいていて確認ですが、この２万５,０００円なりがその保育士の手元に直接行っているということの報告を受けるということでいいのですか。","respondent":"立木保育課長、若生保育支援課長","answer":"引き続きやらせていただく予定です。こういった趣旨で、感染リスクを負いながら業務を頑張っていただいている保育士の一助に少しでもなればという趣旨につきましては、きちんと伝わるように事業者等に説明していきたいと考えております。","voiceIndex":71,"id":"exchange-014"},{"speaker":"たけうち委員","kind":"質問・要望","question":"石けんがだめで、ハンドソープがいいという明確な医学的なものはないと伺っているので、致し方ない部分もあるのですが、お声の中に、前もどなたかの委員が言われたかもしれないけれども、学校の保護者の中にも、やはり気にする方が、特に網に石けんを入れて、少しちびてくると汚れが目立ったりして、ハンドソープという中で、いろいろと私も調べたら、学校によっては、ほかのところですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-015"},{"speaker":"せお委員","kind":"質問・要望","question":"２点ほど伺います。窓口混雑緩和策についてですけれども、入園事務の業務委託ということで先ほどからもお話がありましたが、業務委託を拡大するときに、入園に関しての情報が一元化をされていて、それが共有できているのかをお聞かせいただきたいのが１点です。保育士等への支援、応援給付金ですけれども、書いていないので確認ですが、すまいるスクールの職員は入らないのかを教えてください。","respondent":"立木保育課長、廣田子ども育成課長","answer":"窓口で受付やご案内をさせていただいたことに関しましては、きちっと入園相談担当職員と課内で共有されて、一律に同じ対応ができる形を取らせていただいております。現時点ではその範囲内で対応していただくというところで、今後の状況によっては、また検討しますけれども、委託料の範囲内で対応していただくと考えています。","voiceIndex":78,"id":"exchange-016"},{"speaker":"せお委員","kind":"質問・要望","question":"すまいるスクールのことは理解いたしました。業務委託のほうですけれども、以前に、対応する職員によってお話しする内容が違うということもよく聞かれるのですが、通常よりも見学などもなかなかできづらく、相談も電話相談だったりとか窓口に来られる方も多いと思いますので、いま一度、情報を統一していただいて、同じように案内できるように確認をお願いいたします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-017"},{"speaker":"横山委員","kind":"質問・要望","question":"何点か確認させてください。窓口混雑緩和策についてですけれども、先ほどの議論の中でもありましたが、窓口発券機は、戸籍住民課等で導入している整理券のようなイメージでよろしいのでしょうか。入園相談窓口案内システムですけれども、ウェブ予約ができるようになるのはすごくいいと私は思っておりまして、こちらはいつ頃にスタートできる見込みなのでしょうか。","respondent":"立木保育課長","answer":"スタートに関しましては、可及的速やかにということで、今、考えておりまして、１２月の一番混雑する時期前にとにかくスタートしないと意味がございませんので、そういった形で、今、準備を進めているところです。","voiceIndex":82,"id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-019"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"何点かお伺いします。最初に、保育所等の感染防止対策物品購入で、先ほど、あべ委員からも少しありましたけれども、状況を聞きながら配付されるということで、これは消耗品は、ある意味、余っても使えるのかなと思うのですが、空気清浄機等というところで、空気清浄機が入っているところに何個も送ってもしようがないのかなとも思っていますので、これはぜひ希望を確認をしていただきたいのが１点。","respondent":"立木保育課長、吉田保育施設調整担当課長、若生保育支援課長","answer":"ウェブ案内、予約ができるようになりますとか、待ち時間、例えばメールでお知らせすることができますという新しい仕組みに関しましては。消耗品や空気清浄機につきましては、現在、導入を予定しているものは、新型コロナウイルス感染症対策として、ウイルスの軽減に役立つものについて。メンタルヘルスの相談支援事業の来年度以降につきましては、これは歳入が見込めるかどうかというところは未確定というか。","voiceIndex":85,"id":"exchange-020"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"最後に周知の件でもう一点だけ。今のお話でホームページをという話がありまして、なかなかホームページだけだと難しいかとも思いますので、来ていただいた後でも結構ですので、相談が終わった後や、あとは相談案内のパンフレット等に記載していただいて、今後はウェブでのシステムをこれから導入していきますという案内をしていただければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-021"},{"speaker":"あべ委員","kind":"質問・要望","question":"先ほどの答弁の中で気になったのですが、保育士の相談ですけれども、相談対象に公立は入れないということですが、公立で働けば、派遣の方は職員の相談システムではなかなか厳しいかと思うのですけれども、そこは対象になるのか、あるいはどのようにお考えなのか教えていただきたいのと、それから相談の内容で、コロナ禍での保育の在り方のようなものは、臨床心理士というより。","respondent":"立木保育課長、若生保育支援課長、篠田学務課長","answer":"公立保育園の派遣の職員の方は、今回、メンタルヘルスの区の仕組みの中では、今のところは入っておりませんので。相談内容の中でベテラン保育士等というところですけれども、こちらについては、心理的な負担というところで言えば。こちらに関しましては、今回の補正予算自体が、国の補正予算の補助金に基づいて組んでいるものですので。","voiceIndex":90,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"保育園の入園事務で重要な窓口対応相談を委託し、拡大するというのは問題があるので、やはりこれは正規の職員で対応すべきだという意見は言わせていただきたいと思います。その上で、公・私立を問わない支給ですとか、それにこの場を借りて言いたいのは、感染リスクのさらに最前線で働いているのは医療従事者なので、そういったところにも支給を求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-023"},{"speaker":"あべ委員","kind":"質問・要望","question":"いろいろと要望を出させていただきましたので、そういったこともご検討いただきながら、本件には賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-024"}]},{"id":"topic-04","title":"す。 予定表では(1)令和２年度請願第１１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(2)令和２年度請願第１２号","agenda":"す。 予定表では(1)令和２年度請願第１１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(2)令和２年度請願第１２号","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、保育のほうは加点があるということで、平成２９年に国の通知があったということですが、今、保育園の方に加点をしている理由を教えていただきたいのと、現時点で区は、こういった特別な配慮が必要だと考える職種の方々をどのように考えているのかを伺いたいと思います。","respondent":"立木保育課長","answer":"それから支援が必要だと思われる方も、今回、緊急事態宣言等の中でもお預かりをさせていただいた、社会機能を維持するためのご職業に就かれている保護者の方等ですけれども、区の姿勢としては何かしらの支援が必要ということは、当然、考えておりますが、一方。","voiceIndex":108,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"そうですね。かなりいろいろと、社会を維持するのに必要な職種というのは、本当に広いと思いますし、支援が必要だというのは、私も同感です。保育のほうでは、実際に働いている全ての方が対象ですという話があったのですけれども、そもそも国の通知の紹介もありましたが、中身にも関わると思うのですけれども、保育士の方を加点するということになった理由を聞きたかったので、もう一度お願いします。","respondent":"立木保育課長","answer":"当時、待機児童が多い中では、まず働く人を確保した上で、待機児童を受け入れて、待機児童を減らしていくという意図の中で、保育園で働く保育士の職場復帰を後押しするという形で、加点を検討しなさいという通知が来たです。","voiceIndex":110,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"保育従事者に調整指数プラス１とされたのは、平成２９年の国の通知によってだというご説明でしたけれども、今回の請願で議題とされている医療従事者に対しては、調整指数加点について、国は今、現時点でどういった動向なのでしょうか。何か区として把握されていることがあったら、教えてください。","respondent":"立木保育課長","answer":"今のところ、職業に対しての加点というのは、ご説明に挙げた保育士等だけでございまして、厚生労働省に確認を取ったところ、ほかの職業に対して何かしら通知を出すということは、今のところないと聞いております。","voiceIndex":112,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"そのようなことですけれども、ただ、区としては、医療従事者に対して何らかの保護というか、そうした優遇策をしてあげたいということでしたが、その１つが、保育園入園時の調整指数加点、こういったことも区としては一方策として受け入れられるということでよろしいのでしょうか。","respondent":"立木保育課長","answer":"幾つか方法がある中で、どれがベターなのかというところは、いろいろなデータ等も参考にしながら検討する必要があると考えているところです。","voiceIndex":114,"id":"exchange-028"},{"speaker":"あべ委員","kind":"質問・要望","question":"保育士に対する加点がある現状からいっても、また、新型コロナウイルス感染症以前からも医療関係者の方々には加点が必要ではないかという議論は、一定あったかと思います。その辺の線引きは、技術的に可能でしょうか。ある程度線引きができるのであれば、ぜひ前向きに考えていただきたいですけれども、いかがでしょうか。","respondent":"立木保育課長","answer":"若しくは、「緊急事態宣言で対象になった職種」というくくり方もできようかと思います。このどこら辺に線引きをするかというところは、現時点でどの程度というところまでは検討が進んでおりませんで、今後ということになるかと思います。","voiceIndex":116,"id":"exchange-029"},{"speaker":"たけうち委員","kind":"質問・要望","question":"会派で紹介議員になったので、これについて特に異議を唱えるのではないのですが、もし分かれば、各自治体によって既に医療従事者にこのような形で対応している例も、２３区でも少しあるかと思うので、その辺の情報があれば教えていただきたいのと、あと、今、品川区ではないと思うのですけれども、一方で医療従事者のお子さんに対して、保育園での「来ないでくれ」というような。","respondent":"立木保育課長","answer":"それから保育園における、例えば優先入園、何らかの優先をつけた場合、優遇措置をした場合の園での対応、それから、その他のご批判等についてですが、一定程度の例えば対象から漏れた方からのご意見は、当然、想定はされるところですが。","voiceIndex":118,"id":"exchange-030"},{"speaker":"たけうち委員","kind":"質問・要望","question":"分かりました。あえて医療従事者なので、身近なところで新型コロナウイルス感染症の対応をされているがゆえの逆の排除されてしまうような、そこに加えてこの加点ともしなったときに、さらなる何か、そのような人も中にはいらっしゃるので、そこはぜひしっかりと考えていただきたいと要望しておきます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"対象者の範囲が広くなりますと、政策の効果が出にくくなることを私は懸念しておりまして、職種、施設、所得制限を設定したりですとか、他の自治体の保育士の事例ですと、そういったものですとか、区内や市内の勤務の方というようなやり方もあるように思いますが、私は、ある程度範囲をしっかりと絞って効果を出していただきたいと考えているのですけれども、そのあたりの現在のお考えはいかがでしょうか。","respondent":"立木保育課長","answer":"加点と加点以外、加点、優先入園以外の方法ですが、なかなか難しいところでありますので、すみません、今はすぐ思いつくところはございません。","voiceIndex":121,"id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"いろいろと確認させていただきました。特に医療従事者の方もそうですけれども、それ以外の区民の方に対して、なるべく早いタイミングで確実に情報が届くような方策を採用していただきたいと要望したいと思います。","respondent":"立木保育課長","answer":"いろいろと内容が変わることに関しても、事前に制度上変わることがありますというような表記に関しましては、何か不都合がないかどうかは、確認した上で対応してまいりたいと思います。","voiceIndex":123,"id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"なかなかこういった新型コロナウイルス感染症の対策の一部という形で、緊急的にこういった請願が出されて、また、スピーディーに対応しなければならないということで、通常時であれば、しっかりとした準備期間ですとかスケジュールを取ることができるかと思うのですけれども、なかなか事務的にも大変な部分が出てくるかと思うのですが、周知をできるだけ多くの必要な方に届く形で検討していただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-034"},{"speaker":"芹澤副委員長","kind":"意見","question":"本日、結論を出すで、採択でお願いします。内容としても、会派で様々やり取りをしましたけれども、エッセンシャルワーカーと呼ばれる大きな職種の中でも、医療従事者が先端に立っていると考えていますので、ぜひ後押しをしていきたいという思いでの紹介議員にもなっております。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":127,"id":"exchange-035"},{"speaker":"せお委員","kind":"意見","question":"本日、結論を出すでお願いします。結論としては採択でお願いいたします。医療従事者は、本当に大変な状態にありますので、保育をとても必要としていると思います。先ほどから議論がありますが、医療従事者という範囲だったりですとか、その対象となる範囲を、とても時間がないとは思うのですが、そこの議論もぜひ慎重にしていただいて、こちらをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":128,"id":"exchange-036"},{"speaker":"たけうち委員","kind":"質問・要望","question":"本日、結論を出すで、採択でお願いします。何とか来年の４月に間に合うように、大変ですけれども、よろしくお願いいたします。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択なのですが、一言、述べさせていただきたいのですけれども、先ほども出ましたが、加点というのは、必要な保育園整備完了に向けた過程の中での暫定的な措置であるべきだというふうな考えがあります。今こそ保育をはじめ、ケアの手厚い区政にも転換していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-038"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。先ほど来からお話にも出ているように、医療従事者の範囲や、その定義の明確化と、また、これが新型コロナウイルス感染症収束までの期間限定のものなのか、また、ほかの職業の方の公平性、国や都の動向などもしっかりと注視していただくといったことを考慮していっていただいて、そうしたことも検討していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-039"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日結論を出すということで、採択でお願いしたいと思います。途中から減らすのは大変難しいことですので、少なくとも初めは職種限定的な考え方で、医療にダイレクトに関わっていらっしゃる職種を中心に検討していただき、かつ、その方々については、できるだけ早くこの制度が実現できるように頑張っていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-040"},{"speaker":"横山委員","kind":"意見","question":"結論を出すで、採択でお願いします。早急かつ慎重な対応をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-041"}]},{"id":"topic-05","title":"令和２年請願第１１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(3)令和２年陳情第４１号、品川区立学校図書館設備充実に関する陳情","agenda":"令和２年請願第１１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(3)令和２年陳情第４１号、品川区立学校図書館設備充実に関する陳情","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"それで、やはり情報化が進んでいく中で、実は私、今回の陳情が出るまで学校図書館でインターネットが通じないなどと考えもしなかったものですから、ちょっとびっくりいたしました。その中で、既存の学校内でも、ある程度、自由に使える端末が出てくるのではないかと思います。品川区としては、今なぜつながっていない状態にあえてしているのか、今後の考え方について教えてください。","respondent":"横山品川図書館長、篠田学務課長","answer":"今現在、現状としては、説明申し上げましたように、個人情報を抱えているシステムとの併存が難しく、区役所の中でも個人情報とインターネットの接続はできるだけ分離するということで、実は学校図書館のシステムリプレースの際にも。現状、図書館で、図書館のシステム上つながっていないというのは、今、品川図書館長から説明があったとおりですけれども、現状は、もう既に無線ＬＡＮの構築は全ての学校で完了しています。","voiceIndex":143,"id":"exchange-042"},{"speaker":"あべ委員","kind":"質問・要望","question":"司書の立場で先生たちの教材探しなどをサポートしたり、お伝えしたりということも、せっかく来ていただいているわけですから、したほうがいいに決まっているわけです。そのレファレンス機能を十分に果たすためには、やはり学校に来ている間も自由に情報にアクセスできる立場にいたほうが、学校の学びにとって私は有利だと思いますけれども、あえて使わないのはむしろもったいなくないでしょうか。","respondent":"矢部教育総合支援センター長","answer":"今の委員のお話を受けてですけれども、ＧＩＧＡスクールになりますと、１人１台お子さんにタブレットがわたります。現在、学務課長からも説明があったとおり、各学校に４０台のタブレットパソコンが置いてありますので、今、それを活用して学習しています。","voiceIndex":146,"id":"exchange-043"},{"speaker":"あべ委員","kind":"質問・要望","question":"これはむしろ学校の校長先生の裁量の部分も結構あるかとは思うのですけれども、その校長先生の意識によって、あるいは学校の先生方の考えによって、司書がインターネットに接続できたりできなかったりという状態自体がもったいないなというふうに思っております。そうした方向で、ぜひ考えていただきたいなと。それをすることのデメリットは特にないと思うのですが、いかがでしょうか。","respondent":"横山品川図書館長","answer":"それが全体に及んだ際に、改めて学校図書館の配備も考えられると思います。","voiceIndex":148,"id":"exchange-044"},{"speaker":"たけうち委員","kind":"意見","question":"この陳情書の中で、下から２段目の上から２行目の辺り、「これまでの調べ学習では、ＰＣ室と図書館が離れているところが多く、インターネットで調べる児童生徒と本で調べる児童生徒が別の教室で調べるため、教員にとっても、図書館スタッフにとってもサポートしにくい学校が多くありました」となっているのですけれども、その辺の状況は、実態としてはどのような感じで教育委員会は捉えていますか。","respondent":"横山品川図書館長","answer":"現状は確かに離れているので物理的な制約は今まではあったと思いますが、まさにＧＩＧＡスクールで生徒が１人１台持っているという形になれば、学校図書館のスタッフも教諭の方も、そちらをサポートする形で調べ学習を進められるので。","voiceIndex":151,"id":"exchange-045"},{"speaker":"たけうち委員","kind":"質問","question":"分かりました。そのような中で、各図書館スタッフが使えるような形という、これは子どもたちに対してというふうに受け止めた部分と、最後のほうでは、図書館スタッフとあるので、そういった面では、ＧＩＧＡスクール構想でいいますと、子どもたちには１台、それを重々活用しながらと。先ほどあったとおり、図書館スタッフの方も使えるようなものが既にあると、こういうことでよろしいのでしょうか。","respondent":"篠田学務課長","answer":"現状は、今、委員ご指摘のとおり、要は、機械自体はいろいろな形で工夫をすれば学校の中にもあるということですので、そこはＧＩＧＡスクールの導入に合わせて、その使い道についてもいろいろと検討して工夫をしながらやっていけるのかというふうに思っているところです。","voiceIndex":153,"id":"exchange-046"},{"speaker":"筒井委員","kind":"確認","question":"具体的に司書がタブレットを持つことで、ＰＣ端末を持つことで、どのように子どもたちに対して教育をしていくのか、そうした具体的な活用方法が、これも急ですから見えない中、いろいろと現時点ですぐというわけには、品川区としても難しいかと考えていますけれども、今後、ＧＩＧＡスクールということが定着していって、やっぱり教員以外にも司書、図書館スタッフにも１人１台持つというようなことを。","respondent":"篠田学務課長","answer":"ただ、これから先、情報化が様々な形で進んでいく中で、例えば国などがそういった考え方を示されるかどうかといったこともあろうかとは思うのですけれども、その辺は十分見据えながら、ただ、最低限必要な部分にはきちんと手当てをしていくということで。","voiceIndex":155,"id":"exchange-047"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ検討していっていただきたいのですけれども、国の動向ということもおっしゃられたのですが、やっぱりＧＩＧＡスクール構想という中、なぜか図書館のスタッフにタブレットがないというのもちょっと違和感を覚えますので、国はその点をどうお考えなのか、あまりお気付きになっていない点なのかちょっと分からないのですけれども、そうした動向をしっかりと見ていただいて、また、今現在。","respondent":"篠田学務課長","answer":"文部科学省の基本的な考え方としては、今回のＧＩＧＡスクールに関しては、子どもたちが、１人１台、きちんと使いこなせるような環境をつくりましょうと言っている中で、言ってみれば、教員に関する部分は、区としてその辺は配慮するといったところです。","voiceIndex":157,"id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"陳情のほうに新学習指導要領が引用されています。四角の部分です。学校図書館は、子どもの情報活用能力の育成にとって重要で、計画的に活用することで、主体的・対話的で深い学びの実現に向けた授業改善に生かすとありますけれども、区の学校教育要領では、この辺のところといいますか、学校図書館と情報活用能力の関係ですとか、どのような位置付けになっているのか、改めて伺いたいと思います。","respondent":"工藤指導課長","answer":"インターネットの情報は、その中の情報は正しいのかどうかも含めて、そういったものも含めた情報活用能力、広く育成が必要であるということは教育要領でも示しているところではあります。","voiceIndex":159,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう少し聞きたいのですけれども、４０台あるというのは、今まで先行してやっていたところもあって、今度、１人１台来ると、品川区全体として４０台余るから、それをいろいろなものに活用できるということなのか、もう少し聞かせていただきたいのと、それと、ＧＩＧＡスクールの１人１台ということなのですけれども、教員と児童・生徒には配るということなのですが。","respondent":"篠田学務課長","answer":"特に今回は、ＧＩＧＡスクールにおきましてはｉＰａｄを入れるという形で機種の選定を進めているところであるのですけれども、４０台についてはＷｉｎｄｏｗｓの機械ということになっていまして、この先。","voiceIndex":161,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"暫定的な対応はもちろん必要かもしれませんが、その中でも校長の判断とか、場所によってはそうならないとか、それですと、やっぱり私はまずいと思うので、しっかりと区として図書館スタッフが日常的に使える端末を保障していくというような考え方を示すということが大事だと思いますし、必要であれば、財政措置も講じて整備するということは必要だと思いますけれども、いかがでしょうか。","respondent":"篠田学務課長","answer":"先ほど申し上げたとおり、リースがまだ残っている機械が引き続きあったりとかということもありますので、そういったものの活用等は改めて学校の中でどういったことが必要なのかというのは、それぞれ学校の事情もありますから、考えながら進めていけるのかと考えているところです。","voiceIndex":163,"id":"exchange-051"},{"speaker":"安藤委員","kind":"意見","question":"最後に意見ですけれども、学校教育、教育の環境整備というのは、やっぱり区の役割といいますか、教育行政の大事な役割だと思いますので、ぜひしっかりと整備していただくようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":165,"id":"exchange-052"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"ＧＩＧＡスクール構想の考え方がそれぞれあるのかと思うのですが、先ほど、図書館が閉鎖されているというような発言があったと思うのですけれども、私は逆に、校内無線ＬＡＮがつながっているのであれば、全世界につながって開かれているということだと思っていまして、端末に関しても、図書館に置いてある今の端末を、なかなかインターネットが使えないというようなお話からの議論だったと思うのですが。","respondent":"篠田学務課長","answer":"基本的にはこの補助金はいろいろと難しい制約がございまして、例えば契約にしても、これまで文部科学省が様々な形でＩＣＴ化を推進してきているということもございまして、今回、必要な台数の３分の２だけを補助しますという仕組みになっています。","voiceIndex":166,"id":"exchange-053"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"もう１点確認で、今の外から持ってきたパソコンの接続に関してですけれども、これは設定というのは、パスワード等を教えてもらってという話ではなくて、複雑な設定があるということなのですか。例えば、事前に持っていきたいので、当日、インターネット接続をさせていただきたいというようなお話があっても、なかなか使うことはできないのでしょうか。","respondent":"篠田学務課長","answer":"したがいまして、１台１台、いわゆる家庭で使うようなＷｉ－Ｆｉを簡単に接続できるというような形にはなっていないところがありますので、もしどうしてもおつなぎになるということであれば、事前に私どもの学務課に校務情報管理対策担当がおりますので。","voiceIndex":168,"id":"exchange-054"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。理由としましては、先ほどいろいろな議論がありましたけれども、まずは持っている端末を使っていただいて、今後の可能性についてはこれからも議論されるのだろうと思っていますが、まずは今の時点では使えるものを使っていただきたいという意味での不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-055"},{"speaker":"せお委員","kind":"意見","question":"先ほどから議論やお話がありますが、１人１台、これからはタブレットを児童・生徒にお渡しするということであったり、これから急ピッチでＧＩＧＡスクール構想に向けて動いていく中で、整備だったり、タブレットの活用方法、授業内容とかもそうですけれども、本当に整備していかなければならないことがまずたくさんありますので、そこのところが整理できてから検討していただくのもよろしいかと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-056"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それを活用していく調べ学習についても、どういう形でこれから新しい流れの中でやっていくのか、また、その中で学校図書館スタッフがパソコンを使った場合に、どういうメリットが出てきて、どういうことをやっていけるのか等、もうちょっと整理をしっかりとしていただく中で今後構築していくというお話もありましたので、その上で果たして専用のものが必要かどうかも含めて検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-057"},{"speaker":"安藤委員","kind":"意見","question":"ですので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":174,"id":"exchange-058"},{"speaker":"筒井委員","kind":"質問・要望","question":"ただし、急なＧＩＧＡスクールの話が出てきまして、当然、端末配備の優先順位もありますし、予算の制約や図書館スタッフの具体的な活用方法がまだよく分からないという点もありますけれども、今後、そうした課題が解消されたときには、やはりせっかくの熱心な図書館スタッフのお力を活かしていく、また図書館スタッフのお話を伺って、スタッフの具体的な活用方法をしっかりと詰めていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-059"},{"speaker":"あべ委員","kind":"意見","question":"本日結論を出すで、採択でお願いしたいと思います。スタッフはちょっと大変になるかもしれないのですけれども、そこは力を合わせて学校のために頑張って動いていただければというふうに、その環境が、繰り返しますが、現状の持っているもので十分進めていくことは可能だと思いますので、できる学校から進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":176,"id":"exchange-060"},{"speaker":"横山委員","kind":"質問・要望","question":"その次の段階として、将来的に、現在残っている端末ですとか、どういったふうに使っていけるのか、また、司書だけではなくて、学校や子どもたちを取り巻く方々にとって、どういった使い方、共有なのか、またセキュリティの観点ですとか、フォルダー共有ですとか、クラウドを使うですとか、そういった様々な細々したことも発生してくるかと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-061"}]},{"id":"topic-06","title":"令和２年陳情第４５号、２０人学級で学べるよう教職員の数と予算を増やし教育環境整備を求める陳情","agenda":"令和２年陳情第４５号、２０人学級で学べるよう教職員の数と予算を増やし教育環境整備を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"陳情本文のところに、分散登校時の子どもや教員の声が具体的に紹介されていますけれども、前回も聞きましたが、改めて、品川でも実際に少人数学級を体験することになった分散登校時に、子どもや教員からどういう声が挙がっていたのか、どのような声を聞いたのかということと、その受け止めです。聞いた声のご紹介などがあれば伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"今のご指摘ですけれども、６月の初めはやはり２か月お休みしていましたので、子どもたちは緊張した面持ちで教室に入っております。３密を避けるというところから、静かなスタートでございました。約半数ですので、そういうような状況です。","voiceIndex":186,"id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、一般質問で私も同様のことを求めて質問しましたが、新たに必要な教室数と教員数を伺ったのですが、単純に倍必要ですみたいな答弁だったのですけれども、改めてどういう意味だったのか伺いたいのですが、４０人を２０人にしたら単純に２倍ですというふうにしか聞こえなかったのですけれども、品川区としては、現在の４０人学級制度に基づく学級編制を２０人程度の学級するという上で。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"１点目につきましては、子どもたちと非常に似ていることだと思います。教員は感染防止のために様々な工夫等をしますので緊張感があったこと。そうしたところ、やはり５００以上の学級数が増えるのは間違いないというところは出ています。","voiceIndex":188,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺は後ほどぜひ聞きたいと思います。そういう声はないのですかと聞いているので、くどいですけれども、もう一度お答えいただきたい。そして、一般質問のあれですけれども、再々質問で伺ったところ、答弁では少人数学級に対しては終始慎重というか、全く前向きな答弁がないのですが、かわりに少人数編制、加配を要望しているというようなご答弁があったと思うのです。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"１点目の件についてです。先ほど、学務課長からも話がありましたとおり、ご指摘のとおり、少人数も大人数も教員の苦労は少しはあります。今、教育総合支援センター長からもありましたように、少人数指導による効果というのは、私どもも重要に考えておりますので、そのため、このコロナ禍の分散登校時ということも含めまして、従来からできるように、引き続き。","voiceIndex":191,"id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"そう言う方もいます。私も問題だと思っています。それは違うと思うのですが、そこは認めますでしょうか。","respondent":"工藤指導課長","answer":"委員ご指摘の点ですけれども、そういう意味では、少人数指導、また習熟度別指導、それが個に応じて適切な指導を行う場面で必要なところで行っているところがありますし、また、学級において複数の指導者が入る、いわゆるチームティーチング、ＴＴの形で行いますので。","voiceIndex":194,"id":"exchange-065"},{"speaker":"安藤委員","kind":"提案","question":"少人数学級を導入すべきだというのは、私ももちろん提案しましたけれども、この陳情にあるように、今、コロナの経験もしまして、いろいろな角度から、何よりも子どもの現状がそういうことを求めているというふうな状況だと思いますので、詳しくは繰り返しません。代わりということで答弁しているわけではないということでよろしいのですか。全く別な話でしているということなのですか。","respondent":"篠田学務課長","answer":"ひるがえって考えますと、２０人学級にするということは、２０人で学級編制をするということですから、２１人になった瞬間に、１０人のクラスと１１人のクラスをつくらなければいけないということになりますから、これはさすがにいかがかというところがありますので。","voiceIndex":196,"id":"exchange-066"},{"speaker":"安藤委員","kind":"質問・要望","question":"陳情者の方は、恐らく、分からないですけれども、２０人学級というのを厳密な学級編制の意味で言っているのかというのが正直分かりません。恐らくですけれども、２０人ぐらいの学級にしてほしいというふうな、普通大体そう思いますよね。ということで、私は、これは今、本当に求められている内容だと思いますので、ぜひこれは区の意思として、議会の意思としても採択していきたいという思いがあります。","respondent":"齋藤教育次長","answer":"したがいまして、私どもは、物理的に東京を含めて首都圏では、２０人での学級編制は難しい以上は、加配あるいは区の予算で講師、指導助手を加えて、４０人を２人の大人の教員の目で見る、私どもは実績、ノウハウを持っておりますので。","voiceIndex":198,"id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"それはそうだと思います。いろいろと想定される課題を挙げていただいたと私は思うのですけれども、そういったことを踏まえてでもなお、欧米などに比べても本当に何十年も遅れている学級規模の問題、これはやっぱり今だからこそ、ここを変えていくことに挑戦すべきだと思うし、それを品川区としても全国の流れ、思い等に共鳴して進めていく先頭に立っていただきたいというふうに私は思っております。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-068"},{"speaker":"あべ委員","kind":"質問・要望","question":"今の議論、日本の学級編制は上限主義をとっているので、４０人を超えると分割して、もし２０人ならそれを分割しなければいけない。でも、やっぱり国に対しては、現場の声として学級編制をもう少し緩やかにしてほしいというような声は、ぜひ上げてほしいと思うのです。そういったことは区としてはされていますでしょうか。","respondent":"篠田学務課長","answer":"ただ、学級編制として少人数学級を求めているものではなくて、少人数学習の環境を整えたいという思いでこれまでも要請していますので、基本的な考え方は同じような形で今後も対応していくと考えているところです。","voiceIndex":201,"id":"exchange-069"},{"speaker":"あべ委員","kind":"質問・要望","question":"長期的なものになりますし、国の意向や都の意向も勘案しながらということかもしれませんけれども、やっぱり今の世の中、４０人というのは、なかなか子どもたち、低学年は３５人とかありますけれども、もう少し少ない編制の中で子どもたちが安心してその集団の中にいられるようなことも、区として現場の声として考えていただきたいし、実現にたとえ時間がかかるとしても。","respondent":"齋藤教育次長","answer":"本会議でご答弁したとおり、国、都の基準が基本ですので、まずはこれに従った教育活動を実施してまいります。","voiceIndex":203,"id":"exchange-070"},{"speaker":"筒井委員","kind":"質問","question":"２０人学級、少人数学級のメリットとしましては、きめ細やかな指導が可能だということと、現在、コロナウイルスの感染拡大に伴って、その防止と消毒などの対応がしやすいということもあると思うのですけれども、逆に、大人数学級のメリットというのは、何回かお話が出たかもしれないですが、改めて大人数学級のメリットはあるのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"隣同士で人数の少ないところというよりは、全体でやることで士気が上がったり、時にはライバル意識を高めて力が入ったりという相乗効果もあるかと考えております。","voiceIndex":205,"id":"exchange-071"},{"speaker":"筒井委員","kind":"質問","question":"そうしたメリットもあるということも見ていかなくてはいけないのかと思っていますけれども、少人数学級にしたときの、先ほどからプレハブということも出ましたが、実際、では、品川区が２０人学級を実現したとしましたら、設備はどのぐらい増やさなければいけないのかとか、教員数がどのくらい増やさなければいけないのかということは、大体お分かりになっているのでしょうか。","respondent":"篠田学務課長","answer":"先ほど、私のほうで５００と申し上げたのは、５００以上かかるというのは、今の子どもの数を素直に分けるとそうなるということですので、ただ、この先、当然子どもたちが毎年増えていったりしていますから、増えれば当然、学級編制というのは先ほど申し上げたとおり。","voiceIndex":207,"id":"exchange-072"},{"speaker":"筒井委員","kind":"質問","question":"ただ、報道とかでは、知事会などの３会長などの文部科学大臣との面談で、文部科学大臣が少人数学級に対して前向きな姿勢を見せているというようなこともありますし、また、今、コロナウイルスの感染拡大で、地方に転出していくという人とか、あと、そもそも人口自体が減少していくということもあるのですけれども、そうした将来の変動とか、また文部科学省が少人数学級を進めようと言ったときに対しては。","respondent":"篠田学務課長、工藤指導課長","answer":"ただ、いずれにしましても、現状、法律で１年生は３５人、それ以外は４０人という形で規定がされていますから、それが変わるとなれば、当然その法に従って対応していくことは間違いないということだけは申し上げられると思います。そういった意味で、少人数編制を進めるべきだという議論があるというふうに認識していますので、その中で私どもは東京都の加配等も含めて、区の講師等も含めてきめ細かく対応しているというところが私どもで進めているところです。","voiceIndex":209,"id":"exchange-073"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。引き続き、区においては４０人学級、国と都の基準に従って教育現場をつくっていただきたいというのと、あと、コロナのお話もありましたけれども、今、休校、そして分散登校を経て、今の状態でもしっかりと感染の拡大を抑えられているという認識もありますので、こちらも引き続き適切に臨んでいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":214,"id":"exchange-074"},{"speaker":"せお委員","kind":"質問","question":"本日結論を出すでお願いします。不採択でお願いします。２０人学級のメリットは理解できます。ですが、先ほどから答弁がありますように、課題は多過ぎて現実的ではないと思いますので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":215,"id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"かつてないようなストレスと不安も抱えながら頑張って、今、登校しているわけですけれども、やはりそういった現状が学級規模のさらなる縮小を強く求めておりますので、柔軟で手厚い教育を実現させていく必要があると思います。採択を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":217,"id":"exchange-076"},{"speaker":"筒井委員","kind":"意見","question":"本日結論を出すで、不採択といたします。その理由は、面積、設備、教員数などの物理的な制約、また、将来的に方向性としては少人数学級の方向に行く可能性はあるでしょうけれども、具体的に２０人という数字は現実的に言って困難だということからです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":218,"id":"exchange-077"},{"speaker":"あべ委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いします。ただ、これを区が単独ですぐにできるものではないということ、もしそれをやろうとすると、逆に学校教育の根幹からかなり崩れてしまうというか、マイナスの影響が大きいということで、具体的に踏み出す状況にはないということで、申し訳ないですけれども、これは不採択ということで考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":219,"id":"exchange-078"},{"speaker":"横山委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。学級編制は法の規定と国や都の基準にのっとり対応をしていただいて、教える教科、単元、内容と、お一人お一人のお子さんの学習状況によって、少人数指導や習熟度別学習や、またチームティーチングなどを適切に実施していただきたいというふうに考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-079"}]},{"id":"topic-07","title":"令和２年陳情第４８－２号、子どもが健やかに育つための陳情（陳情項目１、２）","agenda":"令和２年陳情第４８－２号、子どもが健やかに育つための陳情（陳情項目１、２）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ質疑の前に陳情者のご意見は聞きたいと、その上で、そういったことも含めて質疑に活かせると思いますので、そのようにしていただきたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":227,"id":"exchange-080"},{"speaker":"あべ委員","kind":"意見","question":"意見陳述をしたいという趣旨は、それを聞いた上で審議してほしいということだと思いますので、常識的に考えて、意見陳述は議論の前にしていただければいいなと、それでないと、なかなか逆に、意見陳述の機会を設けている意図が不明確になってしまうことと、全国の自治体議会を見ておりまして、やはり意見陳述は前にする議会が多いのではないか、ごめんなさい、数字は持っていないのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":229,"id":"exchange-081"},{"speaker":"たけうち委員","kind":"質問","question":"区議会、私も長いことお世話になっていますけれども、なかなか意見陳述を受けたケースも少ないわけですが、いい悪いは別にして、内容によって、事前にお聞きするものと、そうではないものという形で言えば、非常に分かりやすい内容になっているかと思いますので、質疑を終わった後で必要かどうか諮っていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-082"},{"speaker":"あべ委員","kind":"質問","question":"陳情１のほうですけれども、コロナということもありますし、いろいろと心配事を相談するときに、何かを１回渡したからこれで十分ということではなくて、受け取ったときにはあまり関心がなかったけれども、その後、悩みが出てくるとか、相談したい気持ちになるというのはあると思うので、いろいろな、チャイルドラインに限らずでいいと思うのですが、様々な相談先について。","respondent":"矢部教育総合支援センター長、黛生活安全担当課長","answer":"相談窓口の周知につきましては、委員おっしゃったとおり、相談窓口については約１０か所程度、１枚にまとまった東京都からの案内があります。そこに本区のＨＥＡＲＴＳも含めた相談機関を載せて、複数回、学校に周知しています。今、委員からご指摘をいただきました点ですが、まだいろいろと検討しなければいけないところはあるとは思うのですけれども、１つの考えとして、例えばですが、今、委員からアドバイスをいただきましたように。","voiceIndex":240,"id":"exchange-083"},{"speaker":"たけうち委員","kind":"提案","question":"それから２点目のほうです、今、あべ委員からもいい提案があったと思うのですが、我々としても、このチャイルドラインのやられているすばらしい取組みについては理解しているのですけれども、やっぱりそういうふうにやっていらっしゃる区内の団体の方もいっぱいいらっしゃるので、その中でどこも品川区としてバックアップしてもらいたいと思う中で。","respondent":"矢部教育総合支援センター長、黛生活安全担当課長","answer":"少しご心配の旨かと思いますが、学校は、到着しましたら、それを配らないということはないので、確実に配布していると認識しております。ただいま委員からご意見をいただきましたとおり、まさにそういう子どものための大変有意義な活動をされている団体も多数あるところでございまして。しながわチャイルドラインとは、ご担当者が教育長のほうにもご挨拶にみえたということで、そういう連携。","voiceIndex":243,"id":"exchange-084"},{"speaker":"たけうち委員","kind":"質問・要望","question":"分かりました。今、報道等で、コロナの影響で、子どもたちというよりは、全体的にようやく十何年かけて減ってきた自殺者が、７月、８月と増える傾向にあるという中で、これからまたコロナによるいろいろな影響で、親御さんがお仕事を失業してしまったとか、また商売があれしたとか、いろいろなことでいろいろな家庭内のごたごたが出てくる中で、自殺者の増加がちょっと懸念されているのです。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":247,"id":"exchange-085"},{"speaker":"横山委員","kind":"確認","question":"２点お伺いしたいと思います。ＮＴＴ東日本による２０１７年１２月の公衆電話に関する調査では、公衆電話を知らない、使ったことがない子どもは合わせて８４.３％いるというようなデータがありまして、ちょっとこの辺りを確認、もし分かれば教えてください。","respondent":"有馬庶務課長","answer":"公衆電話の使い方などというところは、市民科で教えているかどうか分かりません。基本的には家庭でというところになるかと考えています。","voiceIndex":248,"id":"exchange-086"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれども、まもるっちに、今、登録として、ＨＥＡＲＴＳはもともと入っている。ＨＥＡＲＴＳが入っている理由は、やはり教育総合支援センターという区の公的機関だからという理由でよろしいでしょうか。","respondent":"黛生活安全担当課長","answer":"委員ご指摘のとおりです。","voiceIndex":250,"id":"exchange-087"},{"speaker":"筒井委員","kind":"質問","question":"はい、分かりました。ＫＤＤＩと保護者の方の何を登録するのかというのは任意だということなのですけれども、傾向として、保護者の方は大体どのような番号を登録されているのでしょうか。分かる範囲で。","respondent":"黛生活安全担当課長","answer":"大変申し訳ございません。契約に関するところにつきましては、当担当で認知はございません。","voiceIndex":252,"id":"exchange-088"},{"speaker":"安藤委員","kind":"提案","question":"ご説明、質疑も聞きまして、ＨＥＡＲＴＳは登録しているということで、令和５年に新システムに移行すると。令和３年度からいろいろと検討を始めるということなので、非常にタイミング的には、すごくいいタイミングでの具体的な提案なのかというふうに思います。ぜひ検討していただきたいと思います。ですから、やはり区も支援を強めていただきたいと思います。これは意見です。先ほどの質問だけお願いします。","respondent":"矢部教育総合支援センター長","answer":"委員お話のように、大変ありがたい取組みだと思って感謝しているところですが、本区では、重複しますが、市民科の５年生から７年生でカード自体も取り上げて指導しておりますので、支援を強めるという委員のお言葉に当たるかというふうに考えております。","voiceIndex":254,"id":"exchange-089"},{"speaker":"安藤委員","kind":"意見","question":"ぜひこうした区民の方の思いを議会として拝聴する場は貴重ですし、この陳情審査においても非常に有益だと思いますので、意見陳述をぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":257,"id":"exchange-090"},{"speaker":"あべ委員","kind":"質問","question":"私も意見陳述を伺いたいと思います。今の質疑の中で、品川区あるいは区教委としても、一定の連携をしつつ、カードも配布したりということを聞きました。そういった状況であって、なおかつこの陳情が出てきているということは、その背景は何なのかということも含めて、ぜひ今、聞きたくてうずうずしているのですけれども、ぜひ意見陳述をお願いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":258,"id":"exchange-091"},{"speaker":"筒井委員","kind":"意見","question":"私も陳情者の方の直接的なお考えを聞いてみて判断していきたいと考えておりますので、意見陳述に賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":259,"id":"exchange-092"},{"speaker":"あべ委員","kind":"質問・要望","question":"理解できた方が多いということですばらしいと思いました。私はこれだけ区教委がやっている中で、それであったら、この陳情はあえて出てこなかったかと思うのですけれども、理解できた方にぜひ教えていただきたいのですが、では、なぜこの陳情が出てきたということなのでしょうか。そこは理解できた方は、しっかりとご理解ができたからもういいとおっしゃっているわけですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":266,"id":"exchange-093"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今、あべ委員の質問が、仮に答えが分からなくても、ここに出てきている要望は分かりますので、特にそれを分かる必要はないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":267,"id":"exchange-094"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"本日結論を出すでお願いします。趣旨採択でお願いします。２番に関しても、さらに電話をかけやすい環境を作ってほしいということだと思いますので、それは区としても様々模索をしていただきたいという思いで趣旨採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":273,"id":"exchange-095"},{"speaker":"せお委員","kind":"質問・要望","question":"本日結論を出すでお願いします。趣旨採択でお願いします。項目２のフリーダイヤルのほうも、オプションということもありますが、こちらの新しいまもるっちができるということで、そちらのほうでも検討して、今現在のまもるっちではちょっと課題がありますので、新しいまもるっちのほうでも検討していただきたいという思いもありまして、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":274,"id":"exchange-096"},{"speaker":"たけうち委員","kind":"質問・要望","question":"理由としては、お二人と似ていますが、項目１については今もやっていらっしゃるけれども、直接的に学校では配っていますということですが、そこももう一歩、区教委も意識を向けていただきたいという思いと、それから2)については、今すぐにはできないけれども、先ほど、課長からあったとおり、今回新しくまもるっちを変えていく中での検討の１つに加えていただくというお話もいただきましたので、この２つ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":275,"id":"exchange-097"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択を主張したいのですけれども、やっぱり大切な相談機関だということで、区のご説明が答弁の中でありましたが、支援を強めていく必要があると思いますし、こういうときだからこそです。採択をして、議会としてもそういった検討を後押ししていくほうがいいかと思いますので、そういった趣旨で採択を主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":276,"id":"exchange-098"},{"speaker":"筒井委員","kind":"質問・要望","question":"やはり既に区の答弁としては、小中学校に広く配布・周知されているということですけれども、もう一歩、陳情者の方の実感できるぐらいに積極的な周知を行っていただきたいということと、また、ＫＤＤＩと保護者の契約は任意であり、また、チャイルドラインはあくまでも民間だということと、ほかの団体もいらっしゃるので、どの程度優遇するかということ、課題はありますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":277,"id":"exchange-099"},{"speaker":"あべ委員","kind":"質問・要望","question":"電話も令和５年度からということで、そこには期待したいところですけれども、では、それまでの２年間の子どもたちはかけられないのかということで、電話に日常的にアクセスできないお子さんもいらっしゃるでしょうから、これも例えばですけれども、例えば児童センターからこういうものをかけられるとか、何か公共のものを使って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":278,"id":"exchange-100"},{"speaker":"横山委員","kind":"意見","question":"結論を出すで、趣旨採択でお願いします。選択肢が多過ぎますと、子どもたちがどこに相談してよいか混乱してしまう可能性もありますが、相談先は１つではなく複数あって、その中から本人がより話しやすい相手や相談先を選択してアクセスできる環境は必要だというふうに考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":279,"id":"exchange-101"},{"speaker":"安藤委員","kind":"意見","question":"一応会派で相談して態度を決めていますので、採択すべき内容だと思っているのですが、やっぱり全会一致で趣旨採択ということで結論を出していくというのは大きな力になりますので、趣旨採択に変えします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":282,"id":"exchange-102"}]},{"id":"topic-08","title":"令和２年請願第１１号、大学生に返還免除規定を持つ奨学金制度の創設を求める請願","agenda":"令和２年請願第１１号、大学生に返還免除規定を持つ奨学金制度の創設を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"こちらの請願を出されている方にお話を伺ったのですけれども、あと、街頭で署名も集められていたのです。高過ぎる学費の実態は、やっぱりみんなが共通して悩んでいるなと。だから私は理由にならないと思うのですけれども、もう一度、なぜ区がこうした区民の学生に対して支援をしないのか、給付型の奨学金を行わないのか、もう一度お聞かせいただきたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"先ほども申し上げましたように、国や東京都が、また様々な事業者が奨学金制度を設けておりますので、区といたしましては、大学までの奨学金制度を創設する考えはございません。","voiceIndex":290,"id":"exchange-103"},{"speaker":"安藤委員","kind":"質問・要望","question":"区は、高校生をやっていますけれども、大学生に対する支援をする考えはない、支援する必要がないというふうに思っているのか、お聞かせいただきたいと思います。それと、区はやらないと言うのですけれども、東京の中で２３区ほかでも自治体で、こうした施策は実はいっぱいやられています。どのように把握しているのか伺いたいというのが２点です。","respondent":"三ッ橋子育て応援課長","answer":"品川区では、高校生の返還免除制度を始めたばかりです。したがいまして、大学生まで拡大する新創設はございません。他区の状況ですけれども、港区や大田区などが実施しているものと捉えております。","voiceIndex":292,"id":"exchange-104"},{"speaker":"安藤委員","kind":"提案","question":"大学生や専門学生についても、今、アルバイト収入がなくなって生活困窮しているということがあるので、それを受けて、やはり１５万円の給付型奨学金を支給するという補正予算を第３回定例会に提案しているということです。港区も同じく第３回定例会に、国の給付型奨学金制度を基準に、区独自の上乗せを来年度から実施する条例を提案しているということで聞きました。なぜできないのか伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"品川区では、高校生までの返還免除制度を新設して、今、対応しています。こちらの検証なども含めて、今現在のところ、大学生までの奨学金を創設する考えはございません。","voiceIndex":294,"id":"exchange-105"},{"speaker":"安藤委員","kind":"質問・要望","question":"再チャレンジということを言っていた人もいましたけれども、どこが再チャレンジなのかと。実際に品川区にもこうした実態はあるのだということで、当事者が手を差し伸べる行政をと声を上げたわけではないですか。そうしたところであれば、区としてこういう区民の声に応えるべきではないかと思います。品川区としては、こういう区内の大学生に対して手を差し伸べないのでしょうか。伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"令和２年４月から文科省が法律関係を含めて様々な制度を対応しています。したがいまして、国が授業料の減免や奨学金拡大を行っている段階です。区といたしましては、区民を守るという立場は変わりませんが、今後も国や都の動向を注視してまいります。","voiceIndex":296,"id":"exchange-106"},{"speaker":"安藤委員","kind":"質問","question":"人によりますけれども。その中で一人ひとりの方にとっては、しかもコロナの問題もあって、一刻を争う事態なのです。ですから、私が伺ったのは、こうした目の前で実際に困っている方、何とかしてほしいという方に対して、区は手を差し伸べないのでしょうか。区としてやらないのでしょうかということを伺いましたので、もう一度、大学生は支援をしないのでしょうか。伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"大学生を対象といたしました制度につきましては、国で授業料減免や奨学金拡大を行う法律が制定されましたので、東京都や大学をはじめ様々な事業者が奨学金制度を設けております。したがいまして、区といたしましては、大学生までの奨学金を創設する考えはございません。","voiceIndex":298,"id":"exchange-107"},{"speaker":"あべ委員","kind":"質問","question":"今の答弁の中で、国の制度を見ていきたいということがあったのですけれども、国の奨学金制度、３８０万円が上限になっていて、２７０万円から少しずつ給付額が減るという条件になっています。品川区では、品川区の大学生２割を対象としようとすると、一体幾らの世帯年収になってくるのかというのは、どのように試算をされているでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"品川区の大学生２割の世帯年収ですけれども、区といたしましては把握ができません。","voiceIndex":300,"id":"exchange-108"},{"speaker":"あべ委員","kind":"提案","question":"そうしたことはすごく参考になるのではないかと思うのですけれども、先ほどのご答弁の中で、考えていないというご答弁と、それから高校の免除制度が始まったばかりなので、まだだというものと、ちょっとニュアンスが違う２つのご答弁があったと思うのですが、今、品川区としては、高校の制度を見てから検討するということなのか、それとも単に検討していないだけなのか、どちらですか。","respondent":"三ッ橋子育て応援課長","answer":"しかしながら、国や都が、実際には国で授業料減免や奨学金拡大を行う法律等が制定されておりますので、まずは今の段階では、東京都や大学をはじめ、様々な事業者で奨学金制度が創設されている状況を鑑みて、今後の国や都の状況を注視してまいります。","voiceIndex":302,"id":"exchange-109"},{"speaker":"あべ委員","kind":"質問","question":"何年か経たないと分からないという性質のものではないと思いますので、検証するというのであれば、数字が出そろった今、検証を始められたらいいのではないかなというふうに思いますが、いかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"検証につきましては、しかるべきときに検証してまいります。","voiceIndex":304,"id":"exchange-110"},{"speaker":"あべ委員","kind":"質問・要望","question":"すみません、言葉が通じない。しかるべき条件が出そろっているから、それは今ではないですかという話をしておりますが。生活にかかる費用が変わってきますので、一律の数字で設計をすると、その対象は東京の場合は対象にならない世帯が増えてくることが当然に想定されますので、ぜひそこを勘案した上で奨学金制度をもう一度正面から考えていただきたいと思うのですけれども、いかがでしょうか。","respondent":"柏原子ども未来部長","answer":"ただ、こういったお話が出ている、国のほうの動きも出ているというところを考えたときには、その制度に対する近隣の区の動きもありますので、今、これをどう見ていくかというところの段階だと思っていますので、これが政策として、ではどこでやるのだという判断は。","voiceIndex":306,"id":"exchange-111"},{"speaker":"あべ委員","kind":"質問・要望","question":"ですので、これがすぐにできるとは実はあまり思っていないのですけれども、しかし、少なくともかなり性格の違う高校生の制度を見た上で大学生について考えるというのは、私はちょっと順番としてはどうかなと。そうした面では、ぜひ前向きな検討を、しかも高校の条件とは違った視点でぜひ検討していただきたいと、これは最後に要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":308,"id":"exchange-112"},{"speaker":"安藤委員","kind":"質問","question":"今回、コロナ感染の影響でということもやっぱり含まれていると思うのですけれども、そういったこともあって、他区などでもいろいろと動きもあると思うのです。品川区としては、大学生、区内の学生、専門学生などについて、こういうアルバイト収入がなくなったとか、あるいは退学せざるを得ないですとか、そういう学生の今の困窮実態はつかんでいらっしゃるのか伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"特に今の段階では、学生の困窮状態については把握しておりません。","voiceIndex":309,"id":"exchange-113"},{"speaker":"安藤委員","kind":"質問・要望","question":"しかも、そこに３桁を超える方々の署名も添えられているというようなところをまず認めていただいた上で、制度設計する上でも学生が困っているのだという実態は、少なくともまずつかんでいただくことは絶対に必要だと思うので、それをつかんでいませんということで終わらせるというのは、あまりにも自治体としてはどうか、所管としてはどうなのかというふうに思いますので。","respondent":"柏原子ども未来部長","answer":"ただ、限られた条件の中でやっていかなくてはいけないという情勢の中で、コロナ禍だから、では大学生のこのことに対してすぐ打ち出しができるかというと、いろいろなところの政策との兼ね合いの中で、例えば区民の方に給付を始めました応援給付金。","voiceIndex":312,"id":"exchange-114"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。経済的にもなかなか大変だったので、いろいろと模索をしながらやってきました。これからも自民党として国政の中でも制度改革というのも非常に進めていますので、そこにぜひ期待をしていただいて、より多くの学生を救っていただきたいというふうに思っていますので、まずはやはり国の動向を引き続き見ていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":315,"id":"exchange-115"},{"speaker":"せお委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。国の動きもありますし、先ほどもありましたように、コロナ禍ですので、やっぱり区も限られた財政というところで、やはり優先順位は必要だと考えています。ただ、区の大学生に関する実態の調査であったりとか、そういったところはやっていただきたいという要望はありますが、こちらに関しては不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":316,"id":"exchange-116"},{"speaker":"たけうち委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。公明党は、党として国のほうで給付型の実現を含め、またこれから拡充を含め動いていくということをしっかりとお約束を私がするのもあれですけれども、する中で、私も親の立場でつい最近まで２人同時に大学に通わせて、非常に大変だ、なぜこのように高いのだろうと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":317,"id":"exchange-117"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択を主張したいのですが、根本的には、先ほどもいいましたけれども、お金のあるなしで未来がある若者が学べないというような社会でいいのかというのが、どのステージでも問われていると思います。区としてできることを早急にやっていただきたいというふうに思いますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":318,"id":"exchange-118"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。港区、大田区もそうしたことを受けてか給付金制度を進めようとしておりますし、予算の制約も考えなくてはいけないとは思いますけれども、やはりここはコロナの収束するまで緊急的かつ期間限定でもいいので、ぜひこうした給付金、奨学金制度の創設に前向きな検討をしていただきたいという理由で、採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":319,"id":"exchange-119"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日結論を出すということで、採択と考えております。なおかつ、先ほども伺っていますと、国もこれからさらに充実させていくということですので、補う形で設計していれば、国が充実すれば、その分だけ自治体の負担も減ってくるであろうということも考えられますので、そうすると、つなぎとしての効果も発揮できるだろうというふうに考えます。それも併せて実態把握に努めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":320,"id":"exchange-120"},{"speaker":"横山委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。は区の新制度について、成果、課題などの検証や分析を実施していただきたいというふうに考えています。今後の高等教育の修学支援の状況については、引き続き、国の新制度ですとか、国の動向などを注視していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":321,"id":"exchange-121"}]},{"id":"topic-09","title":"令和２年陳情第４７号、離婚等のこども養育支援にかかる陳情","agenda":"令和２年陳情第４７号、離婚等のこども養育支援にかかる陳情","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"その件数のうち、何％が解決したのでしょうか。それは答えられますか。","respondent":"三ッ橋子育て応援課長","answer":"相談につきましては、きちんと対応して、面会交流や養育費の問題など、様々、公益社団法人に紹介しておりますので、基本的には１００％と考えております。","voiceIndex":331,"id":"exchange-122"},{"speaker":"あべ委員","kind":"質問","question":"１００％解決が図られているというご答弁でよろしいのですか。","respondent":"三ッ橋子育て応援課長","answer":"解決と申しますのは、それぞれの方の答えというものも非常に難しい問題があります。ひとり親家庭になって様々な問題を抱えている方、そして面会交流がしたいと思ってなかなかできない方、様々な問題があるのは承知しております。","voiceIndex":333,"id":"exchange-123"},{"speaker":"あべ委員","kind":"質問","question":"それはフィードバックを受けているのですか。つまり、区としては、面会交流についてご相談された方が、その後どうなっているのか、ちゃんと満足いける状態なのか、それとも課題があるのかということを区として把握されているのでしょうか。それなしに、さっきおっしゃっていた子どもたちの最善の利益というのは普通にできないのではないかと思いますけれども、いかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"しかしながら、私が問題解決は図られているというふうに申し上げましたのは、区といたしましては、相談を受けて、ご紹介をして、そこの次の段階で何らかの対応をしているということはできますので、その意味で図られていると申し上げました。","voiceIndex":335,"id":"exchange-124"},{"speaker":"あべ委員","kind":"質問","question":"とすると、課長がおっしゃられる問題解決が図られているというのは、相談を受けて次の機関に紹介したら、それでもう一件落着という意味なのでしょうか。そのようにしか今のお話は聞こえないのですけれども、それでは区民の方々が本当に困っているのか、次にもう１回相談が来ないと、紹介した後のことは追えていないということでよろしいのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"様々な案件がありますので、面会交流は、お父さん、お母さんの問題、そしてそれに伴うお子さんの問題、様々なことがありますので、区としては、もちろん問題は解決が図られていると把握はしておりますけれども、しかしながら、委員がおっしゃるように、様々な問題がある。","voiceIndex":337,"id":"exchange-125"},{"speaker":"あべ委員","kind":"質問","question":"すみません、質問が重なっているのではなくて、答弁がその場所から動いていないだけだと思うので何度も聞かせていただきます。問題解決が図られているという最初のご答弁だったわけです。でも、区としては、もう全て問題解決しているという認識なのですか。もう１回聞きます。","respondent":"三ッ橋子育て応援課長","answer":"したがいまして、もちろん区としても面会交流の支援はしていきたいと考えておりますけれども、この案件につきましては、本当に難しい問題で、国や都の動向を注視しています。","voiceIndex":339,"id":"exchange-126"},{"speaker":"あべ委員","kind":"質問","question":"１００％は目指しているけれども、解決は１００％ではないというところまでは区として認識はされているということ、これはいいですか。それが１点。それから国や都が動かないと、品川区としてはこの問題に動かないという意味でよろしいのですか。つまり、品川区としてはこの問題には直接的には関わらないということでいいのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"何にしろ、子どものことをきちんと大事に考えていかなければならないと考えています。１点補足ですけれども、相談を受け付けて、その後、支援につなげていく、ご紹介していく、その後、またもちろんアフターケアもしておりますので、ご相談に応じて対応はしております。","voiceIndex":341,"id":"exchange-127"},{"speaker":"あべ委員","kind":"質問・要望","question":"先行事例がある以上、自治体としていろいろと悩みながらどこまでできる、どこまでできると考えている自治体がある以上、品川区としても、いや、それは都に投げましたとか、あるいは国が動くのを見ていますというだけではなくて、ぜひこの問題を区としてできることを考えていただきたいと思うのですけれども、その姿勢自体はあるのですか、ないのですか。","respondent":"三ッ橋子育て応援課長","answer":"先ほど申し上げましたように、実際に法律等も動いていく可能性が高いと考えています。その中で区として何ができるのか、それは考えていかなければいけない問題だと考えています。","voiceIndex":343,"id":"exchange-128"},{"speaker":"あべ委員","kind":"質問","question":"考えていかなければいけないというのは、今はまだ考えていないけれども、これから考えるということですか。今は何を考えていますか。","respondent":"三ッ橋子育て応援課長","answer":"先ほど答弁いたしましたように、区といたしましては、引き続き、国や都の動向は注視していきます。そしてまた、法律の状況もいろいろと把握していきながら、区として何ができるのか、できないのか、どの部分に対応していくのかなどを含めて考えていくことが大事だと考えています。","voiceIndex":345,"id":"exchange-129"},{"speaker":"あべ委員","kind":"質問","question":"部長、今のご答弁でいいのですか。いろいろと面会交流あるいは子どもの養育については、たくさんの課題があることまでは、多分区としても認識されていると思いますが、品川区としては、今は何もしないという状況なのでしょうか。","respondent":"柏原子ども未来部長","answer":"国等々の動きがある中で、区がそこの中でどういう役割を持たなくてはいけないのか、それはケースごとによって、入り方であったりとか、それから、その部分だけの課題だけではなくて、別の部分にも課題があったりということが幅広いというところもありますので。","voiceIndex":347,"id":"exchange-130"},{"speaker":"筒井委員","kind":"質問","question":"実際、東京都とセンターに振られているということなのですけれども、ということは、実際にご相談があったということだと思うのですが、今までのそうした件数や、それが多いのか少ないのか、区としてはどのような実感を得ているのかをお聞きしたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"件数については控えさせていただきたいと思いますが、全て、もちろん状況に応じて面会交流などもご紹介しております。","voiceIndex":350,"id":"exchange-131"},{"speaker":"筒井委員","kind":"質問","question":"実際、この事業をやるかやらないかに当たっては、需要があるのかというのは把握しておかなければいけないと思っているのですけれども、それほど頻度的に多いものなのかということを、具体的な件数というよりは、相談は本当に多いのかというか、感触というか、その辺りはどうなのですか。","respondent":"三ッ橋子育て応援課長","answer":"様々な相談がありますので、特に面会交流をしたいとか、今回の陳情に関係するような相談については、多い少ないというのもなかなか難しい答えになるのですけれども、もちろん面会交流をしたいというご相談はあります。","voiceIndex":352,"id":"exchange-132"},{"speaker":"筒井委員","kind":"質問","question":"小平市とか武蔵野市とかは、実際に東京都の取組みとかを自身のホームページで上げているので、そうした周知とか広報の改善をしてほしいのですけれども、その点、いかがお考えでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"様々な状況を勘案しながら、ご相談したい方が探せないというのは、さすがによくないとは思います。ただし、この案件は非常に慎重に進めなければ、単純な事務的な作業とかとは全く違いますので、その部分に関しては慎重に検討させていただきたいと考えています。","voiceIndex":354,"id":"exchange-133"},{"speaker":"たけうち委員","kind":"質問","question":"これはまず周知でしょう。それから、さっき件数云々とおっしゃっていたけれども、事務事業概要の５６ページに、家庭福祉とあって、ここで家庭相談で、ここを見ると、養育の相談で何件、何件と件数が出ているではないですか。なおかつ今、区でもやっているわけではないですか。ここはそういう視点でお答えしてもらわないと、我々もせっかくこれを審査しているのだからと思うのだけれども、どうでしょうか。","respondent":"柏原子ども未来部長","answer":"件数等々についても、そういった視点のところで慎重なところでの答弁が行き違いのようになっていますけれども、お話しできる内容については、きちんと審議といいますか、議論ができる内容での答弁をさせていただきたいと思います。申し訳ございませんでした。","voiceIndex":356,"id":"exchange-134"},{"speaker":"安藤委員","kind":"質問","question":"陳情にも紹介されていますけれども、子どもの権利条約の第９条というところです。「児童がその父母の意思に反してその父母から分離されないことを確保する」というような、子どもが両親、片方ではなくて両親と交流するという権利について書いているわけですけれども、ここについて品川区としては、どう認識されているのか伺いたいというふうに思います。２点伺います。","respondent":"三ッ橋子育て応援課長","answer":"面会交流につきましては、先ほど申し上げましたように、子どもたちにとって最善の方法をとるのが一番いいと思っているところです。明石市や港区に対しては、やはり先進的な事例だと捉えておりますので、それらはいろいろと勉強させていただきたいと考えています。","voiceIndex":358,"id":"exchange-135"},{"speaker":"せお委員","kind":"質問","question":"１点だけお伺いしたいのですが、養育費に関してですけれども、東京都が今年度の予算で養育費確保支援事業という「ひとり親家庭の養育費の安定した取得に向け、民間保証会社と連携し、養育費の立替保証を実施する区市町村を支援する」とあるのですけれども、こちらの事業については何か検討されていることはありますでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"今年度から東京都が始めた事業と捉えておりまして、区といたしましても、様々検討、勉強してまいりたいと考えています。","voiceIndex":360,"id":"exchange-136"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれども、２３区では、実際に面会交流支援をやられているのは、港区だけという理解でよろしいでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"私はそう捉えております。","voiceIndex":362,"id":"exchange-137"},{"speaker":"芹澤副委員長","kind":"意見","question":"継続でお願いいたします。会派からも養育費等を行政のほうに働きかけてきましたけれども、国と都の動きが今非常に活発になってきていると。ただ、国と都がやればいいだけの話ではなくて、今話し合ったように、区の関わりも前提になってきているのかと思いますので、引き続きこちらは議論していければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":365,"id":"exchange-138"},{"speaker":"せお委員","kind":"質問・要望","question":"こちらは継続でお願いいたします。ご家庭それぞれの事情とかも第三者が理解するのはすごく難しい部分もありますし、あと、国の法改正でしたりとか、先ほど質問いたしました都の事業に関しても、こちらも動きがあるということで、そちらを注視していくべきだと私も思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":366,"id":"exchange-139"},{"speaker":"安藤委員","kind":"質問・要望","question":"面会交流支援というのは、そういったところに重要な支援だと思いますので、ぜひ品川区でも先進事例だという話もありましたけれども、検討・研究を進めて実施できるところから実施していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":368,"id":"exchange-140"},{"speaker":"筒井委員","kind":"質問・要望","question":"国・東京都の動きもこれからあるかもしれませんし、また、離婚という事由の性質上、基礎自治体でやっていくべきものなのか、それとも東京都という広域である程度やっていくべきものなのかということは、しっかりと今後も深めていかなくてはいけないのかと考えています。ただ、案内とか周知の点、現行の東京都の制度がありますので、そこはしっかりとご相談者にお伝えをしていっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":369,"id":"exchange-141"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いしたいと思います。とはいえ、今のお話を伺っていると、どうも継続のほうが多そうな感じで非常に懸念をしているのですけれども、もしこの結論が長くなるということがあっても、その時間をむだにせずに、ぜひ、特に所管課のほうで、この問題について、もう一度しっかりと把握をして、深く法制度、それから、これまでの品川区での議論も頭に入れていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":370,"id":"exchange-142"},{"speaker":"横山委員","kind":"質問・要望","question":"継続でお願いします。その間、現在もＦＰＩＣ、家庭問題情報センターのパンフレットを課の前のところに置いていただいているというのも、私、この間、確認もしてきたのですけれども、今やっていただいている周知ですとか、または都やＦＰＩＣの専門家に適切につないでいただくなど、相談者と一緒に考えて、よりよい解決に向けた情報提供を必要な方にお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":371,"id":"exchange-143"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5012#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":94514,"voices":377}},{"id":"r02-20200923-5","meetingId":"r02-cm09","date":"2020年9月23日","dateIso":"2020-09-23","committee":"総務委員会","time":"午前１０時００分～午後 ０時００分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６２号議案 第二戸越幹線整備工事（北品川立坑）請負契約の変更","agenda":"第６２号議案 第二戸越幹線整備工事（北品川立坑）請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"資料の２ページ目の変更理由ですけれども、その他のところで、新型コロナウイルス感染拡大防止に向けたとあります。工事の一時中止というのは、どのような趣旨なのか。いわゆる感染者がいる、それとも、感染予防なのか。いずれにしても、工事の一時中止によるというのは、どのような事情なのか、そこだけご説明いただきたいと思います。","respondent":"松本河川下水道課長","answer":"その他の新型コロナウイルス感染拡大防止に伴う一時中止ですが、これは、請負者から感染予防ということで、緊急事態宣言の間、４月２７日から５月８日にかけて、平日の６日間、中止したものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"提案","question":"関連して、今回、金額が大きいので議案として提案されたのだと思います。この新型コロナウイルス感染症の対応は、どの工事でも共通してくることだと思うのです。金額の大小で議案になるかどうかは別にして、ほかの公共工事もこのような対応というか、追加の費用を支出しているという認識でよろしいのでしょうか。","respondent":"東野経理課長","answer":"新型コロナウイルス感染症に対する工事請負契約の変更なのですけれども、現在、感染症対策のみで金額の変更をしている案件はございません。工事の一時中止等に伴いまして、工期の延長等の契約変更の措置は何件かしています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"今の質問についてお聞かせ願いたいのですが、今回、感染拡大防止に向けて、一時、工事が中断したということです。現場維持経費等と記載されているのですが、この費用は、おおむねどれぐらいの額になっているのですか。その分をお客様に請求しているという話を聞いたことがないし、新聞でもそういった記事を読んだことがないのですが、なぜこのようなことがあるのですか。それについてお聞かせください。","respondent":"松本河川下水道課長","answer":"この経費の計算につきましては、今回、この工事が東京都下水道局の請負事業になりますので、下水道局の変更ガイドラインに計算方法があり、それに則って計算し、４０万円を算出しています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"下水道局は公共の機関です。要は、公共機関はこのように上乗せする。それで、他方、民間ではしない。額は少ないですが、やはりこのようなことを行うならば、私は日本全国にわたって、建設業者および現場の業者にこのようなことをきちんとアピールしていくべきではないかと思います。意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"今、(5)のその他のところは約４０万円ということで、約８億円の契約について、約２億円の増額ということですので、つまりは(1)から(4)が大きいということです。ごめんなさい。私、こういうことが全く分からないので、ざっくりで結構です。費用がどれにどれくらい、また一番多くかかるのはどれだったのかということを教えてください。","respondent":"松本河川下水道課長","answer":"変更金額についてです。内訳につきましては、(1)の立坑工が、約９,０００万円の変更となっています。続きまして、(2)の付帯工が、約７０万円の変更です。(3)の仮設工が、約６,７００万円の変更です。(4)の共通仮設費が、約１,７００万円の変更です。","voiceIndex":13,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"すみません。一遍に聞けばよかったのですけれども、これらの変更が必要になった理由も、簡単で結構ですので、教えていただけますか。","respondent":"松本河川下水道課長","answer":"設計段階では、平成２８年度のボーリング調査の地下水から処分量を算定しておりましたが、請負者決定後、ボーリング調査を実施したところ、設計段階より地下水が高かったことから、土砂と泥土の処分量を変更したものです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"つまり、土砂と泥土では、処分の金額が変わってくるという理解でよろしいでしょうかというのが１点です。最初のところと、あとは要望ですけれども、もし何か一言あれば、伺いたいと思います。","respondent":"松本河川下水道課長","answer":"今、委員のご質問のとおり、土砂と泥土の処分先によって金額が変わるものです。理由の掲載につきましては、今後、検討していきたいと考えています。","voiceIndex":17,"id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"意見","question":"変更理由の４番目、共通仮設費は、近隣構造物の計測管理の追加等ということで、先ほど、課長から１,７００万円の変更という話しがありました。これは、掘削をするに当たって、近隣の構造物に恐らく影響が出たから、改めて計測管理をやると思うのです。具体的に、どのような計測管理をやるのか、施工するのかどうか。その１点だけお願いいたします。","respondent":"松本河川下水道課長","answer":"ＪＲにつきましては、高架にターゲットという測量のポイントを設置いたしまして、その変位を見てあります。首都高につきましては、傾斜計というものを設置しまして、地盤が変位するか、しないかということを測ってあります。","voiceIndex":20,"id":"exchange-008"}]},{"id":"topic-02","title":"令和２年請願第９号 固定資産税及び都市計画税の軽減措置の継続","agenda":"令和２年請願第９号 固定資産税及び都市計画税の軽減措置の継続","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"３項目にわたって、来年度以降も継続することという願意ですけれども、小規模事業者の経営が苦しくなっているので、必要な措置だと考えています。１点だけ伺いたいのですけれども、品川区としては、この３項目について、東京都にどのように要望しているのか。そのスタンスだけご説明いただきたいと思います。","respondent":"伊東税務課長","answer":"区のほうにも、軽減措置ということで、要望等が上がっているところです。スタンス的には、我々も区民の暮らしのためにそのような軽減措置を継続したほうがいいなと思っているところですが、具体的にどの場面、どのような形で都にということでは、今のところ考えておりません。","voiceIndex":38,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"こうやって毎年、軽減措置について議論するわけですが、もう３０年続いているわけです。３０年以上続いているならば、そうすべきだと思うのですが、実際、区長会、副区長会では、都にどのような要望をしているのか。都ではできないのか、やってくれないのか、その辺について、少しご見解をお聞かせください。たしか毎年、区長会、副区長会でも要望していると思うのですが、その辺は、どうなのでしょう。","respondent":"桑村副区長","answer":"そのことも含めて、制度的なものについての都と区の感覚の違いがありますので、これがいい制度だからといって、区長会も副区長会もどんどん進めるべきだとはなかなかならないのではないかなと思っています。","voiceIndex":40,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"毎年これを見ていて、都内に高層マンション、タワーマンションがたくさん建って、固定資産税が膨大にと言ったら変ですけれども、地方と比べたら圧倒的に地価も上がって、固定資産税も増えているのです。ですが、それに対して区民に還元されているのか、２３区にきちんと還元できているのか。ぜひ今後も区長会、副区長会で、また、財政課、企画調整課のほうで、都にしっかり進言していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-011"},{"speaker":"湯澤委員","kind":"質問","question":"１点お聞きしたいのですけれども、この軽減措置の３つの項目について、品川区においては、軽減措置創設以来、適用を受けている件数や金額の増減の推移が、どうなっているか教えていただけますでしょうか。","respondent":"伊東税務課長","answer":"影響額というところで、今回、令和元年度の数字は資料にお示ししていますけれども、昨年度と比較してみますと、影響額は、小規模住宅用地に対する軽減措置に関しては、件数的には６万件というところですが、８,０００万円ほど増加しています。軽減を受けているということです。","voiceIndex":44,"id":"exchange-012"},{"speaker":"湯澤委員","kind":"意見","question":"増加したり、少し減少しているところもあるかもしれませんけれども、特に今年は新型コロナウイルス感染症の影響で、区民や区内事業者でダメージを受けているところはかなりあるかと思います。そういった方々のためにも、この軽減措置は、ぜひ今年もしていくべきではないかなと思っている次第です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-013"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１点だけ確認させていただきたいのですが、２番目の小規模非住宅用地に対する減免措置。この減免を受ける場合には、年内に申請が必要とあります。この対象者には、品川区、東京都のどちらが、この減免措置について案内されているのでしょうか。","respondent":"伊東税務課長","answer":"新規の方は、年内に申請が求められているです。それで、直接的には行っていないかもしれませんけれども、様々な媒体、主税局で発行しておりますガイドブックや、先ほど言ったホームページのような方法で周知が図られていると認識しております。","voiceIndex":48,"id":"exchange-014"},{"speaker":"新妻副委員長","kind":"意見","question":"対象の方は、そのようなところを意識されているので、情報は知っているかと思います。やはり、知らなかったということがないようにする必要があると思いましたので、該当の方にしっかりと周知できるように、すでに周知されているということであれば、安心しました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-015"}]},{"id":"topic-03","title":"令和２年陳情第４８号 子どもが健やかに育つための陳情（陳情項目３）","agenda":"令和２年陳情第４８号 子どもが健やかに育つための陳情（陳情項目３）","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"参加はたくさんしてほしいけれども、定員は何分の１とせざるを得ない。だから、そういう視点からも、現状は分かりましたけれども、今後のことを考えると、このようなことは全然考えられないものなのでしょうか。新型コロナウイルス感染症が終息しても、必ず次を想定しておくというのは、もう世界の流れではないかなと思うのですが、その点についてお考えがあったら伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"それと、新型コロナウイルス感染症対策としての緊急の課題ですが、できるところからやってみて、またお声を聞きながら、進めていけるところは進めてまいりたいと考えております。","voiceIndex":66,"id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"確かに、一気に進むかどうかは、私もオンライン会議をやるときや、オンライン講習会をやるときには、検討しなければいけないことがたくさんあるのです。それは分かるのですけれども、方向性としては、やはりオンラインのほうを考えていくべきではないかと思うのです。今、方向性の検討の項目の中に、例えばそのようなことも検討される余地はあると理解してよろしいでしょうか。","respondent":"島袋人権啓発課長","answer":"今後、講習会等々を開催していく予定で、今進めているところです。その中では、リモートでの参加はないのですけれども、アンケート等で区民の方たちの意見等も取れるかと思いますので、そちらを注視してまいりたいと考えているところです。","voiceIndex":68,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"アンケートもすごくいい必要な手法だと思いますし、オンラインなどは余り得意ではなくて、紙で書きたいという方がいらっしゃるのも確かですし、先ほどの繰り返しになりますけれども、生活者ネットワークとしては、本当は会って顔を合わせてやるべきだという考えなのです。だけど、やはりいろいろな人の参加を募る。繰り返しになってしまいますので、これは要望にとどめたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"冒頭の説明は、きゅりあん４階の特別講習室にＷｉ－Ｆｉがあって、その利用料金が５割減額になるので、そちらを利用していただきたいということでした。私も区民集会場を様々利用しますが、１時間で１回切れますが、どこもＷｉ－Ｆｉがつながります。今、大井町駅前にも整備しているわけですから、そのような方向で、ぜひとも考え直していただきたいと思うのですけれども、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"そちらの検討もせざるを得ないかなということもありますし、確かに公共施設におけるＷｉ－Ｆｉの環境整備はとても必要だと思います。","voiceIndex":71,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"この議論をすると、無料であったものが有料化になってしまうような感じがして、それはよくないと思うのです。これは進めるべきではないと申し上げたいと思います。いずれにしても、ほかの区が有料の中、品川区は男女共同参画の事業を進めるに当たって、会議室を無料で提供しているというのは、とてもよいことだと思います。ぜひとも有料にするのはやめていただきたいのですけれども、いかがでしょうか。","respondent":"榎本総務部長","answer":"今、男女共同参画センターには会議室が１つしかないのです。その中で、区の事業としていろいろな講座をやる。その使っていない部分を団体が使うという形になっていまして、その調整をしているところです。","voiceIndex":73,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、登録団体が減っているというお話がありましたけれども、それは男女共同参画センターの事業をより拡大していって、区民に身近な存在になれば、また増えてくるのかなと思います。改めて、やはりＷｉ－Ｆｉ整備は当然進めていくべきだと思いますので、検討していただきたいのと、今まで空いているところを無料で貸していたのを有料化することなく、今までどおりでお願いしたいと申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、お話をいろいろ聞いていたのですが、確かに将来的にはこういう環境になっていくということは世界の流れだと思います。ただ、お話を聞いていて、様々な貸出環境がある中で、こちらはどうするのだ、有料化、無料化と、様々なこともあります。そこは重々加味してやっていただきたいと思います。意見だけ述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-022"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"現状の確認をします。先ほど、登録団体も減ってきているということでありましたが、現状、どれくらいの登録団体があって、その団体の方からのＷｉ－Ｆｉのご要望の声や、どれくらいお部屋が活用されているのか。コロナ禍でありますので、かなり激減していると思うのですけれども、交流室、資料コーナー等がどれだけ活用されているのかという現状をお聞かせいただきたいと思います。","respondent":"島袋人権啓発課長","answer":"交流室、資料コーナーは出入りがありますので、何人というお示しはできないのですけれども、出入り口のところには、記入していただくように記載名簿を出しています。このところは、若干減っているような傾向が見られるようです。","voiceIndex":78,"id":"exchange-023"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"４９団体のうち、約半数は実体があるというか、活動されているということが確認されました。今、課長のご説明では、現状は難しいというお話もありましたけれども、きゅりあんの改修等に合わせて、また、フリーＷｉ－Ｆｉの設置なのか、何か別の形なのか、ネット環境が整備されるということにおいては、時代の流れでありますので、ぜひそこはご検討を頂きたいなと思いますが、再度、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"その間、やはりＷｉ－Ｆｉ環境を整備していくことも、その中の検討課題の１つとして考えていくことが重要かと思いますし、合わせて、男女共同参画センターの様々な貸会議室の在り方等も検討していく必要があるのではないかと考えているところです。","voiceIndex":80,"id":"exchange-024"},{"speaker":"新妻副委員長","kind":"質問","question":"結論を出すです。不採択です。先ほど質問もさせていただきました。今後、課題をしっかり検討いただき、きゅりあんの改修の時期に合わせてご検討していただくということで、今回の陳情に関しては不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-025"},{"speaker":"中塚委員","kind":"意見","question":"結論を出すということと、採択でお願いします。やはり陳情要旨にもあるとおり、男女共同参画センターにＷｉ－Ｆｉを設置すべきだと私も思いますので、採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"結論を出すということと、不採択でお願いいたします。やはり、今お話を聞いていて、貸出は区民に対して平等に行う。やはりそれが原理原則だと思いますので、そういうものが様々整った上で、区はこれからも改善云々があるのでしょうから、そのときにまたＷｉ－Ｆｉ設置等を考えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-027"},{"speaker":"吉田委員","kind":"意見","question":"本日結論を出すということで、採択でお願いいたします。いろいろ課題があることは私も承知しております。大規模改修のときには、きっとフリーＷｉ－Ｆｉという形になっていくのだろうなと思います。いろいろな条件整備が必要なことは理解いたします。ただ、条件整備は、区や議会が考えるべきことです。採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-028"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"そのためにあるべきなのに、例えば、国や都の意向で自治体の方向性が決まってしまう仕組みだといつも感じるのです。あのようなものは本当に最たるものだなと思うのだけれども、やはりそういう流れの中で、区としては自立して地方自治を考えていくという姿勢が必要なのではないのかなと、大雑把な質問になってしまいましたけれども、その辺のところを品川区はどのように考えているのか、伺いたいと思います。","respondent":"品川財政課長","answer":"例えば、木造密集の関係や木密不燃化１０年プロジェクトなどがありましたけれども、それについても、大枠は独自で決めて動いているというところはあったのですが、やはり、どのようにしようかという細かい内容は、各区、各自治体などにヒアリングをし。","voiceIndex":96,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"使える補助金や制度をこちらが主体的に使うことはとてもいいことだと思うのです。ただ、特に財政調整の仕組みを見ても、都区協議会で合意した上での条例改正とはいえ、まだまだ２３区独自施策、特に児童相談所すら議論に時間がかかっていると思うので、主体的に東京都との交渉に当たっていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"国・都補助金の概要です。もし聞き漏れていたら申し訳ないのですが、再度になりますが、少し質問させてください。補助金申請事務の流れなのですが、大体何月頃、このようなことがあって、ヒアリングを何回ぐらい行うのか。そして、国や都に出向くと思うのですが、どの部署に行くのですか。各所管ごとに行くのか。その辺も教えてください。","respondent":"品川財政課長","answer":"基本的には、大体１月から２月、４月ぐらいまでのもあるのですけれども、その辺で交付決定がされて、その後、何回かヒアリング等も受け、おおむね夏を過ぎた頃から実績調査等をやるという動きで、最終的に、年度末ぐらいに交付を受けるというものもあります。","voiceIndex":99,"id":"exchange-031"},{"speaker":"須貝委員","kind":"提案","question":"ただ、このような流れを見ると、やはり２３区は国や都に監視されているみたいで、きちんとやらなければお金を交付しないよ、きちんとやれば交付するよ、それもいいかげんな提案だったらだめだよと、逆に国の施策、事業に対して、我々も言いたいことが山ほどあるけれども、本当にこういう国や都の補助金の概要を見ると、先ほどもありましたけれども、じくじたる思いというか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません。私も初歩的な質問で恥ずかしいのですけれども、一番最初に事業計画書の提出があって、その事業計画に対してヒアリング・調査が１回行われるわけです。そのやりとりは、審査選考に至る事業計画書になるまでに、何回ぐらいやりとりがあるのかということ。それで、ここで１回審査に入りますよという内示なのですかね。その辺のことを教えていただきたいと思います。","respondent":"品川財政課長","answer":"それで、最終的に交付決定されるという流れになっていると思います。ですので、回数は何回ですかという質問に、なかなか具体的にお答えすることはできないのですけれども、そのような状況です。","voiceIndex":102,"id":"exchange-033"},{"speaker":"吉田委員","kind":"確認","question":"だから、そのようなやりとりがあるのかなと思ったのです。つまり、大体内示が出れば、何か微修正はあるにしろ交付決定という理解でよろしいでしょうか。１団体が国からの補助金をもらうことに比べたら、これは割とルーティン作業と言っては失礼かもしれませんけれども、そのような形になっていると理解してよろしいでしょうか。その辺だけ確認させてください。","respondent":"品川財政課長","answer":"具体的な金額の調整等は、その後の交付申請書の審査等で若干微調整があるというのが大きな流れかとは思います。これもケース・バイ・ケースでいろいろ違うとは思いますので、そこのところはご了承いただきたいと思います。","voiceIndex":104,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"この補助金申請事務の流れというのは、前年度に同様の補助金が出たのが例になっていますけれども、例えば、新しい制度が始まって、こういう事業に補助金を出すとなったときも、大体同じような感じなのか、それとも、始めの年は実績報告が出せないわけですから、何か手間がかかるのか、その辺のことも教えてください。","respondent":"品川財政課長","answer":"そのような形になりますと、国がスケジュールを組みまして、どのような流れになるかというところは、申し訳ございません。これもお答えになっていないかもしれないですけれども、ケース・バイ・ケースで流れは違ってくるかなと考えています。","voiceIndex":106,"id":"exchange-035"},{"speaker":"吉田委員","kind":"確認","question":"初年度でも、内示が出れば、大体大丈夫という感じですか。ケース・バイ・ケースだろうとは思いますけれども、おおよそということで理解していいか、少し確認させてください。","respondent":"品川財政課長","answer":"当然、事業計画という形で提出して、その計画の内容等を審査して内示を出しますので、基本的にはここで補助金の対象になるか、ならないかというところは決まるかと思います。しかし、何回も言いますけれども、これもケース・バイ・ケースでいろいろかとは思います。","voiceIndex":108,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"いろいろありがとうございました。今のお話を伺っていると、国や都が出す補助金だと、その意向に合わせて事業計画を出すみたいになっていくのだと思いますけれども、できることなら、その辺に区としての創意工夫をきちんと盛り込んだ形で、ぜひ出る補助金はきちんと活用していただけたらなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-037"},{"speaker":"須貝委員","kind":"質問","question":"すみません。この事務の流れを見ていて、民間会社なら、足しげく担当者に会いに行ったり、折半というか、個々にお金を出し合って食事会をしたりして、その人の気持ちを聞く、また、こちらから訴える気持ちを分かってもらうには、やはり会って話をしたり、聞いてもらうということも大事ではないですか。そのようなこともされるのか。それから、理不尽な対応もあるのか。","respondent":"品川財政課長","answer":"補助金制度として、２分の１まで出します、４分の１まで出しますとしっかりと書いてはあるのですけれども、実際にそこまで交付しているか、交付していないかというのは、やはり微妙なところがあります。","voiceIndex":111,"id":"exchange-038"},{"speaker":"須貝委員","kind":"意見","question":"本当にこれだと民間会社のサラリーマンの方が、会社でお得意先と対応しているような現状だと思います。国では忖度という話が出ていますので、私が思っていた以上に予算を持ってくる、補助金を持ってくるというのは大変なのだなと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-039"}]},{"id":"topic-05","title":"今定例会の一般質問に関わる所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","agenda":"今定例会の一般質問に関わる所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"実際、依命通達を自分でコピーして持ってきたのですけれども、８月３日に副区長が各部長宛てに出した依命通達です。具体的な質問は、原則１０％のマイナスシーリングを各部局にかけるということで、その趣旨、理由を質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2178#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":30977,"voices":131}},{"id":"r02-20200924-6","meetingId":"r02-cm09","date":"2020年9月24日","dateIso":"2020-09-24","committee":"区民委員会","time":"午前１０時００分～午後 ３時１６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"しながわ活力応援給付金事業の進捗状況","agenda":"しながわ活力応援給付金事業の進捗状況","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"それで伺いたい進捗状況なのですけれども、特別定額給付金の申請割合、最終的に９９.２％まで申請割合がいったと。そちらのほうお伺いをすれば、最終的に特別定額給付金のときの期間に対する申請率の割合、これが活力給付金のときに今伸びている、その申請率の割合で最終的にどれぐらい追いつくかという部分が見えてくると思うので、もしお分かりになれば、約５週間たった時点での申請率をお教えください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-001"},{"speaker":"くにば委員","kind":"質問・要望","question":"すみません。所管が違うということで失礼いたしました。それで現在当初予想と比べて、おおむね順調なのかどうかという、まずそのざっくりな部分を伺いたいです。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"今現在も、約５００件近くの申請書が毎日届いているという状況の中で、申請率をなるべく１００％にするための努力としまして、広報しながわ等での周知もしているところではありますが、申請のまだされていない世帯については、９月末に勧奨通知を発送するという予定です。","voiceIndex":12,"id":"exchange-002"},{"speaker":"くにば委員","kind":"質問","question":"勧奨通知でどこまで拾えるかという部分だと思うのですけれども、最終的に勧奨通知を送って、それでも返信というか、申請がなかった方に対して、一番最後の拾い上げとしてのアプローチというのは、何かその施策をお考えでしょうか。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"勧奨通知を送った後に、申請をまだそれでもされていない世帯につきましては、まず高齢者福祉課、生活福祉課、障害者福祉課といった担当課と連携して、申請されていない世帯に個別のアプローチできる部分に関しては行っていく予定です。","voiceIndex":14,"id":"exchange-003"},{"speaker":"くにば委員","kind":"意見","question":"ぜひともこちら広報に引き続き、広報だけでは難しい部分、郵送でも難しい部分はそのようにして直接訪問であるとか、電話ができるところに対して電話をしていただくであるとか、最終的にどこまで９９.２％辺りに近づいていけるかどうかということを私のほうも期待をしながら見守っていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"今説明いただいて、コールセンターというものは、何人体制でやっていたのでしたかということと、あとこの給付作業というものも、特別定額給付金１０万円のときはどんどん増やしていく感じで作業員を、作業員というか、給付をする方を増やしていたのですけれども、この今回の活力応援給付金のほうは増やしたりという変化はあったのかということを伺いたいと思います。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"コールセンターの体制ですが、コールセンターは電話機１５台、オペレーター１５名という体制で行っております。続いて給付作業につきましては、８月、９月につきましては、委託業者８０人体制ということで作業に当たっているところです。","voiceIndex":18,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"今も質問の中でありましたけれども、個別にアプローチできる部分、所管と連携してということで、よかったと思っているのですけれども、私も３名ぐらいから、その通知が来たかどうかが分からないという、そのような問合せもあったので、直接コールセンターを紹介したりなどもしたのですけれども、そのような問合せが、問合せ別にいろいろまとめられているのかと思って。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"続いて２番目のご質問なのですけれども、申請率を上げるための努力というところで、特別定額給付金担当と連携しながら、先行して行っている特別定額給付金のやり方等を参考にしながら、今回のしながわ活力応援給付金に活かすような形で行っていくように考えてあります。","voiceIndex":20,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"この１０万円の給付金と連携はされているということなのですけれども、要は０.８％の方が申請されていないというところでの理由というか、完璧には分からないと思うのですけれども、その辺の教訓というか、その辺のやり取りはあったのかという、そしてそれを活かしているのかということなのですが、いかがでしょうか。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"私どもしながわ活力応援給付金担当でも、やはり申請書を送って、一定数の郵送物の返戻というものもございました。郵送物が届かないという、また理由がちょっと不明という方もいらっしゃるというところは認識しているところです。","voiceIndex":22,"id":"exchange-007"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと１点だけ確認、郵送して宛てどころに届きませんというような形が一定あるのかなというところのその確認、もうそこに本当に住んでいないかどうかということはどう確認するのかというのを、ひとつ教えていただきたいと思います。できるだけ多くの方にしっかりと届くようにというところで、かなりご努力されているということはよく分かったので、そこだけ教えてもらえますか。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"住民基本台帳等で理由を調べて、転出しているということであれば分かるのですが、転出等が確認できないという形であれば、今回発送する、その勧奨通知をもう一度同じ住所に送ってみて様子を見るという形ではありますけれども、なかなか理由というものが分かりかねるです。","voiceIndex":25,"id":"exchange-008"},{"speaker":"大倉委員","kind":"質問","question":"分かりました。やはり一定、住所地はあるけれども家に住んでいないとか、分からないというところが、宛てどころに届きませんと返ってきてしまうということで、その後勧奨しても多分同じようになってしまうというところでは、その後何か対応ができるのかどうか、その辺の考えはどのようになっているか教えてください。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"給付金事務においては、やはり申請をいただく形になるので、申請書をお手元に届けたいというところがありまして勧奨通知も送るところなのですが、それでも宛てどころなしで返ってきてしまったものについては、なかなか手だてが難しいところかなです。","voiceIndex":27,"id":"exchange-009"}]},{"id":"topic-02","title":"交通系ＩＣカードによる手数料収納開始","agenda":"交通系ＩＣカードによる手数料収納開始","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"対象手数料の(1)印鑑証明書等の等は何か教えてください。それとＳｕｉｃａ、ＰＡＳＭＯ等の等を教えていただきたいのと、これをすることの、ここにＳｕｉｃａ、ＰＡＳＭＯをつけるような機械などというものを買ったら、これにかかった経費を教えていただきたいのと、それとこのＳｕｉｃａ、ＰＡＳＭＯ等を使って決済するという方法は今回初めてやるのか、教えていただきたいと思います。","respondent":"木村戸籍住民課長","answer":"それから予算ですけれども、実際には、そのピッというところは月１,０００円ぐらいのリース料でやるということでございまして、それに伴いまして対応するレジも導入するということで、今年度の予算としては３７万円強という形です。","voiceIndex":33,"id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"とうとうこのような形を取っていくということは、キャッシュカードではなくて、例えばＳｕｉｃａだとそこに現金が入っているわけですから即決済という形で、とうとうこのような時代になってきたのだという思いがあるので、いろいろな決済をこの、課長に言うのも答弁は求めませんが、していっていただきたいという思いがあるのと、委員長、所管の課長がいないのですけれども、区民委員会という意味で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"ぜひこのＳｕｉｃａ、キャッシュカード、クレジットカードと違いますので、検討していっていただきたいと思っていますし、便利で、そしてある意味安全なので、ぜひ推進していっていただきたいと考えています。どこかで、このような形でこうなったという報告をしていただきたいと思います。本当にすばらしい施策だと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-012"},{"speaker":"くにば委員","kind":"質問","question":"端的に伺いたいのが、こちら事業者に支払う決済手数料が何％なのか、あとこちら端末の設置が全窓口なのか、こちらの２点、まず伺います。","respondent":"木村戸籍住民課長","answer":"手数料ですけれども、３％になります。住民票が３００円ですので、９円ということです。それから端末に関しましては、この戸籍住民課の住民異動係というところの１つの窓口、１台でスタートというような形になります。","voiceIndex":42,"id":"exchange-013"},{"speaker":"くにば委員","kind":"質問","question":"小銭を出す方はごく一部、もう８割、９割ぐらいの方々は実際にこの交通系ＩＣカードを使っているという部分で、窓口のほうでもきちんとその広報なりをすれば、同様に６割、７割の方々が小銭を出さず、ＩＣカードで決済ということを実現していけるのではないかと思って、それぐらい利便性の向上が見込める今回の施策だということで、大変評価しているのですけれども、申し上げました２点。","respondent":"木村戸籍住民課長","answer":"実際にうちの課の中で年間１６万件ほど、そのようないろいろな証明の発行をしているのですけれども、うち、その三、四割は、そのぐらい行くであろうというようなところで、ただ、今回１つの係でやるところですので、全体のパイからするともう少しなのですが。","voiceIndex":44,"id":"exchange-014"},{"speaker":"くにば委員","kind":"質問・要望","question":"当然ながら小銭を出すということも含めて、窓口の方々の負担もかなり減ると思いますし、もちろん利便性向上という意味合いでも、かなり区民の方々等もこの利便性の恩恵にあずかれると思うので、そこに関して、ただ住民サービスの向上と引換えに、今回は手数料収入が減になるということを、そこに関して数字を見込んで、当然ながらお金ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"これ本当に、やはりキャッシュレス、すごくいいなとは思うのですけれども、今回交通系ということで、流通系のほうの導入の見通しについてもお伺いできればと思います。","respondent":"木村戸籍住民課長","answer":"はこの交通系ＩＣカードでスタートしてみようというような考えで、先ほどのお話のそのような運用状況や、あといろいろなお声なり、そのようなニーズなりの高まりで、実際に導入もまた検討してまいりたいと思います。","voiceIndex":48,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"もう１点なのですけれども、もう１点か２点か、今回はこの導入でクレジットカードのほう、これまで普通の流れとしては先にクレジット払いが時代的にはあって、それで今度このキャッシュレス、ＩＣカードというものが出てきたと思うのですが、クレジットカードは今、税金の関係などは結構導入され始めていますけれども、この窓口での手数料等の関係では。","respondent":"木村戸籍住民課長","answer":"クレジットカードはやはり、ある程度一定の金額というのですか、手数料の関係もあることはあるのですけれども、今検討の、いわゆる扱うものは少額なので、ちょっと今のところは入ってはおりません。","voiceIndex":50,"id":"exchange-017"},{"speaker":"松本委員","kind":"確認","question":"おっしゃるとおりで、本当にクレジットカードになると結構高額なものを対象にされている場合が多いと思うので、検討状況を伺えただけで、それでよかったと思います。カードだけで決済するのか、あるいはスマートフォンで、スマートフォンを持ってピッとできるようになっているのか、ここの部分はどうなっていますでしょうか。","respondent":"木村戸籍住民課長","answer":"基本的にカードの機能が入っているものに関しましては読み取れるという形です。","voiceIndex":52,"id":"exchange-018"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"小芝委員","kind":"確認","question":"先ほどの説明で融資あっ旋の状況、あっ旋から実行の割合が６５％程度という話でしたけれども、セーフティーネットの認定実績というものが４号認定２,７８８件で、それで漏れてしまった方が５号認定になるような話を聞いたのですが、私の知り合いの方も結局認定を外されてしまった、止められたという方もいまして、具体的にどのぐらいの、この４号認定で申請といいますか、相談があって。","respondent":"遠藤商業・ものづくり課長","answer":"お見えになるときに、経営相談という形でいらっしゃったときに、何で来るというのがまず分からないところがあるので、その中の何％ということは分からないところではあるのですけれども、セーフティーネットの場合。","voiceIndex":59,"id":"exchange-019"},{"speaker":"小芝委員","kind":"質問・要望","question":"次に企業倒産状況なのですけれども、宿泊・飲食がこの数ということで、一方で基本的に個人事業主、これ今回中小企業支援なので話が外れてしまうかもしれないのですけれども、個人事業主は相当な数が、私の主に活動しています大井地域でも、数多くの個人事業主が撤退を余儀なくされている状況ですが、その辺、今回の所管事務調査の項目。","respondent":"遠藤商業・ものづくり課長","answer":"ただ同じようにといいますか、やはり受注が減っているというところで、いろいろと工夫されているという形では伺っているところですので、助成金の部分につきましては、中小企業のみならず、個人事業主も対象になっているようなものも幾つか。","voiceIndex":61,"id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"飲食店ですけれども。そういうところからすると、これから先も見通せないということは当然かなと思うのです。そうした意味での、国や都の支援のさらなる継続を求めるとともに、品川区でも１回こっきりの支援はさらに継続していくという工夫をしていかなければいけないのではないかと思うのですけれども、そこはいかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"私どもといたしましても、今まで販路拡大や、あるいは融資などにつきましても、しばらくは安心していただこうということで、据置期間３年という形で、３年間はお支払い、返済しなくていいという形にさせていただいて、３年あればワクチンができたりとかという部分があって。","voiceIndex":64,"id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"生活様式もそうですけれども、やはり中小企業の経営というところでも、何というのですか、いろいろな連携先と何を進めるかにはよると思うのですが、やはり業種が連携するとか、協力者を見つけるというようなこともいろいろ言われている中で、そのようなものを区が、何というんですか、支援とまではいけるのか分からないですけれども、そのような新たな中小企業の経営というもののやり方、やり方ではない。","respondent":"遠藤商業・ものづくり課長","answer":"例えばなのですけれども、今うちのほうで形にしようと思っているのが商店街支援なのですが、なかなかそのような部分で電子化が進んでいないというところがありまして、一方で私どもは五反田バレーという非常に有力な団体がいらっしゃいますので、今。","voiceIndex":66,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たちはコロナ禍ではなくても減税を求めていますけれども、やはりそこにいかないと、１０％で落ち込んでいたところにコロナということなので、これでコロナが終息しても、まだまだきつい状況がこの１０％消費税ではあるのではないかと思うので、これ中小企業の経営を守るということからも、そういったものが必要なのではないかと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"消費税のお話が出まして、消費税、こちら国の施策なので私どものほうで意見するところではございませんが、経営変化対策資金２０１９というところで、最初消費税に対応できるようにということで。","voiceIndex":68,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"確認","question":"それで福祉施設や学校、保育園などでも、要は感染者が出ましたということはプレス発表でもされるのです。ですけれども、特定はされないわけです。かといって、ではそのプレス発表をする基準も、特に品川にはないですよね。今回のこの東大井五丁目というように出されてしまったところというのは、区はどのように把握をされているのか、区が出したのか、ちょっとその辺を確認したいのですが。お願いします。","respondent":"遠藤商業・ものづくり課長","answer":"報道されたものは、もうこれ止めることはできないかと思いますので、その後の払拭ということで、私どもいろいろな形で支援させていただいているところですので、今後も商店街等お話があれば、引き続きそのような形で対応させていただければと考えています。","voiceIndex":70,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですけれども、やはり、私も一般質問等でも求めましたが、そうした地域へのＰＣＲ検査を拡大する、所管が違うのですけれども、そのようなことはやはりしていかなければいけないのだなと。していくべきだし、それが一番のお客さんを取り戻すアピールというか、そのようなものになるかなというふうに私も感じましたので、ぜひ所管を越えて、そのようなことを求めていただけたらと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-025"},{"speaker":"松本委員","kind":"質問・要望","question":"出てきたのかもしれないです。これは、今は東大井五丁目でしたけれども、私も武蔵小山エリアでパルムや戸越銀座などが、やはり報道からすごい密な状況だったというようなことで、クレームが物すごい全国から来たようなところがありますので、その辺りは、ちょっと今日の話とは違うのであくまで要望として少し申し上げておきたいと思います。お願いします。","respondent":"遠藤商業・ものづくり課長","answer":"それから創業支援センターなどでもいろいろと支援させていただいているところですが、先日も報告させていただいたアクセラレーションプログラム、先日こちらKick-Offイベントがありまして、多くの方、２１人の方が結局採択といいますか、要するに企業２１社が。","voiceIndex":74,"id":"exchange-026"},{"speaker":"松本委員","kind":"質問・要望","question":"要望なのですけれども、こういったことをどんどん広報していただくというところ、やはり景気というのは、何でしょう、気から来るというところもあると思いますので、ぜひ明るいほうもいろいろと広報していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-027"},{"speaker":"大倉委員","kind":"質問・要望","question":"何か聞くと、やはり今なかなか五反田バレーに入ってくるところが少なくなってきているというような情報も入っていたりするのですが、その辺どのように捉えているか教えていただきたいのと、あと４番の倒産状況というのは、これ廃業も含めて入っているのかというところで、結構コロナの影響で。","respondent":"遠藤商業・ものづくり課長","answer":"それから先ほどの企業の倒産状況ですけれども、こちら倒産だけになりまして、廃業については現在のところちょっと確認ができないです。","voiceIndex":77,"id":"exchange-028"},{"speaker":"大倉委員","kind":"質問・要望","question":"廃業も多分結構あるのかなというところでは、これ数としては取れないということなのか、もう１回教えていただきたいのと、テレワークもそうですし、今回も、例えば自宅で過ごすということが結構増えて、これでもいいよねというようなことが区民、国民に大体分かってきたというところで、今まで飲みに行っていたけれども、行かなくてもいいじゃないかという話が出てきたりすると、やはりそのようなところで。","respondent":"遠藤商業・ものづくり課長","answer":"こちらについては現状数字が取れないというところでございまして、ただ、民間の調査機関では、全国という話になりますけれども、昨年が４万件ぐらい廃業だったということですが、今年は５万件を超えるだろうというような話があるので。","voiceIndex":79,"id":"exchange-029"},{"speaker":"くにば委員","kind":"提案","question":"私のほうからは大きく２点、質問や要望、提案をします。先ほど来から廃業という部分に１つのフォーカスが当たっているとは思うのですけれども、大枠のこちらの支援に関して、国でもそうですし、都、区でもそうですし、やはり融資あっ旋であるとか、直接の助成金で一時的なお金の資金投入という形でやっていくと。これに関しては結局のところ一時的なしのぎでしかない。数字としても出づらい。","respondent":"遠藤商業・ものづくり課長","answer":"例えば、先ほど個別の支援ということでは、ビジネスアナリストというものをこちらのほうで派遣といいますか、個別にご相談するような機能を設けておりますので、そのようなところでの支援を中心に進めていけばと思っているところです。","voiceIndex":82,"id":"exchange-030"},{"speaker":"くにば委員","kind":"提案","question":"ここについて私のほうから１つ、提案であったりとか、要望であったりとかなのですけれども、そういった廃業、借金がない状態で廃業なさった方に対して、再チャレンジの支援をしていくという。結局そのくくりというものは難しいではないですか。なので、そこで一旦、自分の意思で廃業した方に対しての支援というものを、また別枠で考えていったらいかがかなと思うのですが、そこに関して１点お願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、今委員もおっしゃられたような、このような状況がありますので、そのような部分でどのような形、もともと廃業とはいえ、いわゆる経営ノウハウは持たれている方ですので、そのような方々への支援といいますか、その部分について何かできること。","voiceIndex":84,"id":"exchange-031"},{"speaker":"くにば委員","kind":"質問","question":"第二創業のような形で受けることが可能なのかどうか、ちょっと私、もう一度という部分で創業支援、私が詳しく存じ上げないからかもしれないのですけれども、もう一度改めて、同じ業種で、例えば１年半後にもう１回創業というか、開業届、廃業の逆に開業届を出した方に対しては、創業支援融資を受けられるのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"廃業後の創業の定義について、ちょっと確認をできないので申し訳ないのですけれども、一旦完全に店を畳まれたということでございまして、要するに事業をやらないという形、休業ではないということであれば、また新たにやるのであれば、ちょっと融資の中では。","voiceIndex":86,"id":"exchange-032"},{"speaker":"くにば委員","kind":"質問・要望","question":"分かりました。その辺の制度の部分に関して、私のほうでもう一度調べてみて精査はしたいと思うのですけれども、ぜひとももう一度そのチャレンジをするという方、借金がなく、断念してしまったけれども、もう一度チャレンジをするという方に対して、ぜひ区として独自に支援をしていただきたいと思います。それが１点目でもう１点あるのですけれども、時間的にもう無理ですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-033"},{"speaker":"くにば委員","kind":"質問・要望","question":"もうあと５分、１０分ぐらい。それが今１つが屋形船なのですけれども、地域振興部の所管の中で、そういった特色を出して飲食業以外のところで個別にどういった支援をしていこうかという施策、現在計画をしている部分であるとか、今後このような計画がありますとかいう部分、あとは今申し上げた部分、区全体での均一な、満遍ない支援以外に、品川区としての特色を出していく支援策について伺いたいです。","respondent":"遠藤商業・ものづくり課長","answer":"影響を受けているところもまだ、今全部が受けているところですので、区の特色ということでやはり商店街の部分が多いかなというところがありまして、その辺のところで既に今の支援と、それからイベントなどを行うときに助成率なども少し変更させて。","voiceIndex":90,"id":"exchange-034"},{"speaker":"くにば委員","kind":"質問・要望","question":"そこに対しての支援はさておきというか、もうここはいいだろうと。ではなくて、全体の業種ではなく、ここの戻りが遅いところの業種に対して個別に支援をしていっていただくということが、今後中長期的に品川区の産業がもう１回戻ってくるためには重要だと思いますので、そこに関しての施策を今後考えていただきたいというのが要望というか、今後品川区がやっていくべきことなのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-035"},{"speaker":"くにば委員","kind":"質問","question":"それに対して再質問というか、そちらに関しては、その申請なさる方が借入れがあってもということでしょうか。借入れの残額があってもということでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"以前の融資が残っている場合ですと、区のほうでやっている融資が残っているとお使いいただけないのですけれども、一応そこがきちんと廃業の段階で、今回使うというときに終わっているようであればお使いいただけるという形になります。","voiceIndex":96,"id":"exchange-036"}]},{"id":"topic-04","title":"に戻りまして、(3)令和元年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"に戻りまして、(3)令和元年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"は全体として、各施設についてです。今年度、直近までで構わないので、現在までの利用率、もうこれは全てコロナ禍によって利用率は低下しているということなのですけれども、各施設によって、そこに関しての特色は違うと思います。ですので、利用率、収入の見込みと見通しについて、まずはお伺いします。","respondent":"遠藤商業・ものづくり課長、古巻文化観光課長、中元スポーツ推進課長","answer":"それから利用料につきましては、現在かなり、当初はもうこのまま続いてしまうのかなですが、大分予約が１１月。それほど、何というのですか、Ｖ字回復というか、大きく回復はまだ見込めない状況。そして令和２年度の全体での利用料収入の見込みですが、令和２年度に関しまして、少し少なめの数字では今のところ見積もっているところですけれども。","voiceIndex":104,"id":"exchange-037"},{"speaker":"くにば委員","kind":"質問","question":"それぞれご答弁ありがとうあります。そういった飛沫感染防止策、施設での感染拡大の防止策として、利用者の方に呼びかける、こちらの２点、大きな声での会話の自粛というものは本当に守られているのか、ボディーコンタクト等に関して、何か区の方針で、これはやめてくれなどということを何か方針を出しているのかどうか、そちらについて伺います。","respondent":"中元スポーツ推進課長","answer":"コロナ対策としまして、やはり区内の小中学生の方の利用もありますので、基本的には学校のガイドライン、教育総合支援センターのほうで作られているものと連携を常に、情報が更新され次第頂きまして、くにば委員のご発言にもありますが、学校体育での注意制限事項。","voiceIndex":108,"id":"exchange-038"},{"speaker":"くにば委員","kind":"質問","question":"各団体のそのガイドラインという部分、あとは文科省のガイドラインという部分、よく分かりました。そういった一般の方々が施設利用する際に、方針として、施設として、どの程度利用の注意を促していて、実際その利用している方々に対して、こちらに関しての利用はお控えくださいであるとか、そういった実際のオペレーションとしてどこまで感染対策ができているのかということを伺いたいです。","respondent":"中元スポーツ推進課長","answer":"９月から徐々に始められているところもあるのですが、やはり接触が少ないバドミントンなどが９月１６日からとか、卓球などは先に始まるのですけれども、バレーボールやバスケットボールはやはりその競技連盟の方々から、１月からの予定でということでお申出がございましたので。","voiceIndex":110,"id":"exchange-039"},{"speaker":"くにば委員","kind":"質問・要望","question":"結局こちら、きゅりあんに関しては、一般の事業者の方々が営利目的でなされる、興行等でたくさん利用なさっているので、やはりキャンセル料という部分を区の施設としてどこまで求めていくのかという部分で、やはり今後の利用率、再開に当たっての利用率は大分変わってくるかなと。個人的な所感ですけれども。","respondent":"古巻文化観光課長","answer":"ただ、それを手をこまねいて見ているということではないので、文化振興事業団のほうでもなるべく利用が上がるような工夫、ＰＲに努めたりとか、感染症対策についても独自に体温測定器を導入するとか、そういった形で感染症対策もしっかりするということですし。","voiceIndex":114,"id":"exchange-040"},{"speaker":"くにば委員","kind":"質問","question":"今おっしゃっていた、利用率の向上のためにＰＲ等をもちろんするであるとか、いろいろな施策の考えがあると、大幅にいろいろ施策の考えがあると思うのですけれども、基本的にここの利用率の向上であるとかに関して、考えるのは区のほうで考えるのか、それともこちらの指定管理者のほうで考えるのか、どちらのほうがこちらの取組をなさるのですか。","respondent":"古巻文化観光課長","answer":"一義的には文化振興事業団が考えるというような形ですけれども、丸投げでするということではなくて、区のほうも支援をしたりとか、様々な形で連携を取っていきたいというふうに考えています。","voiceIndex":116,"id":"exchange-041"},{"speaker":"くにば委員","kind":"意見","question":"きゅりあんに関して今おっしゃっていた中で、幾つか利用率向上のための施策についてご答弁があったのですけれども、こちら、例えばイベント規模によって、もう今自粛している、中止しているところが、もう一度その次の公演をしようとか、もう一度イベントをしようというときに、もちろんきゅりあんだけではなく、例えば半年後のイベント、１年後のイベントをどこで開催するかというときに。","respondent":"古巻文化観光課長","answer":"は安心して利用していただくための感染症対策ということでは、先ほども少し挙げさせていただきましたけれども、体温測定器の導入でありますとか、どういった形で利用していただくのかということでいうと、まだ定員については、なかなか１００席もの定員が。","voiceIndex":118,"id":"exchange-042"},{"speaker":"くにば委員","kind":"質問・要望","question":"様々ありがとうございました。やはり利用率が落ち込んでいるイベント業界というものは本当に大変だと思うので、このきゅりあんに関して、ぜひとも文化振興事業団と、あとは行政のほうとしていろいろと話し合ってアイデアを練りながら、また利用率の向上のほうを目指して頑張っていただきたいと思います。次に、ＳＨＩＰのほうです。そちらに関して見解をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"コワーキングスペースの利用状況が減るというようなお話もあったと思いますが、純粋に今、やはりフリーランスの方が増えているという現状がありますので、特に企業として、何といいますか、あるところに行ってということは減ってくる部分もあるかと思いますけれども。","voiceIndex":120,"id":"exchange-043"},{"speaker":"くにば委員","kind":"質問","question":"減ってしまうのは致し方ないのかなという部分もあるのですけれども、そちらに関して、利用率が今のところは下がっていないという認識でよろしいのか、あとは今後に向けても、こういったオンラインセミナーが増加するに当たって、そういったホールでの利用は下がるのかどうかの見通し、そこを教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"このセミナーについては４階の部分、コワーキングスペースの利用者なり、あるいは会員の方が見るようなところのもので、本来であれば会議室でセミナーなどをやっていたものを、ちょっと集まることができないということで、セミナーという形にさせていただいているものですので。","voiceIndex":122,"id":"exchange-044"},{"speaker":"くにば委員","kind":"意見","question":"ＳＨＩＰに関して、工房の利用に関してが若干減っているという部分が、昨年とその一昨年の区民委員会の答弁か何かあったような気がするのですが、そちらに関しては今後どういった形で展開をしていくか、今後利用がさらに増えていくためにどのような施策を打っているのかということを最後にお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、引き続き工房を使っての、いろいろと試作品を作られたりなどという部分があるかと思いますので、周知に努めていけたらと考えています。","voiceIndex":124,"id":"exchange-045"},{"speaker":"大倉委員","kind":"質問","question":"基本的にはコロナウイルス感染症対策についてで、運動施設についてはガイドラインが、各団体等のガイドラインに沿ってやってもらって、体温計なども配置したりして、安心して使えるようにということでいろいろ取組もされていて、消毒液も設置して、利用者が安心して使えるような取組というものは今もかなりされていて、その中で、例えばエレベーターのボタンであったり、施設の手すりだったりというものも。","respondent":"中元スポーツ推進課長、古巻文化観光課長、遠藤商業・ものづくり課長","answer":"総合体育館、戸越体育館におきましては、まず休止期間の間に様々対策を検討し、清掃事業者と調整、この指定管理者を通じて調整をいたしまして。きゅりあん等を含めまして、文化振興事業団所管の各施設ですけれども、今体育館のほうでもご答弁させていただいたのと同じで、清掃は委託でしていますので。これは全部事業者からいろいろご提案がありまして、もともとの施設ガイドラインというものがありますので、それにのっとった形で今やっていただいて。","voiceIndex":127,"id":"exchange-046"},{"speaker":"大倉委員","kind":"質問・要望","question":"清掃等も増やして対応していただいているということで、そういったところの費用などというのは、やはり少し増加傾向にあるのかというところと、教えていただきたいのが、あとそういうものというのは清掃していますとどこかにアピールするとか、安心して使うときに、今まで以上に気を遣った施設の運営をしていますというようなものが、利用される方に分かるほうがいいかなと思っていて。","respondent":"古巻文化観光課長、中元スポーツ推進課長、遠藤商業・ものづくり課長","answer":"費用面での考え方ですけれども、確かに清掃の、何というのですか、手間というか、回数が増えたりとかいうことで、費用の上昇につながる内容ではありますが。体育館のほうにおきましては、ちょうど今年、実はオリンピック・パラリンピックの練習会場になる予定でございました。７月から９月の中旬まで。いわゆるこのような部分をやっていますというような掲示のお話ですが、掲示自体は特に設けてはいないのですけれども、例えば、当然利用者に。","voiceIndex":131,"id":"exchange-047"},{"speaker":"大倉委員","kind":"意見","question":"は掲示もそうですし、先ほど言った、例えばエレベーターのボタンに抗菌シートをきちんと貼っていますよというようなものが目で見えても安心できるかなと思いますので、そういった目に見える、先ほどの課長のお話でもあった、例えばきちんと２メートル、ソーシャルディスタンスを取れるような、何か並びの配置のシールを貼るとか、そういう様々工夫をして。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こうでした、こうでした、そうですかではなくて、事業計画というものを皆さん出されているわけです。ほかの自治体では、そうしたものも全て出している、そしてホームページにも載せているという自治体もあるので、そうした公開、情報として出していただきたいということは改めて求めたいのです。なので、そうした改善をぜひお願いしたいのですが、いかがでしょうか。","respondent":"古巻文化観光課長","answer":"私の口からちょっとどうしますと言いづらいところはありますけれども、いただいたご意見については承って、伝えてまいります。","voiceIndex":137,"id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そのようにはほかの委員会でも言われるのですけれども、そうしたほうがいいのではないかと思いませんかということで、なのでもし思うのであれば、そういった意見をぜひ上げていっていただいて、改善をさせていただきたいと思います。これは要望にしておきますけれども。それで、この指定管理者のそれぞれの法人で、それぞれの業務に当たっている人数を伺いたいと思うのです。それぞれ。","respondent":"遠藤商業・ものづくり課長、中元スポーツ推進課長、古巻文化観光課長","answer":"３階と４階部分によって分かれていまして、３階につきましては、今３名が基本的にいるというようなところで聞いております。令和元年度の人数ということで回答しますが、合計で１８人という形になってあります。これは理事長の方１名を含めた人数です。清掃などもいますが、舞台だったり、窓口対応だったりする方々もいらっしゃいますので、実際の日々の運営についてはもう少し多い人数でやっている。","voiceIndex":139,"id":"exchange-050"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこの中では、主にどのような声があるのかということを伺いたいのですが、主にでいいです。そして体育館のほうでは、クレーム対応シートというものを活用しているということなのですけれども、こうした改善につながる大事なものだと思うのですが、それがどれぐらいたくさんあるのか、そこまででもないのか、このような取組は大事だと思うのですけれども、そういった中身を伺いたいと思います。","respondent":"中元スポーツ推進課長、古巻文化観光課長","answer":"もう一つのクレーム対応シートは、やはり最近、たまにちょっとあるのですが、そのようなクレーム、要望事項に関しまして、厳しいご意見等があったときには、やはりちょっとそこをきちんと職員間、業者の間等で、会議等で情報共有をし。設備や備品に対しての状況のご意見とかそういったもの、それからあと窓口の受付の対応ですとか、それから大きなホールを使う場合については、舞台さんとの打合せを綿密に行いますけれども、そういった舞台さんとの打合せの状況について。","voiceIndex":143,"id":"exchange-051"}]},{"id":"topic-05","title":"イルミネーション事業","agenda":"イルミネーション事業","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"今年度もこちらの予算額について中心に質問したいのですけれども、まずはこちらの２,９３０万円余の内訳を教えてください。ただし、今回に関しては、こちらにも書いてあるとおり、点灯式のほうを中止するということで、そちらに関しての経費はマイナスになっていてしかるべきなのですけれども、こちらが増額になっている理由を含めて、内訳をお聞かせください。","respondent":"古巻文化観光課長","answer":"式典等は行いませんけれども、式典に係る経費というものはそれほど大きなものではないので、基本的には設置に係る経費が主で、ちょっと人件費等々の部分が増えてしまったという状況です。","voiceIndex":150,"id":"exchange-052"},{"speaker":"くにば委員","kind":"質問","question":"トータル１８０万円プラスアルファの２００万円増ぐらいまで、人件費の増加でなるのかなというのは、ちょっと頭の中で何人工というものをトータルの期間で試算しても、どれぐらい上がったらこのように２００万円も人件費が上がるのかということは、少し不思議な部分があるのですが、そこに関しての細かい数字というものは特に把握はなさっていないのでしょうかということが１点です。","respondent":"古巻文化観光課長","answer":"広告にイルミネーション、電飾をつけますので、その辺りで多少危険度が高い作業になるということがありますので、そういう意味でいうと、値上がりの部分が少し高いようにも感じますけれども、そのような関係で人件費が上がってしまったというふうに認識をしております。","voiceIndex":152,"id":"exchange-053"},{"speaker":"くにば委員","kind":"意見","question":"そのバーチャルでの配信ということも新しい取組で、今年そういった、この後にあるイベントに関しても、そういった報告があるのですけれども、そういったインターネットでの配信であるとか、バーチャルということで、また新たなイベントの楽しみ方であるとか、魅力の発信の仕方、そういったものが様々模索されていると思いますので、そちらに関して目黒川、大変期待をして見ていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":154,"id":"exchange-054"},{"speaker":"小芝委員","kind":"確認","question":"毎年このイルミネーション点灯の時期になりますと、大井町の駅前、イトーヨーカ堂前を歩いておりますと年の瀬を感じる、非常にセンチメンタルな心にもなったりするものなのですけれども、このイルミネーション事業自体は、まず確認なのですが、文化観光課単独の事業という認識でよろしいでしょうか。","respondent":"古巻文化観光課長","answer":"庁内の所管という意味で申し上げますと、文化観光課単独になります。観光協会と連携しながらというような形ですので、文化観光課所管という形になります。","voiceIndex":156,"id":"exchange-055"},{"speaker":"小芝委員","kind":"質問","question":"所管が違いますのでお答えづらいと思いますけれども、お考えのほうをお聞かせ願えますでしょうか。","respondent":"古巻文化観光課長","answer":"はっきりしたご答弁ができないので申し訳ないですけれども、そういったことでご意見として承らせていただきたいと思います。","voiceIndex":158,"id":"exchange-056"},{"speaker":"小芝委員","kind":"質問・要望","question":"予算のほうも決まっておりますので、なかなか追加ということは難しいと思いますけれども、今後、また来年度に向けて考えていただければと思います。要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-057"},{"speaker":"大倉委員","kind":"質問・要望","question":"すみません。確認なのですけれども、今のお話で、これは単色というか、白しかできないのですかというのは、結構ほかのところを見に行くといろいろ色を変えられたりということは割と簡単にできるというような話もあるのですが、それができないのかということを改めて、もう１回確認で教えていただきたい。","respondent":"古巻文化観光課長","answer":"これは地域の方の発案で始めて、地域の方のご意見を十分に尊重していくような形になりますので、そちら地域の方ともよくお話をさせていただきながら、進めていきたいと思います。","voiceIndex":162,"id":"exchange-058"},{"speaker":"大倉委員","kind":"意見","question":"大井競馬場でも都内最大級のという形でやるから、それだけ人目を引くというところもあると思いますので、そういったところとうまく連携ができれば、イルミネーションをつないでいくということもできるのかなと思いますので、いろいろ考えて工夫していただいて、さらなるこの大井町の観光の振興に寄与するような取組にしていただけるといいのかなと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":164,"id":"exchange-059"},{"speaker":"松本委員","kind":"質問","question":"そうすると今の話でも、何か改善しようというときなども、本来は民間が入っているものは民間の発想でより改善案とか、自分たちも負担しているからこそこうしたいのだというようなことが出てくるのではないかと思うのですけれども、そもそも論でなぜこれは区が丸抱えをしているのか、そこの部分をお伺いしてよろしいでしょうか。","respondent":"古巻文化観光課長","answer":"とはいえ、いろいろと手法を考えていくということは必要かと思いますので、様々な可能性も含めて検討して、よりよい形でイルミネーション事業を進めていきたいというふうに考えています。","voiceIndex":166,"id":"exchange-060"},{"speaker":"松本委員","kind":"質問・要望","question":"私もちょっとこのイルミネーション事業をもう少し研究しないといけないと思うのは思うのですけれども、例えばこれも大井町と西小山だけでやっていて、ではいろいろな地域のまちづくり協議会等から、いろいろなところから声が上がったときに、その公平性というか、いろいろなところがあると思いますので、また私も研究して、いろいろと質問等させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-061"},{"speaker":"つる副委員長","kind":"質問","question":"今ずっとあった色です。これ私もずっと思っていて、ぜひ青色がいいのではないかと思います。それこそ「ブルー・ライト・ヨコハマ」と言われるぐらいな、ブルーライト大井町と言われるぐらいの、何というのですか、積極的なアピールというか、せっかくこういう機会であるからこそ、やるからにはそういったところに対する意識、本当にちょっとした心がけだと思うのです。感染をさせないとか、感染をしないとか。","respondent":"古巻文化観光課長","answer":"可能性の話としてどこまでできるかということは、この場でなかなか確約というか、確かなことは申し上げられないのですけれども、いただきましたご意見、十分に踏まえまして、色がどこまで、全面的にということは確かに難しいと思うのですが。","voiceIndex":170,"id":"exchange-062"},{"speaker":"つる副委員長","kind":"意見","question":"ただ、全体の意識として、きちんとそういったことも、先ほど申し上げた行動変容につながるような意識づけというところも、今この時期においては大事なのかなという部分では、今ご答弁いただいたように、できる限りの中での、直接ＬＥＤそのものを青色に変えるとかではなくて、何かそれにつながるようなものがつけられるのであれば、いろいろな工夫をしていただいて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-063"}]},{"id":"topic-06","title":"１０月のイベント開催予定情報","agenda":"１０月のイベント開催予定情報","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"要するに、品川区としてオフィシャルでこういった区の魅力を発信するような形で、今回であればこちらの５つのイベントであるとか、コロナ禍において現地に足を運べない方、もしくはさらに翌年以降、キャナルフェスに来られなかった、行けなかったけれども、どういった形でしていたのだろうであるとか、今年行こうと考えているけれども去年はどういった形だったのだろうということが。","respondent":"古巻文化観光課長","answer":"こういったウェブ配信については、今までもまるっきりなかったわけではないですけれども、今年度のこういった状況下において、様々な試みが今なされているところですので、そういった辺りも整理をさせていただいて、どういった形が観光施策にとって有益なのかということ。","voiceIndex":178,"id":"exchange-064"},{"speaker":"くにば委員","kind":"質問・要望","question":"ご答弁ありがとうございました。ちょっとなかなか進んでいないので、そこに関してぜひとも今年度やっていただけたらと思っている次第なので、いま一度観光協会とお話をいただいたり、所管の課の中、グループの中で話合いを持たれて、ぜひ進めてくださいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-065"},{"speaker":"松本委員","kind":"質問","question":"どうなのでしょうか。","respondent":"古巻文化観光課長","answer":"しながわ観光協会ですけれども、決して何も連携していないとか、話を通していないとかいうことではないですが、なかなか、マンパワー的にちょっと実現が難しい面もあるというようなことでお話をさせていただいたのかなと思います。","voiceIndex":182,"id":"exchange-066"},{"speaker":"大倉委員","kind":"質問・要望","question":"そうすると、やはりただＹｏｕＴｕｂｅを配信してもなかなか難しいというところが、よく言われるＹｏｕＴｕｂｅでも有名な人にそのような予算の余ったところでお声をかけて、そのような人たちに発信してもらうというやり方も１つあるかなと思っているので、そういったことも含めて、品川区をアピールしてくださいというような形でお声がけなどというものはできるのかなと思っているのですが。","respondent":"古巻文化観光課長、山崎文化スポーツ振興部長","answer":"様々な主体が絡んでいますので、実行委員会形式であったり、商店街の方が中心になったりなどということで、一律の運営組織になっていない部分、それぞれは一律の運営組織ですけれども、全部を通すと何か統一的な。1)のキャナルアートモーメントにつきましては、オリ・パラの文化施策ということで今年度予定をしていたもの、それから、今課長のほうで説明した文化観光の部分が、2)の天王洲の観光フェスタ。","voiceIndex":185,"id":"exchange-067"},{"speaker":"大倉委員","kind":"意見","question":"コロナ禍というところで、ＹｏｕＴｕｂｅの視聴は増えているというのも大きくあるのかなということが１つと、今お話のあったように、今後の品川のそのようなイベントのにぎわいや地域の活性化につなげていきたいというところでも、このようなイベントがあるのだったら行ってみようかと思ってもらうためにも、そのような発信というものができるといいなということは改めて思ったので、ぜひ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":188,"id":"exchange-068"}]},{"id":"topic-07","title":"品川歴史館特別展「広がる品川臨海部－新地開発から八潮地域の誕生まで」","agenda":"品川歴史館特別展「広がる品川臨海部－新地開発から八潮地域の誕生まで」","exchanges":[{"speaker":"小芝委員","kind":"確認","question":"確認なのですけれども、館内の配置なのですが、特別展というのは、受付を通りまして、直進すると突き当たりになります。そこの突き当たりのお部屋でよろしかったでしょうか。それとも何か手前の、この角を右側のほうに曲がったところなのか、その配置が、メインがたしか左側のほうにありますけれども、どの辺りを指すのでしょうか。","respondent":"古巻文化観光課長","answer":"特別展につきましては、入っていただいて左手を、会場は恐らく２か所に展示を分けると思います。左手のと、あと右のちょっと奥のほうに小さいお部屋があるのですけれども、こちら２か所で特別展は大体開催をしております。","voiceIndex":193,"id":"exchange-069"},{"speaker":"小芝委員","kind":"質問・要望","question":"うまく来た人が関心を持てるような感じのレイアウトといいますか、動線をうまくしていただければと思います。そういったところをぜひとも歴史館の中に組み込んで、地域の方、そして区外の方にも知っていただきたい。本当に大変すばらしい試みだと思いますので、私もしっかりと伺わせていただきますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2880#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":75053,"voices":200}},{"id":"r02-20200924-7","meetingId":"r02-cm09","date":"2020年9月24日","dateIso":"2020-09-24","committee":"厚生委員会","time":"午前１０時００分～午後 ４時３１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を80件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(2)から先に行います。 それでは、(2)品川区成年後見制度利用促進基本計画の策定","agenda":"冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(2)から先に行います。 それでは、(2)品川区成年後見制度利用促進基本計画の策定","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"大ざっぱに２つの方面から質問したいのですが、まず、この成年後見制度、なぜ利用促進なのかということ、それから、具体的なスケジュールという２方面です。日弁連などからも出ているというふうに伺ったのです。その辺りの成年後見制度に対するご理解と、なぜ今、そういう問題点がある中での利用促進計画なのかというところを、２点、お伺いしたいのですけれども、いかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"自分で十分に判断することができない方に対して、各種法的支援や福祉サービスの利用、生活支援を行うということで、必要とされている方がいらっしゃって、かつ、ご自分でそれが成し遂げられない、そういったご事情をお持ちの方に対して、成年後見制度というものがある。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"補佐、補助はいいのですが、後見制度自体に問題があるということなのです。この制度は、国の利用促進基本計画がもう既にあるのですね。そこら辺のご認識や姿勢を伺いたかったのですが、いかがでしょうか。補佐や補助の制度があるというのは、ここでは関係ないことだと私は思うのですけれども、いかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"それを必要としている方がいらっしゃるので、こういった計画は必要であるというふうに認識しております。もし問題点があるのであれば、この計画策定の中で、それをしっかり検証して生かしていく必要があろうと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"その問題点があるのは、事件が起きたりしていて事実ですし、障害者権利条約の１２条に抵触する恐れがあると指摘されているのも日弁連の文書で出たりしていて、それも事実ですから、そこら辺の抵触をクリアするように、計画を定める場合にも注意をしていっていただきたいと思います。さらに、未対応部分というのは、どういう部分なのでしょうか。以上、５点ほど教えていただきたいと思います。","respondent":"寺嶋福祉計画課長","answer":"現在、品川区では、社会福祉協議会の成年後見センターを中心に行っておりますので、そういった役割分担等もこれから社会福祉協議会と話し合って、区がやるのか、社協がやるのか、連携してやるのかといった辺りも含めて検討委員会の中で進めていくというふうに考えております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"たたき台は検討会で作るということでしたけれども、これは外部に委託するのでしょうか。委託するとしたら、どこに委託するのでしょうか。それとも内部の職員の方で作られるのでしょうか。","respondent":"寺嶋福祉計画課長","answer":"現時点の予定では、区福祉部の職員、保健所の職員、それから社会福祉協議会の職員といった辺りの内部で検討することを考えております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"虐待したとみなされたほう、保護される側のほう、加害者、被害者、私が関わった中では、どうやらどこかでこの成年後見制度が入ってきていて、基本的には高齢者虐待防止法の２８条で、成年後見制度の利用促進という、そもそも法制度の中で促進してくださいというものがあるのですけれど、高齢者虐待で、もし品川区が保護をするなり何なりという措置をした場合には、今必ず成年後見制度を使うような体制に。","respondent":"寺嶋福祉計画課長","answer":"高齢者虐待につきましては、基本的には成年後見の運営会議という検討会議みたいなものがありまして、必ず高齢者福祉課でケースを担当している職員が直接その事例を持ってきて、いわゆるケース検討をするという、成年後見センターの中でやっている、これが通常の活動でありまして。","voiceIndex":13,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"当然役割分担というところで、これから議論もあると思うのですけれど、成年後見について、ご本人または親族が何か意見を述べたい、また希望されたいというときには、しっかり区のほうで担保できるような形に中核機関も仕上げていただきたいというところが１点要望です。そこだけ最後に確認いたします。","respondent":"寺嶋福祉計画課長","answer":"いわゆる虐待防止法に基づいて、例えば措置をするであるとか、そういったケースが起きた場合には、当然そういう対応をしているのですけれど、いわゆる通常の状況確認のご相談の範囲で済むような場合というのも少なからずあろうかと思いますので。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"計画期間が３カ年ということで、今回は２年半くらいの計画になるということですけれども、そうすると、これからは見直しをしながらずっと３年間に１回、計画を作り替えていくことになるのでしょうかというのが１つ。それから、この委員会が１０月と令和３年の１月と７月、これから３回開催されるという予定ですが、これは公開されるものなのかということについてもお聞かせください。","respondent":"寺嶋福祉計画課長","answer":"計画期間の更新につきまして、今の段階ではまだ確定しておりません。その他の上位計画等とのバランスもありますので、その辺も見ながら検討していくことになろうかと考えています。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"先ほどの様々な課題についてということですが、国の基本計画が出ていますけれども、この中でも今後の施策の目標等というところで、利用者がメリットを実感できる制度運営への改善を進める、利用者に寄り添った運用ということで、意思決定ができるような、権利を擁護して意思決定を支援するということも書かれていますし、また。","respondent":"寺嶋福祉計画課長","answer":"繰り返しになりますが、品川区の場合は、既に成年後見制度の実績がありますので、その実績を計画の中でどのように位置付けして明確化していくか、そして課題があるなら、その中でどのようにそこをさらに強化していくかというところが。","voiceIndex":19,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私も成年後見センターでいろいろ相談を受けた方で、お世話になって、すごい助かっているという事例もたくさんあるのですが、それと同時に、やはり細かいところはなかなか自分の思いどおりにいかないという、そういう声も聞いています。これだけ全国的に課題ということにもなっておりますので、そういうところも含めて、前進できるような形での計画にぜひしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"}]},{"id":"topic-02","title":"特別定額給付金事業の進捗状況","agenda":"特別定額給付金事業の進捗状況","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"進捗状況のところにある申請件数と支給済み世帯数ですけれども、申請件数に対して支給済み世帯数が９９.９％ですけれども、引いてみたら２５件、まだ支給済みになっていないということなのですが、なぜ２５件が支給済みになっていないのかお伺いしたいのが１点です。それから、私のほうで、こういう人が支給されないということで伺っているのは、ホームレスの方。","respondent":"寺嶋特別定額給付金担当課長、櫻木生活福祉課長","answer":"ホームレスについては、後ほど答弁申し上げます。それから、勧奨通知につきましては、１万６９２通（世帯）、発送をしております。受給者の中で、ホームレス、かつ受給された方がどのぐらいかということですが、保護を申請して受給された中で、厳密に何名の方が申請されたかということは把握できておりませんが、４月以降、ホームレスの方の生活保護の申請は。","voiceIndex":26,"id":"exchange-010"},{"speaker":"渡部委員","kind":"質問","question":"この間、お疲れさまでした。無事、終了するのかなというところなのですが、１件だけお伺いしたいのは、今回、国の制度として、日本全国の自治体がこれに携わってきた。テレビ報道とかをされる中で、品川区も大変なご苦労があったと思うのだけれども、どういう苦労があったかここで聞くのではなくて、ぜひ国に戻してほしい。ないなら、これは上げてほしいと思うのですけれども、いかがでしょうか。","respondent":"寺嶋特別定額給付金担当課長","answer":"どのような形で国に上げていくかというのは、またタイミング等が難しいかと思うのですが、少なくとも今後の方向性の中で、今回の経験を踏まえてぜひ意見をという機会があれば、積極的に発言はしていきたいというふうに考えておりますし、こちらから何か発信する機会が。","voiceIndex":31,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"コールセンターの問合せ件数、３万３,７０８件ということで、これも莫大な数になっていますが、このご相談内容の内訳、かなり大枠でもいいのですが、我々のもとには、今回、私も質問したことがありますが、これはやはり日本全体の家族制度の問題点でもあるのですが、やっぱり個人への支払いというのが今回はできなかった、世帯ごとであった、これは今回に関しては仕方ないと思うのですが。","respondent":"寺嶋特別定額給付金担当課長","answer":"委員のほうにご指摘いただきました世帯に関しては、国制度なので、なぜ個人単位でないかということを直接区に聞いてくる方はそれほど多かったとは記憶していないのですが、世帯の確認、同居しているご両親が世帯上同一になっているのかどうかが分からないので。","voiceIndex":34,"id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問","question":"さっきの渡部委員ではないですけれども、そういった声があったということを、何か国のほうに戻すような、そういうお問合せが多かったというような声を上げるということは、何か制度上あるのですか。制度上はない。","respondent":"寺嶋特別定額給付金担当課長","answer":"そのときに恐らくいろいろとこれに付随したやり取りというものが何か発生するのではないかということで考えていますけれども、もしそのときに声を上げるタイミングがあれば、ぜひ伝えていきたいと思います。","voiceIndex":36,"id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"もしかしたらこちらでお聞きすることではなくて担当課が違うのかもしれませんが、皆様、今回の振込で銀行口座を書いて区のほうに伝えたわけですけれども、その銀行口座の取扱いは今後どうなるのか。つまり、今後何かに、特に区の給付金には活用されたわけですけれども、保存の仕方、情報の確保の仕方と活用の仕方というのは、所管が違うかもしれないですが、どうなっているのか伺いたいです。","respondent":"寺嶋特別定額給付金担当課長","answer":"そういったことから言いまして、この後、この口座をほかのことに活用するということは今の段階では全く考えておりませんので、通常の年限どおり保存して、廃棄年度が来たら廃棄をするという、そういう手順になろうかと思います。","voiceIndex":38,"id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問","question":"その件について、担当も違うのかもしれませんが、また別の機会にお聞きします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ちなみに、委託の職員というのは、どれぐらいの体制だったのでしょうか。","respondent":"寺嶋特別定額給付金担当課長","answer":"委託については、人材派遣ではないので、何人という契約にはなっていないのですが、コールセンターには電話が１５台ありますとか、操作するパソコンは１５台ありますということで、それをフル活用して、しかも新型コロナウイルス感染症の防止対策として。","voiceIndex":43,"id":"exchange-016"}]},{"id":"topic-03","title":"令和３年度分品川区立高齢者住宅（単身用）補欠登録者の募集","agenda":"令和３年度分品川区立高齢者住宅（単身用）補欠登録者の募集","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"募集内容として、補欠登録者６０人程度と書いてあるのですけれども、実際にこの募集期間に、毎年、何人ぐらいが申込まれて、何人ぐらいが登録されているものなのですか。","respondent":"菅野高齢者地域支援課長","answer":"過去３年の実績を申し上げますと、昨年、令和元年度につきましては７７名の方が申込みをされまして、平成３０年度は５６名、平成２９年度は５９名ということで、大体、平均６０名前後に申込みしていただきまして、要件等を審査させていただき。","voiceIndex":49,"id":"exchange-017"},{"speaker":"おくの委員","kind":"質問","question":"今のが申込みをされた人数で、そのまま登録されているということですか。","respondent":"菅野高齢者地域支援課長","answer":"そのとおりです。","voiceIndex":51,"id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今、応募された方の人数ですけれども、入れた方の人数も教えていただけたらと思います。申請から入居までというところで、申請は１１月１６日から１１月２５日ということで、今までは結構、１２月第１週、１１月の末から１２月にかけてみたいなことが多かったと思うのですが、いつもより早くなっているような思いがするのですけれど、この理由が何かあるのかということもお聞かせください。","respondent":"菅野高齢者地域支援課長","answer":"募集の期間につきましては、今年度は１１月のこの期間ということなのですが、１２月から１１月に変えたということに、多分大きな理由はないとは思うのですが、昨年とほぼ同じような日程で今年度もしていますので、できるだけ、例えば１カ月とか。","voiceIndex":53,"id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう中で、高齢者の方々は住居が定まらないということが本当に不安で、病気になりそうなぐらい不安だというようなことでよく相談も受けるのですけれど、そういうところからすると、この高齢者住宅というのは貴重な存在だと思うのですが、ぜひこれはもっと数を増やしていただきたいと思うのですけれども、その点についてはどうでしょうかということと、これ、年に１回しか募集がないですね。","respondent":"菅野高齢者地域支援課長","answer":"それ以外の期間でタイミングが合わなかった方、お困りの方につきましては、随時、高齢者地域支援課の窓口で丁寧に相談対応させていただきまして、住宅のあっ旋事業等につなげしています。","voiceIndex":55,"id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もちろん民間住宅のあっ旋も何度もご相談に伺っているのですけれども、そのあっ旋で不動産屋を紹介していただいて行っても、そこでもなかなかないというのが現実なのです。だから、このあっ旋では、それは解消できないというような現実を思っております。そういう点で言えば、年２回というところは、ぜひ今後ご検討いただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-021"}]},{"id":"topic-04","title":"医療的ケア児地域生活支援促進事業に係る運営委託事業者の選定","agenda":"医療的ケア児地域生活支援促進事業に係る運営委託事業者の選定","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"幾つかお伺いいたします。これは、なぜ下がったのかお伺いしたいと思います。運営費がなぜ下がったのかお伺いしたいと思います。それから、議事録等も少し読ませていただいたのですが、こちらのフローレンスを選ばれて、体制が一体どうなっているのかということもお伺いしたいと思います。それもお伺いしたいと思います。お伺いしたいと思います。","respondent":"松山障害者福祉課長","answer":"５点目です。公募期間が２週間ということで短いのではないかというご質問ですが、公募期間につきましては、区のほうでは２週間というのが通例のものですので、決して短いという認識はございません。","voiceIndex":62,"id":"exchange-022"},{"speaker":"西村委員","kind":"質問","question":"３点ほどお伺いさせてください。２点目が、看護師の方や保育士の方の常駐の体制を今お伺いしたのですが、予約制での相談になるのか、お伺いしたときに常に相談ができるのか、どのような環境なのかを伺わせてください。３点目が、乳幼児のお子さんがメインになるのかというふうに何となく思うのですが、小学生なども来られるような場になるのか、年齢層の幅がありましたらお聞かせください。","respondent":"松山障害者福祉課長","answer":"ただし、始めるにあたっては、もう少し区との協議だったり、実態把握が必要ではないかと考えています。３点目ですけれども、年齢層についてです。確かに乳幼児、未就学児が中心になると今のところは考えております。","voiceIndex":64,"id":"exchange-023"},{"speaker":"西村委員","kind":"意見","question":"隣り合わせに児童センターがあるというところがすごく魅力だと思います。実際に品川区内でフローレンスにお預けになっている保護者の方から、障害をお持ちのお子さんだけの環境ではなくて、健常児と触れ合うことで身体能力がすごく上がったということを聞いていますので、ぜひそれは期待をしています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問","question":"それと、どちらの団体も存じ上げているのですが、フローレンスも有名ですし、ほわわの社会福祉法人むそう、医療的ケアのことを一生懸命やっている社会福祉法人はそんなに数が多くなく、限られているのですが、国のほうでも永田町子ども未来会議、野田聖子さんのところで一緒になってやられている、非常に緊密な関係があるというふうに聞いていますが、どういった形で連携をしていくのか。","respondent":"松山障害者福祉課長","answer":"医療的ケア児等支援関係機関連絡会にも、ほわわは入っておりますし、また、フローレンスにもご参加いただく予定ですので、区内に医療的ケアの知見や実績のある事業者が増えて、その中で連携を密にしていく。","voiceIndex":67,"id":"exchange-025"},{"speaker":"あくつ委員","kind":"確認","question":"一応念のため確認しますが、こちらの新しい施設は、お子さん一人の場面はない、基本的には親子でずっと一緒だと、こういうことでいいですか。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、親子での参加になります。","voiceIndex":69,"id":"exchange-026"}]},{"id":"topic-05","title":"品川区立障害児者総合支援施設","agenda":"品川区立障害児者総合支援施設","exchanges":[{"speaker":"西村委員","kind":"質問","question":"１点だけお伺いさせてください。その他の部分の、精神科デイ・ケアの見送りということですけれども、今、コロナ禍でもありますので、先方の見直しの中でそういった影響もあったのかということだけ伺わせてください。","respondent":"築山障害者施策推進担当課長","answer":"運営事業者のほうからは、申出のときに、今後のことを考えると、人を多く集めて行う事業については厳しいだろうということで、理事会等で判断をされたというふうに聞いております。","voiceIndex":79,"id":"exchange-027"},{"speaker":"おくの委員","kind":"質問","question":"これ、去年の１０月に始まった施設だと思うのですが、１年たつかたたないかのうちに、なぜ公募になってしまうのか、私が知る限り、非常に評判もいいですし、私も利用者の方からお話を伺いましたし、やめないでほしいと、非常にいいということで伺っているのです。一体なぜこういうことになったのか、どうしてこういうふうに決めてしまったのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-028"},{"speaker":"おくの委員","kind":"質問","question":"というふうに私は思いました。それで、なぜこれが公募になったのか、そういうことがいつどこで決まったのか、そういうことをお伺いしたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"公募の実施につきましては、平成３０年７月３０日の厚生委員会でご報告をさせていただいたときに、期間を３年とし、次回公募する旨のご説明をしています。","voiceIndex":85,"id":"exchange-029"},{"speaker":"おくの委員","kind":"質問","question":"建物全体の管理運営という点では、今の事業者に共同事業体という形で管理運営をやってもらっても構わないのではないですか。","respondent":"築山障害者施策推進担当課長","answer":"当時は運営事業者と一般社団法人を設立して、そこに建物管理を実施させる方法等も検討したのですが、幾つか課題があって、それは難しいということで、結果として区が建物管理をすることになったという経緯があります。","voiceIndex":87,"id":"exchange-030"},{"speaker":"おくの委員","kind":"質問","question":"事業体の方々は、今も建物管理は難しいとおっしゃっているのですか。","respondent":"築山障害者施策推進担当課長","answer":"私は、運営事業者から建物管理は難しいというふうに聞いておりますが、今回、公募をするということにつきましては、昨年度、事業者にはお伝えしておりますので、この間で検討はしているかと思います。","voiceIndex":89,"id":"exchange-031"},{"speaker":"おくの委員","kind":"質問","question":"公募ということは、平成３０年８月に決まっていた規定の方針ということで発しているという、そういうことなのですか。","respondent":"築山障害者施策推進担当課長","answer":"はい、そのとおりです。","voiceIndex":91,"id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"今、どこで公募が決められたのかというのは、２０１８年７月３０日の厚生委員会で説明しているというご答弁だったのでしょうか。それを確認させてください。そのような中で、１年もたたないうちにそういうふうに公募するということがどこで決められたのか伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"７月３０日の厚生委員会のやり取りの中で、当時の担当課長のほうから、３年後に公募を行うという旨を回答しています。","voiceIndex":93,"id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、こういう福祉施設は、これからモニタリングの報告もありますけれど、指定管理者は福祉施設たくさんありますけれど、継続性がすごく大事ということで、基本、公募をしないで、その利用者の方にとっての継続性ということが重視されて、５年たったら、またそこのところを５年後も選ぶというようなことでほとんどされてきたと思うのですが、継続性ということについては、どう考えられているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問","question":"委員長、途中ですけれども、いいですか。私も質問したいのですが、申し訳ないですけど、今、１つの会派でほとんどの時間をお使いになっているので、もし４５分で中断するとしても、もう１回そこは、１回中断という形でお願いしたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"私が申し上げたのは、先ほど言いましたように、２０１５年に、今までにないやり方を、４法人の共同事業体ということで、区がこういう形で、本当に期待を込めて選定をしたわけです。こういうやり方そのものが初めてのことですし、そういうところでは、その困難を乗り越えて期待を背負ってやってきた、そのことに対してどう考えているのかということを伺ったのです。","respondent":"築山障害者施策推進担当課長","answer":"今回の公募の実施というのは、先ほども説明させていただいたのですが、建物管理というところを、現在、区が実施しているというのが望ましい形ではないので、それを本来望ましい形である総合的・一体的な管理運営実施のために公募するという趣旨でありますので。","voiceIndex":99,"id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そこまで区としてすごく大きな期待をしながら、こういう形で全国的にも有名な事業者ですということも言われています。それと、今回もしこういう公募という形になったとしても、利用者の意向も汲むべきだと思うのですが、その点についてはどう考えられているのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"運営法人のほうには、先ほどもご説明いたしましたが、昨年度から公募を実施する旨は伝えておりますので、検討はされていることかと思います。利用者の意向ですが、この辺りも、今回の公募は建物管理の部分から始まっているところですので、そのために実施するというものです。","voiceIndex":102,"id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどから言っているように、この２０１５年の選んだ経過、どのような思いで選んだのか、そして選んだときの区の理由、大きな期待と、それから、それに応える形できめ細やかな事業がされている、そこのところに対して区としてどう評価されているのかということについてもお聞かせいただきたいと思います。それともう１つ……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それに関して、利用者、区民の声は関係ない、こういうように聞こえたのですが、ここに目的として、多様化する区民ニーズへの柔軟かつ迅速な対応、効率的で効果的な区民サービスの提供、こういったことが今回の中にもうたっているのですけれども、もう１回確認したいのですが、この公募の趣旨、その中に区民とか利用者の声というのは、全く関係ないのでしょうか。１点目、伺います。","respondent":"築山障害者施策推進担当課長","answer":"今回ご説明させていただいていることは、総合支援施設の公募を実施するというご報告についてです。先ほどから説明しておりますが、公募の実施にあたっては、建物を総合的に管理するという必要があるから公募をするというものです。","voiceIndex":110,"id":"exchange-039"},{"speaker":"あくつ委員","kind":"確認","question":"課長を個人的にどうのこうのというのはないですけれど、その説明が私はちょっとよく分からないです。法人の理念とか、ちょっとかみつくようですけれど、区民の声は、今回、公募のプロポーザルの中においては生かされる、当然生かされる、こういうことで確認させていただいてよろしいでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"事業者選定については、区民の声も審査項目の１つにはなってくるかと思います。","voiceIndex":112,"id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"審査項目の１つ、審査の条件の１つなのでしょうか、そういうふうに今聞こえたのですが、個人的には、利用者の声が一番大事だと思っています。これは１つの例です。そうした中で、もう１つ確認をさせていただきたいのが、先ほどの繰り返しになりますけれど、多様化する区民ニーズへの柔軟かつ迅速な対応、効率的で効果的な区民サービスの提供とうたってありますが、具体的にはどのようなことが必要なのですか。","respondent":"築山障害者施策推進担当課長","answer":"今回の公募につきましては、建物管理というところで、それも含めた総合的・一体的な施設の管理運営を行うために実施するというところが理由となっております。","voiceIndex":114,"id":"exchange-041"},{"speaker":"あくつ委員","kind":"質問","question":"これは私の感覚から言えば、かなり早い時期での公募になるのではないかということになるのですが、まずこれは、少し質問が前後しますけれど、現指定管理の団体、３団体においても、いわゆる共同体を組んで全体を管理したい、管理をするという意思を示した場合には、形式的には公募の要件を満たすのかどうかということが１つ。この３点をお伺いしたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"１点目ですが、募集の要件を満たせば、当然既存の法人も応募ができるものになっております。それから、２点目ですが、審査については、公平公正な選定を実施いたします。","voiceIndex":116,"id":"exchange-042"},{"speaker":"あくつ委員","kind":"質問・要望","question":"審査については公平公正にやっていただけると、こういうことは今、確認させていただきました。それと、今回の後半部分の要領の中で、４の基本事業と、４ページの７、応募要件、それと８、共同申請、ここに関して、１回目の２０１５年ですか、前の公募のときと大きく変更した点があるのかどうか。あるのであれば、どの部分を変更されたのか教えてください。","respondent":"築山障害者施策推進担当課長","answer":"前回と大きく変わっている点といたしましては、まず、５ページの８．複数の社会福祉法人による共同申請というところですが、(5)「共同事業体が選定された場合の代表団体は、指定までの期間中における、区との施設の管理運営に関するすべての協議の窓口となります。","voiceIndex":118,"id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問","question":"共同事業体が選ばれた後に、どの法人がどのところを担当するのかというところで、相当時間がかかったのは私も理解しているのですが、でもこれは、結局決まった後に責任区分を記した協定書を提出していただくということですから、前と何が違うのか、新しく加えたということはどういうことを意味しているのか、そこについてもう少し詳しく教えてください。","respondent":"築山障害者施策推進担当課長","answer":"現在の状況ですけれども、現在は個々で協定を結んでおりますので、共同事業体による協定書等は存在しておりません。代表としか協議しないというのは、総合的かつ一体的な管理運営を実施していただくために、そのような表記をさせていただいたものです。","voiceIndex":120,"id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問・要望","question":"総合的・一体的な管理をするのに、代表団体としか協議をしないというのはなぜなのでしょうか。全ての共同団体と協議をするのではなく、１団体とだけ協議をする。私はこの意味がよく分からないのですが、そこについて教えていただきたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"総合支援施設は多数の業務がありますが、それを総合的に運営していただくために、代表法人には包括的に責任を持って担っていただきたいというところがあります。","voiceIndex":122,"id":"exchange-045"},{"speaker":"あくつ委員","kind":"確認","question":"それはなぜこうなったのか、いわゆる共同団体とやり取りをしている中で不都合があったのかと思うのですが、そこはなかなかお答えいただけないので、これ以上は申し上げません。それと、もう１回確認したいのですが、クリニックの部分は今回対象ではないということになっていますが、今、ここを実施している団体、にっせいかんについては、いつまでの契約になっているのか教えてください。","respondent":"築山障害者施策推進担当課長","answer":"ですので、１０月１日から９月末までというのが１つの区切りになります。次のクールですが、デイ・ケアのサービスは実施しませんので、それ以外の事業について、また次の９月末までというふうに、１年ごととなっております。","voiceIndex":124,"id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問","question":"今の点でお聞きしたいのですが、今、９月末をもってということでしたが、では、クリニックについては、もう来年度の更新はされているということでいいのでしょうか。それと、デイ・ケアのところの広大なスペースという表現もありましたが、今回ではなくて以前の議会でそのような質問もありましたけれど、ここについては、どのような形で、令和４年１０月１日まで、お考えになるのか教えてください。","respondent":"築山障害者施策推進担当課長","answer":"クリニックにつきましては更新の手続きを行っているところです。デイ・ケアの後のスペースですが、こちらは地域活動支援センター等で利用しまして、そこで対象者を拡大したサービスを実施していきたいというふうに思っているところです。","voiceIndex":126,"id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最初にこの指定管理の候補が決まってから、そのときに私も一般質問に立ちました。この間、様々なことがありましたが、現状、利用者の方からそういう声が上がっているということは、絶対に不安にさせてはいけないし、今利用されている方が継続性をもってしっかりとケアを受けられるように、またサービスを受けられるように強く強く要望いたしまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-048"},{"speaker":"おくの委員","kind":"質問","question":"公募要領の８のところです。具体的なことですが、８の(1)で「共同事業体」となっていて、「法人」となっていない意味についてお伺いしたいと思います。それから、(5)、(6)のところで、これまで「代表法人」とか「構成法人」となっていたのが、「代表団体」とか「構成団体」というふうになっていて、「法人」という言葉が使われていない意味についてお伺いしたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"１点目、２点目の「法人」になっていない意味ですが、共同事業体は複数の法人で結成されておりまして、共同事業体そのものが法人格を持っているわけではないので、「共同事業体」というような表記になっております。","voiceIndex":130,"id":"exchange-049"},{"speaker":"おくの委員","kind":"質問","question":"(1)から(4)まで「法人」という言葉が使ってあって、(5)、(6)で「法人」ではなく「団体」という言葉が使ってあるのに特段意味はないのですか。","respondent":"築山障害者施策推進担当課長","answer":"そうですね、「代表法人」は構成団体の代表となる法人というところで書いております。「代表団体」という記載……。失礼いたしました。特に大きな違いはございません。失礼いたしました。","voiceIndex":132,"id":"exchange-050"},{"speaker":"おくの委員","kind":"質問","question":"審査会と選定委員会というのは、仕組みとして、実際に選ぶのは選定委員会だと考えてよろしいのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"はい、そのとおりです。指定管理者候補者を選定委員会で選定いたします。","voiceIndex":134,"id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"提案","question":"その際に、現行の状況を鑑みて、さらに一体的にということだと思うのですが、各法人の連携でいわゆる中心になっている法人が連携を速やかにできるようにという体制をとるためには、今回の選定の中でも、公募の要件にもありますが、先ほどから出ている代表法人になる法人とか、そういった共同事業体の中心の法人がきちんとした形で体制を。","respondent":"築山障害者施策推進担当課長","answer":"今後、ニーズが高まってきます高齢化・重度化に対応した支援をする施設、それから、親亡き後の介護を見据えた支援ということが重要になってきておりますので、そういった地域生活支援拠点としての役割を担っていく施設というふうに考えております。","voiceIndex":136,"id":"exchange-052"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうございました。それから、先ほどここでお話しした重度化関係の、あるいは医療の視点、大事になっておりますので、重要と考えていただいているので、ぜひその視点も選定の中に入れていただきたいと思います。もちろん指定管理者選定委員会の方々も十分にご理解の上で審査されると思うのですが、改めてその点をきちんと確認していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-053"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどの２０１８年７月３０日のところで、３年後には公募をするということでの議事録は教えていただいて確認させていただきました。なので、１年もたたずに公募というのは、いつ、誰が決めたのかということを改めてお答えいただきたいと思います。これは区自身が選んだことですから、しっかりと重く受止めていただきたいと思うのですが、そこの受止め方はどう考えられているのかお聞かせください。","respondent":"築山障害者施策推進担当課長","answer":"時期につきましては、選定後の準備期間等を踏まえて、妥当な時期というふうに判断しております。それから、２点目、３点目に関してですが、今回、選定をさせていただいたのですが、最初からお話ししておりますとおり、建物管理の実施というところで課題がございました。","voiceIndex":140,"id":"exchange-054"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"建物管理が課題だというところですが、８のところで、複数の社会福祉法人による共同申請ということで、この項目を設けているということは、今の事業所が継続することができるための項目として設けられているということですよね。そこのところを確認させていただきたい。事業所を変えるということを前提に今回の公募が出されているのではないという確認をさせていただきたいのですが、いかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"はい、委員のおっしゃるとおりです。","voiceIndex":142,"id":"exchange-055"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"改めて、利用者の意向、私はこれが最大に大事なことだと思うのですけれど、そこのところをどう考えているのか、そして、利用者の意向をぜひ聞き取っていただきたいと思うのですが、その点についてもお聞かせください。","respondent":"築山障害者施策推進担当課長","answer":"利用者の意向というところは、選定の中で利用者満足度等も審査項目の１つにはなってくるかというところで考えております。","voiceIndex":145,"id":"exchange-056"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、今回指定管理者が公募されると聞いただけで、利用者の中に本当に混乱が起こっていると思うのですが、そういうことをどう考えているのかということについてもお聞かせいただきたいと思います。選考にあたり、その支援の継続性、それから利用者の意向、区民の声、それから現事業所の実績、これらのことは反映されるのか、ぜひしていただきたいと思うのですが、いかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"ご質問の件ですが、まだこちらは公募もしておりませんので、この後どうなるかは未定の状態です。ですので、委員がおっしゃられたことは、選定の際の判断材料の１つにはなってくるかというふうに思っております。","voiceIndex":147,"id":"exchange-057"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、今までの福祉の考え方、それから、今回、新しい事業所を入れるということで、様々な困難を乗り越えて今回の開所に至ったという、そういう事実、そしてそれが大きな期待になっているという、利用者、それから団体の皆さん、家族の皆さん、そういう思いをしっかりと受止めていただいて、選考にあたっては、支援の継続性、利用者の意向、それから現事業者の実績。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-058"}]},{"id":"topic-06","title":"令和元年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"令和元年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"今日の報告を伺っても、あるいは読んでも思ったのですが、他意はないのですが、例えば、障害者福祉課をやり玉に上げるわけではないのですが、これを読んでいて、いろいろな数字も分からないのですが、私も勉強不足だからあまり細かいところに入ると、自分自身わけが分からなくなるので、分かりやすいところで言いますと、５９ページの真ん中より少し下の総括のところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-059"},{"speaker":"おくの委員","kind":"質問・要望","question":"いや、だから、具体的に書いていただきたいというところを指摘しているわけです。こういうところを具体的に書いてくださればということで……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-060"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういうことをお願いいたしたいと思います。それから、これは障害者福祉課に対してだけではなくて、高齢者福祉課、要するに、全般に対して要望したいのですが、その点、たまたまですけど、どのように考えられるかということを、たまたま障害者……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-061"},{"speaker":"おくの委員","kind":"質問","question":"今、具体的に書いてくださればと言ったところの内容を教えていただけますか。５９ページと６５ページ。","respondent":"松山障害者福祉課長","answer":"個別具体的な案件ですので、お一人のことだけを取上げて言っているわけではなく、西大井地区全般にある事業所、複数箇所に関わっているです。グループホーム連絡会につきましても、区内のグループホーム全体を含めた連絡会を主催していただいているです。","voiceIndex":165,"id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"平塚橋ゆうゆうプラザとか、平塚ゆうゆうプラザ、ゆうゆうプラザのところですが、ゆうゆうプラザの利用率は何を差しているのか教えていただきたいと思います。地域ミニデイをゆうゆうプラザでやられていると思うのですが、地域ミニデイの利用率がどうなっているのかというのは、この中には出ていないと思うのですが、その辺が分かったら教えていただきたいと思います。","respondent":"宮尾高齢者福祉課長、菅野高齢者地域支援課長","answer":"そういったいい取組み事例、逆に注意すべき事例、こういったことの事業者間での共有の場、正にこれが会議の重要なテーマの１つでありますので、よいものはみんなで共有をする、逆に、まずい例につきましてはお互いが気をつける。平塚のほうは、人数が延べで出ていないのですが、利用定員１０名で、回数は２５回実施というふうにいただいております。","voiceIndex":167,"id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"そういうものは、お互いに学び合いながらよりよくしていくということでの交流をされているということで確認していいかということをあとでお願いしたいと思います。だから、私はその利用実績を、介護保険の中でも総合事業という形で新しくできたものでありますので、ぜひこの中にそういう形で入れていただけたらというふうに思いますが、いかがでしょうか。","respondent":"宮尾高齢者福祉課長、菅野高齢者地域支援課長","answer":"そういった事例を横に展開させていく、そういう場としても活用しています。研修等も随時、１つのところでやるのではなく、例えば合同でやるとか、そういった取組みも進めさせていただいているところです。こちらの実績のところに、地域ミニデイの参加者数をというご質問だと思いますが、こちらのモニタリングの評価シートにつきましては、モニタリング・評価の目的に沿って項目立てて記載していますので。","voiceIndex":170,"id":"exchange-064"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それはご検討いただけたらと思います。そういうところを今までも指摘して、支出のところも分かるような形に、そしてトータルがどうだったのかという辺りが見えるような形にしていただきたいということで申し上げてきたところですが、そういう見直しは外部委員が入ることで改善がされるということで聞いたのですが、モニタリングの見直しはされないでそのままなのかということもお聞かせください。","respondent":"宮尾高齢者福祉課長、寺嶋福祉計画課長、松山障害者福祉課長","answer":"外部委員が入っているものにつきましては、今後やっていって、その在り方、それから内容も含めまして精査をしていくというふうになっているところです。モニタリングにつきましては、これは区が指定管理者として委託をしているという事業ですので、今の段階では、引き続き。令和元年度のところですが、生活訓練が６８.２％、一番下の数字が生活訓練。それから、機能訓練が２９.８％、生活介護が７８.３％という形で……。","voiceIndex":173,"id":"exchange-065"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"総合支援施設ですが、まだ始まって半年の状況の利用率ということなので、様々低いというようなことでのご報告がありましたけれど、４月からと言っても、新型コロナウイルス感染症の関係もあるので、利用率が今年度になったからといって、どんと上がったということではないのかもしれないですが、始まったところから今年度に入った変化というか、そこら辺はあるのか、それとも同じような状況が続いているのか。","respondent":"築山障害者施策推進担当課長","answer":"現在の状況ですが、相談については件数としてそんなに大きく変わってはいないですが、児童の計画相談を開始いたしました。それから、愛成会が実施している生活介護については、利用者数が増えてきております。就労継続支援Ｂ型については変わりありません。定員の変化はございません。","voiceIndex":179,"id":"exchange-066"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"就労Ｂがかなり、もともとの定員に対して少ない人数から始めて、卒業生も受入れていくという定員になっていると思うのですが、就労Ｂはかなり、１６.２％という令和元年度の実績ですけれど、この１０名に対して１６.２％というのが今年度も続いている状況なのでしょうか。増える見込みはあるのかということも含めて、分かったら教えてください。","respondent":"築山障害者施策推進担当課長","answer":"就労継続支援Ｂ型ですが、昨年度２名で、今年も、現在まだ２名ですので、稼働率については記載のとおりになっているところです。","voiceIndex":184,"id":"exchange-067"},{"speaker":"渡部委員","kind":"質問・要望","question":"例えば、安全面の強化が求められるというようなことが書かれていると、「おいおい」となるわけです。だけど、これが１年後、またこのシートが出てくるのだけど、去年課題になっていたものがどうなったかというのは、私は実は知らないけれど、そういうものは、このシートは出す、指導はする、その中でヒアリングでこういうふうに改善したとかいう報告は、担当課はそれぞれ受けているわけですか。","respondent":"寺嶋福祉計画課長","answer":"このシート、例えば単年度で改善できるものについては、もちろん改善するのですが、例えば稼働率が上がらないとか、人材確保が難しいとか、なかなか簡単に解決できないものについては、複数年続けて課題として上がってくるということがあります。","voiceIndex":186,"id":"exchange-068"},{"speaker":"渡部委員","kind":"意見","question":"要は、改善点が出ていたら、その改善がどうなったかということが知りたいといいますか、特に安全面の強化などと書かれてしまうと、「おい、大丈夫か」という話になりますので、その辺をしっかり押さえていらっしゃるならば、それはそれで問題はないので、引き続きよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":188,"id":"exchange-069"},{"speaker":"高橋（し）委員","kind":"質問","question":"障害児者総合支援施設の指定管理のことでお尋ねします。もちろん努力されて増やそうとした部分はあるのかもしれませんが、そういう部分についてお伺いします。もう１つは、細かくてすみません。そういうことについて、その時点でどうだったのか。そして今年度、人数を増やすためにこれだけの指定管理料を上げてほしいというか、人員を増やすためのそういった交渉とかはされているのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"指定管理料についてですが、グローのところでいきますと、これはどちらかといいますと、地域拠点相談支援センターとしては、区内の大人の相談、知的、身体、相談と３カ所あり、そこと比較しても決して低い数字ではなく、おおむね同じような数字になっているのですが。","voiceIndex":189,"id":"exchange-070"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、改善点については半期ごとにヒアリングをし、そこで事業者と話をしているということですので、今年度ももう半年たったので、恐らく今年度のことも事業者とお話しされていると思うので、まだ続くわけですから、ぜひその辺は直していただくように意見を言っていただきたいということ。最後、グローのそれだけ。","respondent":"築山障害者施策推進担当課長","answer":"引き続き、運営法人と協議をしていきまして、多くの方がご利用できるように進めていきたいと考えています。","voiceIndex":191,"id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問","question":"１点だけ。長くなってすみません。今のやり取りの中であったショートステイの部分、これはそもそも１２床あるけれど、当然、フル稼働などできないという中で、令和元年度１８.７％となっていますが、現状、年度を越えていますが、何％ぐらい受入れているのか、具体的な数字が分かれば教えてください。","respondent":"築山障害者施策推進担当課長","answer":"多いときだと、１日５名ぐらい受けていらっしゃるところになっております。","voiceIndex":193,"id":"exchange-072"},{"speaker":"あくつ委員","kind":"意見","question":"そういう点では、１８.７％だったものが、５０％まではいかないけれど、今、半分ぐらいになってきているということで、利用者からも実はお声を聞いています。非常に受けられるようになってきたということでお話を聞いていますので、そういったところもしっかり評価していかなければいけないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":197,"id":"exchange-073"}]},{"id":"topic-07","title":"品川区国民健康保険条例の一部を改正する条例付則に規定する規則で定める日を定める規則の一部改正","agenda":"品川区国民健康保険条例の一部を改正する条例付則に規定する規則で定める日を定める規則の一部改正","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"たしかうちの会派の質問で、傷病手当の対象になった人は１人もいないということだったような気がするのですが、国保で感染した人はいないということなのでしょうか。","respondent":"池田国保医療年金課長","answer":"以前は１件もなかったところですが、現在の申請状況をお話しいたしますと、申請書の問合せがあり申請書を送った件数が１４件ほどございまして、そのうち１０件の方の申請書を受理しています。実際に支給をしたのは１件ということで、不支給が２件。","voiceIndex":203,"id":"exchange-074"}]},{"id":"topic-08","title":"ロタウイルスワクチン定期接種の開始","agenda":"ロタウイルスワクチン定期接種の開始","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"これ、ワクチンが２種類あるのですが、なぜ２種類あるのかということをちょっと聞いておきたいということ。国が負担するということではないのですか。どういう負担になるのですか。お伺いいたします。","respondent":"鷹箸保健予防課長","answer":"なぜ２種類あるかですが、作っているメーカーが違うため、ワクチンの種類が違うのと、接種回数や方法も違います。現在につきましては、その７,０００円全額ではなくて、ワクチン接種にかかる費用の一部を区のほうで助成させていただいている形になります。","voiceIndex":209,"id":"exchange-075"},{"speaker":"鈴木（博）委員長","kind":"質問・要望","question":"１点だけ、私のほうから質問というか、要望があるのですが、超早期産の例えば２８週で生まれた子どもは、入院している最中にこのロタウイルスワクチンの期限が切れてしまうのですが、こういう人が、今、小児科医の間でどうしたらいいのだということで問題になっていますが、ぜひ品川区では救済措置の検討をお願いしたいと思います。これは要望で終わります。ほかにご意見はありますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":211,"id":"exchange-076"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今まで１回７,０００円で１人２回までの助成額が品川区のほうで出ていたと思うのですが、これで年間何人くらいの方がワクチンを受けられていたのか。それから、実際は医療機関によって多少違うのかもしれないですが、自己負担はどれぐらいあったのかということも分かったら教えていただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"任意の予防接種ですので、委員ご指摘のとおり、医療機関によって接種費用は異なりますが、おおむね２回接種するほうのロタリックスのほうが高くて、３回接種するほうのロタテックがワクチンの接種費用自体を比べると安いのですが、例えば７,０００円自己負担をお願いした場合。","voiceIndex":212,"id":"exchange-077"},{"speaker":"西村委員","kind":"質問","question":"１点だけすみません。２回接種か３回接種かは、区民の方がご自分で選ぶような感じですか。","respondent":"鷹箸保健予防課長","answer":"医療機関のほうでどちらのワクチンをされるかということは大体決めていらっしゃいますので、かかりつけの先生が選ばれているワクチンを、かかりつけの先生のところに行って受ける、そういう形になると思います。","voiceIndex":215,"id":"exchange-078"},{"speaker":"あくつ委員","kind":"確認","question":"それと、高齢者のほうは間に合わなかったので、２回送るというお話、１回でいいのですか、中に同封されているということでいいのですね。分かりました。これも確認できましたので。２,５００円と書いてあるけれど、無料で受けられますよというものが同封されているということで確認させていただいてよろしいですか。","respondent":"鷹箸保健予防課長","answer":"この方針が出たのがぎりぎりだったので、医師会のほうにも急ぎ併せて周知をいたしまして、今年については、高齢者の方がいらした場合に、自己負担をとらないでいただきたい、お支払いする必要はありませんということを併せて周知していますので。","voiceIndex":221,"id":"exchange-079"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それぞれ子どもの場合と高齢者の場合のインフルエンザの接種率を教えていただきたいのと、高齢者の場合は、２,５００円分全額東京都のほうから財源が来るということで、今回、実施になったということなのでしょうか。その財源のことについても教えてください。","respondent":"鷹箸保健予防課長","answer":"ただ、１０月１日から始まりますので、そうは言っておられません、これについては区の考え方として早くこの方針を打ち出したということになります。","voiceIndex":224,"id":"exchange-080"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3578#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":92431,"voices":235}},{"id":"r02-20200924-8","meetingId":"r02-cm09","date":"2020年9月24日","dateIso":"2020-09-24","committee":"建設委員会","time":"午前１０時００分～午後 １時３８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"会議の運営上、順番を変更して、初めに、(4)令和元年度指定管理者による管理に対するモニタリング・評価","agenda":"会議の運営上、順番を変更して、初めに、(4)令和元年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"住宅のほうなのですけれども、２件ともなのですが、実績のところで、滞納者１件あたりの対応回数ということで記載されているのですが、これを今回、この総括シートの中で示しているのがなぜなのかなということを率直に思いましたので、伺いたいと思います。","respondent":"森住宅課長","answer":"使用料につきましては、区営住宅のほうは下がっているですが、基本的には、それぞれの入居者の方の収入状況に応じて対応していますので、そのものが平成３０年度と比べて多少下がってきたというところかなというふうに考えています。","voiceIndex":7,"id":"exchange-001"},{"speaker":"のだて委員","kind":"確認","question":"分かりました。滞納者１件あたりの対応回数は重要な業務ということで示されているということですが、そうすると、どうなると評価が高いというか、回数が多いほうが評価が高いということになるのでしょうか。そこの確認と、そうすると、突然修繕しなければいけなくなったときに、指定管理者が負担をしなければならないということになってしまうということなのか、そこの仕組みを伺いたいと思います。","respondent":"森住宅課長","answer":"滞納者１件あたりの対応回数についてですが、これは回数が多いからといっていいかという話ではないのかなというふうには考えております。","voiceIndex":9,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"分かりました。最後に、職員の方、東急コミュニティーのほうは常勤職員３名というところでやっていらっしゃると。品川宅建管理センターのほうは常勤職員３名、管理主任が４名ということで、倍ぐらいの人数ということになりますが、棟数が、品川宅建管理センターのほうが多いわけなのですけれども、この体制の違いというのか、この体制で十分対応できているのか、そこを伺いたいと思います。","respondent":"森住宅課長","answer":"品川宅建管理センターにつきましては、区営住宅・区民住宅とも棟数も多くございまして、当然、区営住宅などでは高齢者も多いことから、基本的には対応も少し東急コミュニティーよりは多いのかなというふうには考えているところです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"自転車の駐輪場のほうなのですが、率直によく分からなかったのです。バイクの当日利用率のところが１００％を超えているのですが、これはどういうことなのかということでお聞きしたいと思います。それと、裏面の３のところで、アンケートを行っているということで、そのアンケート結果がどのように生かされているのか、伺いたいと思います。","respondent":"川口交通安全担当課長","answer":"３点目なのですけれども、アンケートの結果ですが、これにつきましては、それぞれ、先ほどもご説明させていただきましたように、いわゆる統括責任者による、各場長への指示ですとか、各自転車整理員に対する指示等に反映をさせて、このような意見・要望等もあるので。","voiceIndex":13,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"アンケートのところはいろいろ運営に生かしていっているということでしたけれども、何か具体的に。整理整頓の話は１つありましたけれども、こうやって改善されましたということとかがあったらご紹介いただけたらというふうに思います。先ほど、統括責任者のお話もありましたけれども、２３か所でどのように何人の方があたっていらっしゃるのか、そこを伺いたいと思います。","respondent":"川口交通安全担当課長","answer":"ところが、チャイルドシートを付けているような自転車の方ですと、最低でも４０ｃｍから６０ｃｍの寸法が欲しいというような意見・要望があった場合には、利用スペースで平置きのスペースに誘導するとか、そのようなサービスをしているとともに、また、駐輪場の電気が暗いとか。","voiceIndex":15,"id":"exchange-005"},{"speaker":"のだて委員","kind":"確認","question":"体制のところで、部長職の方がいろいろ場長の方に指示をしているということでした。具体的な数字は分からないということでしたが、そういった体制のところが、この整理整頓を小まめにやっていくということにも反映していくというふうに思います。そこは、きちんと確認できるような体制にしていくということが必要だと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"自転車等駐車場、日本コンピュータ・ダイナミクスというところが、ずっと長年のノウハウを持っていると。ここのところでは、お母さんたちが、要は荷物の多い云々と書いてある。その中の、支払いシステムについて伺いたいのですけれども、国でもデジタル庁などというものが立ち上げられるぐらい、行政はデジタル化が遅れているというような声が、新聞等々、マスコミには、報道等には出ているのです。","respondent":"川口交通安全担当課長","answer":"令和３年度末で今の指定管理者は一旦契約等を終了するのですけれども、その切り替えの際に、今後、実現可能性について検討してまいりたいというふうに、今のところ考えているところです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"住宅のほうです。区民住宅は、ここに利用率というのが見えないのですけれども、それが今どうなっているのか。その上での収納率という形になって、そして、管理運営委託料というのが発生しているのだろうなと思うのですが、それがどうなっているのかということ。これは倍くらい、もっと、３倍のところもありますよね。結構いい収益なのかななどと思っているのですけれども、その考え方はいかがでしょうか。","respondent":"森住宅課長","answer":"区民住宅のほうは多少、単年度で見ますと収納のほうが多いということではありますけれども、それぞれの使用者の使用料として適正なものをいただいているというふうに考えております。","voiceIndex":22,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"それと、自転車のほうなのですけれども、見ていただいている方というのは、シルバー人材センターからの派遣になるのだと思うのですが、その教育であったりとかというのは、大分きちんとされているとは思いますけれども、その辺も含めてのこの改善の取組なのだろうなと思いますが、その辺はいかがでしょうか。","respondent":"川口交通安全担当課長","answer":"区に対しても、個別の自転車等駐車場の係員の関係でお話をいただくことも確かにありますので、その辺のところは、指定管理者と連携を密にしながら改善に資するように実施をしています。","voiceIndex":24,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"個人名を出してはいけないかもしれないのですけれども、阪急のところの、線路側の駐輪場に、管理をしていただいている方が２人いらっしゃるのですよ。困っているとすぐ出してくれたりとか、あとは、「番号は何番ですか」とかと言ってくれたりして、非常に気持ちがいい状況なので、そういうところを参考にしていただいて、サービス向上を図っていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-010"}]},{"id":"topic-02","title":"令和２年１１月都営住宅入居者募集","agenda":"令和２年１１月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"都営住宅の募集ということですが、今年に入っての募集数と募集倍率を教えていただけたらと思います。","respondent":"森住宅課長","answer":"今年度になりますと、５月に募集されたものが公表されております。家族向の抽選で、区内の倍率といたしましては２５.３倍、都内全体で見ますと１４.２倍、病死等があった住宅につきましては、都内で５.１倍ということになってあります。","voiceIndex":31,"id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"区内では２５倍ということで、都内全体よりも高くなっているという状況ですので、やはり、この都営住宅を含め、公営住宅が求められているということだと思います。ですので、ぜひ、この都営住宅の増設を都に要望すべきではないかと思うのですけれども、いかがでしょうか。","respondent":"森住宅課長","answer":"都営住宅を増やすようにというお話ですが、都のほうでも、例えば多摩部のほうでは大分空きも目立っているというところでございまして、都の都営住宅の方針といたしましては、若者世代に入っていただくような施策に取り組んでいたり、あるいは。","voiceIndex":33,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"多摩部では空きがあるというお話でしたが、やはり都心に多くの方が住んでいるということだと思うのです。やはり需要があるのですから、そこに増設をしていくということが求められているということだと思いますので、ぜひ、区もそこの方針を改めて、増設を求めていっていただきたいということで要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-013"}]},{"id":"topic-03","title":"航空機騒音の短期的な測定の実施","agenda":"航空機騒音の短期的な測定の実施","exchanges":[{"speaker":"田中委員","kind":"意見","question":"短期的な測定が実施されるということなのですけれども、なぜ短期的なのかというところ。五反田文化センターに設置ということで、今、ご説明の中でも五反田文化センターがほかの設置場所との勘案から選ばれたということだったのですけれども、ほかに、五反田文化センター以外の候補があったのかなということを、もしご存じであったら報告していただければと思うのですが。","respondent":"鈴木都市計画課長","answer":"２点ご質問いただきましたが、まず、なぜ短期測定なのかですが、国のほうは本格実施開始以降、固定で、区内で言いますと３か所、これは新ルートを飛ぶたびに測定を行っているわけですが、やはり、さらにデータを蓄積して分析を行っていくのに、国としては、もう複数。","voiceIndex":51,"id":"exchange-014"},{"speaker":"田中委員","kind":"意見","question":"この短期間で２週間にわたって測定ということなのですけれども、もう既に設置はされているけれども、まだ開始はされていないということなのか、いつからいつまで測定するのかということと、その２週間を過ぎた後には、また別のところを設置するといった話があるのかというところを、２点お知らせください。","respondent":"鈴木都市計画課長","answer":"先ほど設置は完了し、今後というお話をさせていただきましたが、設置は完了していまして、９月２３日から１０月６日の間の２週間でいうところです。","voiceIndex":53,"id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"現在、区の測定状況の報告がまだ上がってきていなくて、国の測定とのすり合わせの結果、９月末には公表されるという、たしか一般質問でお答えがあったと思うのですけれども、その公表についてもそうなのですけれども、いつ頃、測定の公表がされるのかというのと、この短期間での測定についても、国が公表するので、それほど時間はかからずに公表されるのかといったところも確認させていただければと思います。","respondent":"鈴木都市計画課長","answer":"固定化回避に向けた検討会、１回目が行われてありますが、２回目の実施時期、これは前回、委員のほうから重ねて国のほうにと。","voiceIndex":55,"id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"今回のこの短期的な測定の実施について、区としてはどのように捉えているのかというところ。検討会について、まだ日程などが決まっていないということだったのですけれども、区としてどのように求めていくのか、あと、今、この期間、何を求めているのか、ということをお知らせいただければと思います。","respondent":"鈴木都市計画課長","answer":"固定化回避に向けた検討会について、まだ次回が決まっていないことへの区の受け止めですが、基本的には、国のほうは、大臣が会見でも発言されてありますが、さまざまな技術的な視点で検討を加えながら、一定。","voiceIndex":57,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"再三、検討会のスケジュールを確認してほしいと、区としても要望すべきということを訴えているのですけれども、やはり、年度末の取りまとめまでに、スケジュール感が全く出てこないというのは、とても怖いなというか、どのように進んでいくかも見えてこないという今の状況で、先ほどご答弁の中にもありましたけれども、やはり、区民生活が脅かされているこの状況に対して。","respondent":"鈴木都市計画課長","answer":"年度末に向けた細かいスケジュール感と、それから、そのスケジュール感をお示しいただくことの要望書等を出すかどうかについての区の考え方ですが、この固定化回避に向けての強い要望につきましては、当委員会でもご説明しましたが、５月に区長が国土交通省を訪問しまして。","voiceIndex":59,"id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"区としての強い要望を国が聞き取って検討会が実現されたということでしたので、もしそうであるならば、ではその年度末までに取りまとめるためにも、もう１０月になりますし、半年のスケジュール感でどう取りまとめていくのか、具体的な案というのが、この短い期間にできるのかというところも、区としてもっと本当に求めていくべきだと思うのですけれども、そのところに関してどうお考えでしょうか。","respondent":"鈴木都市計画課長","answer":"この検討会の進め方につきましては、繰り返しになりますが、大臣自ら会見の場で、年度末にはしっかりと取りまとめてお示しすると。これは強い言葉でいただいてあります。","voiceIndex":61,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"検討会の要望はこれからも引き続き。要望と、あと、いつ開催されるのかということは、いつも聞いてくださる。区が国へ出した５月の要望はとても強いものだったというお話だったのですけれども、私たち生活者ネットワークは全くそのように思っていなくて、区として、きちんと白紙撤回を求めてほしいということは重ねて要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"そう考えると、１か所だけじゃなくてもっと多くてもいいのではないかと。どういうところで、どういう影響が出ているのかということを把握して、また、それを継続的に、やはり固定で見ていかなければいけないということにもつながってくるのではないかというふうに思うのです。区と国との協議の中で、どういった話し合いがあったのか伺えたらと思います。","respondent":"鈴木都市計画課長","answer":"区として、こちらから積極的に、さらに３か所、４か所と測定局を設置していただきたいという要望は、今のところは考えてございませんが、短期測定というのは、丁寧な説明の観点の中ではありがたい、しっかりやっていただきたいという受け止めです。","voiceIndex":66,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、最後がまとめの確認ということで、もう１回、間にあれば、まとめの素案みたいなものが出てきて、最後にまとめていくということになるかというふうに思ってしまうのですね。つまりは、羽田新ルートの見直しも含めて、ルート変更も含めて議論をしていただきたいということで、区のほうで要望していくべきではないかと、ぜひ要望していただきたいと思うのですけれども、いかがですか。","respondent":"鈴木都市計画課長","answer":"検討会について、年度末に向けて回数を重ねて議論をというところ、これを区として要望するべきではないかですが、どういう回数を重ねて、どういう内容で進めるかについては、これは当然、会の主催である国がしっかりと検討を行って考えるべきであって、それによって議論が薄まる。","voiceIndex":68,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません。先ほど聞き忘れてしまったのですけれども、今度設置される五反田文化センターでの設置場所は、路上なのか、それとも屋上なのか、その場所についてお知らせいただきたいと思います。","respondent":"鈴木都市計画課長","answer":"建物の屋上だと思います。","voiceIndex":70,"id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私たちの感覚では、自民党品川総支部で固定化回避の要望書は出して、直接、政務官に出しに行ったりして、きちんと、「それは分かりました」と言って、こういう会ができるようになったと我々は理解しているので、来年３月、年度末は期待しています。１年経つと、６割とは言っていたけれど、現実どうだったかというのも、ぜひ分かるようにしていっていただきたいなと思いますので、お願いだけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"すみません。二重になったらごめんなさい。「夏季、冬季にそれぞれ１週間の測定を実施します」という、この冬季というのは何月頃とかというのは出ていましたでしょうか。冬というと１２月、１月、２月という感じなので、「それぞれ１週間」というこの意味。北風経路で。これはどういう方法なのか。お願いします。","respondent":"鈴木都市計画課長","answer":"今、ご質問もいただきました、夏季２週間、北風、これは、どうしても品川区内は南風のみのルートになりますので、この件については細かく確認をしているのですが、北風については「夏季、冬季にそれぞれ１週間の測定を実施」。","voiceIndex":75,"id":"exchange-025"},{"speaker":"田中委員","kind":"確認","question":"今の北風のところなのですけれども、確かに品川区の上空は飛ばないのですけれども、北風ルートのときに、八潮のほうでは特に、音が結構聞こえるという声が届いているのですね。時によって、荏原のほうでも、朝方、離陸の音がすごく大きい。でも、それでもやはり品川区の上空は飛ばないからということで測定はストップしてしまうのですか。その辺の確認はしてほしいのですけれども、どうなのでしょうか。","respondent":"鈴木都市計画課長","answer":"先ほどからご答弁申し上げているとおり、北風時については品川区上空を飛ばないですから、品川区内には固定局が３局ございまして、五反田文化センターでも短期で設置するわけですが、例えば、音は、今日が南風だから人がスイッチを入れて今日測定しますということではなくて。","voiceIndex":78,"id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"今、八潮で、北風ルートのときにもうるさく聞こえてくるということがあるので、それについても測定の結果がもし出せるならば、出してほしいなと思っているのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"この数字の音を実際に見ていただくということで、十分ではないか、まさに、これが大事ではないかというふうに考えてあります。","voiceIndex":80,"id":"exchange-027"},{"speaker":"大沢委員","kind":"確認","question":"先ほど西本委員から、冬季ということで、１２月、１月、２月という話が出たのですけれども、季節の「季」と期間の「期」と２つあるわけではないですか。そのあたりを、国のほうはきちんと使い分けてやっているわけで、季節の「季」だから、あくまでも季節感ということなので、冬の季節感を捉えるところだから、期間は決まっていないわけですよね。何月から何月と。ここのところを確認です。","respondent":"鈴木都市計画課長","answer":"今まさに委員にご指摘いただいたように、現在、もう９月末ということで、季節的には秋に入っていくような状況の中で、北風・南風を語るときに、国のほうは、冬季・夏季で使い分けているようなところもありまして。そうですね。季節の。そのような考えです。","voiceIndex":82,"id":"exchange-028"}]},{"id":"topic-04","title":"立会川緑道整備工事","agenda":"立会川緑道整備工事","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"どっちをとるのかと言ったら、整備しなければいけないということがあるので、あきらめる部分は往々にしてあるのですけれども、そういうものも今後生かしていただきたいなと。だから、遊歩道を広げるというのはあるのですけれども、もうちょっと端のほうに、遊び感覚があるような、子どもたちが自然に触れ合えるような、そういう雰囲気があると助かるなという感じはあるのですけれども、いかがですか。","respondent":"溝口道路課長","answer":"委員ご指摘のように、これまでふたかけして、地域の方々に親しまれてきた緑道であるというのは、私どもも十分認識しております。そうした中、時代背景等いろいろある中で、利用の仕方というのが変わってきているというのも実態としてあると思います。","voiceIndex":89,"id":"exchange-029"},{"speaker":"西本委員","kind":"確認","question":"そうですよね。よく分かります。１点、緊急車両が通行できるということなのですけれども、これは通常は止めるということでよろしいのでしょうか。確認します。","respondent":"溝口道路課長","answer":"ただ、緊急時には、そういう車止めを外すことによって、中まで入って消防活動にあたれたりとか、そういった緊急活動が行えるような道路にしていくということで考えております。","voiceIndex":91,"id":"exchange-030"},{"speaker":"西本委員","kind":"確認","question":"すみません。１つ確認を忘れました。下のほうの図の左側のほうにも自転車が通れる道があるのですよ。これは、これだと変わらないのですけれども、ここはやはり整備はもう難しいのでしょうか。","respondent":"溝口道路課長","answer":"資料の６の代表断面図を見ていただければと思います。現況と計画とを併せて２ｍの道、１段下がったところに自転車の絵が描いてあるところがあります。","voiceIndex":93,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"２ｍですから、それほど行き来ができないのですよね。ですので、例えば一方通行、左側は右のほうにとか、もう１つは逆方向にとかという、そういう形でやったほうが危険が少ないのかななどと思ったりするのです。閉じることはできないのですけれども、やはり安全性を踏まえた形で、どういう自転車の使い方がいいのか、分けられれば一番いいのかななどと思うのですけれども、その辺の工夫はいかがですか。","respondent":"溝口道路課長","answer":"そういった中で、右側通行とか、そういったところの矢印等を施すことによっての誘導というのはしていきたいというふうには考えておりますが、いずれにしましても、初めてここを正式に通すような形になりますので、利用形態を見ながら。","voiceIndex":95,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"私も西本委員と全く同じ意見でして、子どもたちがとても楽しめる場所であるので、こうやって変わっていってしまうのは、少し悲しいなというのを思うのです。お散歩コースだったりとか、やはり楽しめる場所になっているので、話をしていただきたいと思います。この辺のところが、こんなに減ってしまうのかと、断面図を見て驚いてしまったので、この辺りをお知らせいただければ。","respondent":"溝口道路課長","answer":"ただ、今回の整備計画・方針、または工事にあたりましては、近隣の町会ですとか、沿道の方に各戸訪問したり、説明会などというのを重ねながら来ているところですので、この形でできれば整備をしていきたいというふうに思っています。","voiceIndex":98,"id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"１点だけ確認させていただきたいのですが、今回、４年間で整備していくということで、１工区から４工区とあります。両側から整備されていくということになっていますけれども、なぜそういう進め方になるのかということについてお聞かせください。","respondent":"溝口道路課長","answer":"そういった中、１工区、前年度実施したところにつきましては、もともと、大人たちが夜たまってお酒を飲んだりするという、そういった地域としての課題を何とか解決してほしいという強い要望がありましたので、まず最初に荏原町駅側のほうを。","voiceIndex":101,"id":"exchange-034"}]},{"id":"topic-05","title":"第二戸越幹線整備工事（北品川立坑）","agenda":"第二戸越幹線整備工事（北品川立坑）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"変更内容ということで５点、ご説明があったのですけれども、イメージができなかったというか、なぜこの変更が生じたのかというところでご説明いただけたらと思うのです。２番目の、受入基準を満たさなかった泥土処分の受入施設を追加するというのはよく分からなかったので伺いたいと思います。そして、３番目の、工事現場出入口の形状がなぜ変更になったのかというところでご説明いただければと思います。","respondent":"松本河川下水道課長","answer":"３番目の出入口ですが、出入口につきましては、事前に東京都の第二建設事務所と協議はしておりましたが、請負事業者が決まった後、改めて、大型重機であるとか、大型車両を選定した後、出入りの方法を改めて検討し、舗装の構造や安全の内容に変更が生じたためです。","voiceIndex":108,"id":"exchange-035"},{"speaker":"のだて委員","kind":"意見","question":"泥土の受入れのところで、再資源化、受入基準を満たさなかった分を、ほかの処理施設に受入れていくということなのですよね。敷地内で溜めておくところを作るということなのか、その辺がよく分からなかったので、もう一度説明いただけますか。","respondent":"松本河川下水道課長","answer":"当初、想定していましたのは、外部の施設で処理をする予定でございました。そこの受入基準を満たさなかった土壌がございましたので、その土を、今度、受入れられる施設に切り替えたということで変更が生じたものです。","voiceIndex":110,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"これは下流部と上流部に分けられているのですよね。それで、子供の森公園も、これは同じ時期に同時進行でやっていたのでしょうか。それとも、別々だったのでしょうか。初めから上流部、下流部という形での設計になっていて、同時に立坑を掘って、シールドで掘っていっているという感覚なのか、それとも、下流部はまた別というふうな感覚なのか、この辺の工事の概要というのを教えてほしいのですけれども。","respondent":"松本河川下水道課長","answer":"コロナの件ですが、今回、工事を一時中止いたしましたのは、緊急事態宣言がありました４月２７日から５月８日までの間の平日の６日間です。それに関わる経費といたしまして、４０万円ほど、今回変更させていただいているところです。","voiceIndex":113,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"これは目黒川のところですね。目黒川の水位を下げるというか、抜け道として、この第二戸越幹線整備という形になっていると思うのですけれども、そういう形でいいのですよね。上流部のほうを先にやっていて、下流部のほうが、今、立坑で掘っていって、最終的には上流と下流が合流するという形で、これによって目黒川の氾濫が大分減るというふうな想定で設計されているということでしょうか。","respondent":"松本河川下水道課長","answer":"今回のこの第二戸越幹線工事というものは、目黒川から水をとるというものではなくて、平塚地区であるとか、そちらの雨を目黒川に流すための下水道工事です。","voiceIndex":115,"id":"exchange-038"},{"speaker":"石田（秀）委員","kind":"確認","question":"すみません。１点だけ教えてください。今、立坑を掘っている敷地がありますよね。あそこは、完成後、例えば、全くの更地になるのか、何らかのものは残るのか。なぜこのようなことを聞くかというと、一緒に一体で公園整備をするではないですか。全く更地と思えば、いろいろなことを一緒に一体になってやれるのだけれども、何か表面に残る場所というのはあるのですか。それだけ確認させてください。","respondent":"松本河川下水道課長","answer":"併せまして、今、検討していますが、ここに水が入ると、どうしても中にある空気が抜ける道を作らなければいけませんので、もしかすると、そういった空気が抜けるための施設等が地上部に出る可能性はあります。","voiceIndex":118,"id":"exchange-039"},{"speaker":"石田（秀）委員","kind":"質問","question":"そのマンホールとか空気口というのは、もう公園課と打ち合わせをして、例えば、一番端っこの邪魔にならないようなところにしようとか、そういう話というのは、もちろんやっていらっしゃると思うのだけれども、我々はそういう感覚でいていいのでしょうか。","respondent":"松本河川下水道課長","answer":"もちろん、ここは公園用地ということで考えてありますので、そういった施設を邪魔にならないところに設置したいということで、これから具体的な検討に入っていきたいというふうに考えてあります。","voiceIndex":120,"id":"exchange-040"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"少し外れてしまうかもしれないのですが、この間、Ｊアラートでしたか、間違って放送されましたね。あのときに、非常に聞きやすかったのですよ。通常、例えば、「熱中症に気をつけてください」とか、いろいろ防災行政無線を使っていると思うのですけれども、非常に聞きやすかったのはなぜだろうと、非常に不思議だったのです。それとも地域がそうなのか、何かそこは変わっているのですか。","respondent":"大森災害対策担当課長","answer":"委員ご指摘のありました、聞きやすかったというところなのですが、区としては、区民の皆さんのご意見等を踏まえながら、いろいろな音量調整などを含めて、調査等をしながら整備をしているところなのですけれども、区としての認識ですと、特に。","voiceIndex":128,"id":"exchange-041"},{"speaker":"西本委員","kind":"意見","question":"何もしていないということですが、確かに聞きやすかったのですよね。いいのですよ。聞きやすくなっているのであれば。感覚の違いかもしれませんけれども、そういう感覚があったので、もしも何か違いがあって、いい方向にあるのだったならば、そちらのほうが聞きやすいのかななどと思ったので、感想を言わせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":130,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4302#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":34191,"voices":132}},{"id":"r02-20200924-9","meetingId":"r02-cm09","date":"2020年9月24日","dateIso":"2020-09-24","committee":"文教委員会","time":"午前１０時００分～午後 ３時０８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を76件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"旧三井文庫第二書庫の国登録有形文化財登録","agenda":"旧三井文庫第二書庫の国登録有形文化財登録","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"基礎的なことで申し訳ないのですが、登録というところで変わるところといいますか、特にメンテナンスの義務規定など、保存の義務みたいなものも発生するのではないかと思うのですけれど、その辺はどうなのかというのと、価値あるものなので、やはり区民が触れられるように方策を何らか取っていただきたいと思うのですけれども、常時開放というのは難しいかもしれないのですが、例えば、日を決めて。","respondent":"有馬庶務課長","answer":"広報などでＰＲすることももちろんですけれども、今委員が言われたように、オープンしなけんというか、そういう建物を見学するツアーがありますので、そういったところに、この書庫もメニューに入れてもらうとか、あと文化財週間というものが１１月にはありますので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あべ委員","kind":"確認","question":"確認なのですけれども、品川区内に今、指定文化財、登録文化財、今回のものを入れて、それぞれ何件になるのでしょうか。","respondent":"有馬庶務課長","answer":"国の指定文化財で、今回のような建物というのは１件です。これは、清泉女子大学にある旧島津邸が１件です。いろいろな工芸品とか絵画とか天然記念物とか、全部含めて２０件です。それから登録文化財については、今回の旧三井文庫を合わせて５件ということになります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"あべ委員","kind":"質問","question":"ほかに、平塚のほうにもありましたか。比較的、地域的にも近いところなどは、回遊式のことも考えてもいいかと思いますし、それを核として、あの一帯を何か文化的に盛り上げるといいますか、文化を面的に感じられるようなことというのも、今後考えていったらいいのではないかとも感じるのですけれども、今、教育委員会はどのような形で考えていらっしゃるのでしょうか。","respondent":"有馬庶務課長","answer":"登録文化財を中心に巡るというところですけれども、今回、併せて、古民家が１つなったのですけれど、まだそこに住んでいらっしゃるので、ある程度、そっとしておいていただければというか、大々的にＰＲはしてもらわないほうがいいというようなこともありますので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"著名な方々のお墓ですとか、ゆかりの場所ですとか、様々なものがあるのに、あるとぜいたくになるといいますか、一つ一つが意識されていない部分が、我が家の近くにもたくさんあると感じておりまして、ぜひこれを機会に、文化財あるいは文化について区民にもっと親しんでもらうという機会を、年３回と言わず増やしていただければと思いますので、要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"今のに関連するのですけど、今後あそこの近くに環境の拠点ができますので、そこに子どもたちが当然行くでしょうから、その際には、中は限られた中で見られないかもしれないけれど、外からでもそういうものを勉強する意味で、当然お考えになられると思うのですけれど、そういうものもぜひ含めてご検討いただければと思いますが、一応、ではお考えを。","respondent":"有馬庶務課長","answer":"せっかくの場ですので、我々の所管している大森貝塚も併せて、子どもたちは品川歴史館にも行っていますので、それと併せて、ここもこういう文化的な価値があるのだということは、子どもたちにも紹介していきたいと考えております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"筒井委員","kind":"質問・要望","question":"今、ＰＲのお話も出ましたけれども、今現在、登録文化財は、今回の旧三井文庫を入れて５件というお話でしたが、品川区のホームページを見ますと、指定文化財は掲載されているのですけれど、登録文化財については何も掲載されていないので、ぜひ今回の旧三井文庫の登録をきっかけとして、登録文化財も、もうちょっと、まずホームページに記載するなどのことをやっていただきたいと思っているのですが、その点。","respondent":"有馬庶務課長","answer":"ホームページの掲載については、所有者様との同意を得られればというところで進めていけたらと考えています。今回の三井文庫は区所有ということで、区所有では初めてですので、これは今後、ホームページに上げていきたいと考えています。","voiceIndex":14,"id":"exchange-006"}]},{"id":"topic-02","title":"令和元年度保護者アンケートおよび児童・生徒アンケートの結果","agenda":"令和元年度保護者アンケートおよび児童・生徒アンケートの結果","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、学校ごとの集計のデータについて、区教育委員会としては把握しているみたいなご説明がありましたけれども、この結果をどの程度、各学校に区教育委員会として、何というのでしょう、具体的にどういう活用を求めているのかというのを、もう少し伺わせていただきたいというのが３点目です。お願いします。","respondent":"工藤指導課長","answer":"学校においては、これを、先ほど申し上げたように、学校評価を各校独自にＣＳなどで行いますけれども、その際にもこの項目はさらに細かく聞くということを、校区教育協働委員会などで検討して行うということもありますので、そういった意味で活用いただきたいということで。","voiceIndex":20,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"アンケートというのは本当に難しいと私は思うのです。学校ごとの結果を殊さら強調して、その改善を過剰に求めることはやるべきではないと思いますけれども、いかがでしょうか。続けて質問しますけれども、「現在通っている学校に満足している」という設問があるのですが、これは保護者のみに聞いていて、児童・生徒には聞いていないのですけれども、これはなぜでしょうか。","respondent":"工藤指導課長","answer":"児童・生徒につきましては、様々な、先ほど来説明しているように、例えば学校や家での様子などというところの中から、子どもたちが学校生活の中で人間関係をどう築いているかなどの調査結果から。","voiceIndex":22,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"それで、やはり子どもに聞くべきなのではないか。区のこのアンケートと、自己肯定感や幸福度とは、単純にイコールではもちろんないと思いますけれど、その後の検討の進捗といいますか、今後、なぜ学年が上がるにつれて自己肯定感が下がってしまうのかということの検討をしていきたいというご答弁もあったので、その後どうなったのかというのをお伺いしたいというのが質問です。以上です。","respondent":"工藤指導課長","answer":"ご質問いただきました点につきまして、まず、本アンケートの概要版でもご説明した、「社会の様々な人々の個性を尊重し、認め合いながら関わることができる」という項目があります。","voiceIndex":24,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"なかなか、子どもの心というか肯定感、非常に難しいテーマだと思いますし、このアンケートで一律に単純に分かるというものでもないと思いますが、今の区の考えは分かりましたけど、なかなか、自己肯定感というのは、教科の市民科で促せば上がるかというと、そう単純なものでも、もちろんそうとは考えていないと思いますけれど、そうではないと思いますし、やはり子どもを取り巻く環境全体というのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"この調査なのですけれども、いつ頃から実施されているのかということと、内容は多分、ほぼ、割と似た内容で、プラス、その時々の課題も少し入れるというような構造になっているかと思うのですけれど、そこの概要を教えてください。","respondent":"工藤指導課長","answer":"保護者アンケートにつきましては平成２４年度から、児童・生徒アンケートにつきましては平成２５年度から実施しているものです。特に直近のアンケート項目、例えば一昨年、平成３０年度、また平成２９年度というのは、基本的には同じ項目で取っていたというところがあります。","voiceIndex":27,"id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"これを実施するのに、学校の現場も教育委員会も、結構大変なのではないかと思います。それから市民科の評価や、あるいは学校生活に対する評価というのは、去年と比べてどうだったというより、せっかく平成２４年から取っているのであれば、やはり１０年単位で推移を見ていくというようなこともあってもいいのかと思うのですけど、そういうこともされていますでしょうか。","respondent":"工藤指導課長","answer":"そういった項目はあるのですけれども、今回、３年に一度の項目にするという精査などを行ったのは、やはりそうすると３年前との比較ができるであるとか、３年間経つと、これまで１回で行っていたものを、全ての保護者、児童・生徒も調査することができますので。","voiceIndex":29,"id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"それで、こうした集計というのは、やはりパソコンはすごく相性がいいので、そうしたものも、アンケート、特に保護者アンケートなどにも活用される方向で考えられると、なお一層学校現場の負担というのが、いきなり１００％にはならなくても、こういう答え方もあると、逆に保護者の方にとってもかなり負担の減になるし、学校現場にとっても負担の減になるのではないかと思いますけど。","respondent":"工藤指導課長","answer":"それは、様々な方法を検討しているところで、昨年度も紙でということで行ったところですが、その取り方についてもまた様々検討しながら進めたいと考えているところではあります。","voiceIndex":31,"id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"学校選択制についてのアンケートで、特に７年生のところ、保護者アンケートと児童・生徒アンケートで同じなのですけれど、指定校以外を「希望申請して、希望の学校に入学した」と回答した方について、部活動というのがかなり、１６.１％、児童・生徒に至っては１９％と高いのですけれど、どういった理由なのか。理由のさらなる詳細というか内訳が分かりましたら教えてください。","respondent":"工藤指導課長","answer":"今、ご質問いただきました、いわゆる詳細につきましては、選んだ方のそれぞれさらにというところは取っていないところですので、そこの詳細というのは、例えば内訳、生徒の１９％の中がどういうところかというのは把握していないところはあるのですけれども。","voiceIndex":33,"id":"exchange-014"},{"speaker":"筒井委員","kind":"質問","question":"平成３０年度のアンケート結果を見ましたところ、部活動という項目が、たしか前回は１桁ぐらいだったように記憶しているのですけれども、要は１０％ぐらい、部活動という項目を重視されてきたのかとは、単純に数字だけ見ると思っているのですが、１桁から、このように２桁になった理由というのは、どう分析されていますでしょうか。","respondent":"工藤指導課長","answer":"その理由については、私どもは把握していないところではありますけれども、そういうところが１点あります。ですので、この１９％が単純に昨年度と比較してということではないというところをご理解いただければと思います。","voiceIndex":35,"id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"幾つか確認します。先ほどからもご説明がありますけれども、昨年までは２５項目ですとか２６項目ぐらいある中で、今回は十数項目ということで、見直しを行っていただいて、より効果的な分析を行っていただくという方針ということで理解しておりますが、ちょっと確認なのですけれども、昨年の６番ですか、児童・生徒のほうの、２年生ですと、「良いクラスをつくるため、話合いで意見を言える。","respondent":"工藤指導課長","answer":"その円グラフの結果、または昨年度とも比較しながら、またさらに、自治的な活動の領域であるとか文化創造の領域もありますので、そういったバランスを考えながら今後さらに検討したいと思います。","voiceIndex":37,"id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"最後に市民科の部分なのですけれども、先ほどもちょっと議論にありましたが、保護者の方が、学年が上がっていくと、なかなか授業を見る機会が少なくなったり、生徒が保護者の方にはなかなかそういったお話をしなくなるというような傾向があるということだったのですけれど、品川区の市民科の授業というのは、私はすごくすばらしいと考えていますので。","respondent":"工藤指導課長","answer":"今、ご指摘いただきましたとおり、やはり市民科を中心にしながら、学校で行っていることを家庭で話題にしていただくというのは、児童・生徒の成長にとって非常に有効であると私どもは認識していますので、各学校が、学校だよりあるいはホームページ、またはその他、小学校。","voiceIndex":39,"id":"exchange-017"},{"speaker":"せお委員","kind":"質問","question":"１点だけすみません。児童・生徒アンケートの（３）ですか、概要にも書かれているのですけれども、「社会の様々な人々の個性を尊重し、認め合いながら関わることができる。」というのは、どのような場面を想定して質問されているのか、どのような目的などがあって質問されているのかというのをお聞かせください。","respondent":"工藤指導課長","answer":"今、ご質問いただきました、例えば場面ということであれば、特に５年生から９年生のところは、「社会の様々な人々」とあるところではありますので、これはいわゆる学校に限らず、身の回りでご自身が生活する場面全てにおいて、やはり「個性を尊重し。","voiceIndex":41,"id":"exchange-018"},{"speaker":"せお委員","kind":"質問","question":"そうすると、それを教える学校生活、教えていくような場面というか、そういったものというのは今現在、どのようなところで教えているのでしょうか。","respondent":"工藤指導課長","answer":"個々の事象というのはあるとは思いますけれども、全ての場面に必要であると認識しています。","voiceIndex":43,"id":"exchange-019"},{"speaker":"せお委員","kind":"質問・要望","question":"とても大事なことで、社会に出ていく上でとても重要なことになってきますので、改めて授業というわけではなく、やはり、ご答弁にあったように、いろいろな場面で伝えていく場所をつくっていただきたい。よろしくお願いします。以上です。","respondent":"工藤指導課長","answer":"部活動のところで、若干、数字が上がってきたというところは、私どもは働き方改革の観点でも部活動指導員を入れて、より専門的な指導ができるであるとか、また部活動の見直しを各校行っているので、そういったところでマニュアルを作成して各学校の取組みを充実させているので。","voiceIndex":45,"id":"exchange-020"}]},{"id":"topic-03","title":"令和２年度「秋の読書フェア」","agenda":"令和２年度「秋の読書フェア」","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、あとテーマの選定なのですけれど、全くのフリーハンドなのか。今、指定管理者がやっていますよね。図書館法第１４条で、住民参加の保障として図書館協議会の設置が求められているということなのですけれども、こういう細かいテーマまでそういったものをやるかというのはあるにしても、こうした図書館協議会などでの議論などがなされているのかなど、その辺もお聞かせください。","respondent":"横山品川図書館長","answer":"２点目の、「秋の読書フェア」のテーマの各館の方針につきましては、年間で各図書館、環境であるとか人権であるとか平和であるとかという、統一テーマで行うというのを会議で決めておりまして、それ以外の月につきましては、春の読書フェア、秋の読書フェアについては。","voiceIndex":51,"id":"exchange-021"},{"speaker":"あべ委員","kind":"質問・要望","question":"それで、フェアもそうですし、やはり蔵書などを見ていても、品川区の図書館がすごいと思うのは、若干ではありますけれど、ライトノベルみたいなものも入っていたりして、全館で一、二冊ぐらいしかないところに何十件も予約が入っていたりするのを見ると、やはり選書でも、若い世代の人たちがまずスタートラインとして気軽に読めるようなものを蔵書として増やすとともに。","respondent":"横山品川図書館長","answer":"まさに委員からご指摘いただきました、ティーンズの世代の読書離れが非常に問題とされているのを図書館でも認識しておりまして、昨年度策定の子ども読書推進計画におきましても、中高生、大学生の読書活動を進めていこうということを決めまして、各図書館で。","voiceIndex":55,"id":"exchange-022"},{"speaker":"あべ委員","kind":"意見","question":"ＰＯＰコンテストは、私も大崎図書館でチラシを見まして、いい試みだと拝見しておりました。そうした新しい試みと同時に、こうしたルーチンの定期的な活動の中にもやはり入れ込んでいっていただければと思います。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-023"},{"speaker":"横山委員","kind":"確認","question":"すみません。細かいところで申し訳ないのですけれど、周知方法についてなのですが確認させてください。「秋の読書フェア」のほうは、今回、ポスターやチラシ、チラシは統合チラシがあると思うのですけれども、その辺りの状況と、「秋の子ども読書の日フェア」のほうは、統合チラシは今回はなしということなのでしょうか。","respondent":"横山品川図書館長","answer":"両フェアにつきまして、若干、周知方法が違うところなのですが、客層の違いといいますか、どちらかというと子どものほうについては、日頃、図書館を利用されていて、親御さんと一緒に参加されるようなことが多いので。","voiceIndex":58,"id":"exchange-024"}]},{"id":"topic-04","title":"ゆたか図書館の空調設備改修工事","agenda":"ゆたか図書館の空調設備改修工事","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"確認なのですけれど、これだけコロナがはやっていて、空調も随分進化してきて、換気をしながら空調ができるものというのも、近年、大分出てきていると聞いています。今回の図書館も、空調を使っているとどうしても換気が悪くなりがちだと思うのですけれども、換気可能なタイプかどうか分かりますか。","respondent":"横山品川図書館長","answer":"機器の詳しいところは把握しておりませんが、今現在は、ゆたか図書館では空調を使いながら一定の期間、窓を開けて換気をするというような形で調整させていただいているところで、これからも、実際の自然換気というのは併用しながら運用していきたいと考えています。","voiceIndex":64,"id":"exchange-025"},{"speaker":"あべ委員","kind":"意見","question":"窓を開けながら空調を使うというのも、換気できないタイプだったらそれは仕方がないと思うのですけれども、また今後、情報収集などもしながら、状況をお教えいただければと思います。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-026"}]},{"id":"topic-05","title":"令和元年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和元年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"それぞれＡ、Ｂ、Ｃのグループで見ますと、入館者数と貸出の総数を比べますと、Ａ・Ｂは微減というか、ちょっと減っているのですけど、Ｃグループは結構増えている感じなのです。これは何か地域的なものとか、またはＡ・Ｂのほうで何か改築や図書館の改修があって減ってしまったのか、何か理由が分かれば教えていただきたいと思います。","respondent":"横山品川図書館長","answer":"その他の入館者数・貸出数が減っている状況につきましては、これは全体に減っているわけではなく、むしろ駅の取次施設で予約して貸し出すという傾向がかなり増えておりますので、図書館の利用の仕方が多様化しているという状況を表しているものと考えております。","voiceIndex":71,"id":"exchange-027"},{"speaker":"たけうち委員","kind":"質問・要望","question":"一概に数が減っているからいい・悪いなどという単純な比較ではないとはもちろん思っているのですが、大崎のほうで結構、利用者が増えているという中で、一方ではＣグループの裏面のほうで見ますと、ほかのＡ・Ｂのグループもかなり、地域やイベントなど、いろいろなところと連携を取りながらの展開が見られている中で、Ｃもいろいろとやっていらっしゃるのだとは思うのですが、一方で３番のところを見ると。","respondent":"横山品川図書館長","answer":"そういう意味合いで、区民ニーズとして、高齢化社会に向かって、健康であるとか、高齢期をどう過ごすかというような興味に対して、図書館が知識として応えていくという、新しい取組みができる場として期待がとても大きいので、今現在も増加しているものですけれど。","voiceIndex":73,"id":"exchange-028"},{"speaker":"たけうち委員","kind":"意見","question":"分かりました。非常に積極的な、また新たな取組みということで、非常に期待するところなので、ぜひこれからも引き続き、それぞれのグループのよさもまた見ながら、共有しながら推進してもらえればと思いますので、よろしくお願いします。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"これを拝見した中で気になったのが、ＡグループとＣグループで、「改善が必要とされた原因の分析および対応方針」のところで、有資格者の配置について引き続き努力するというのは、Ａ・Ｂ・ＣのうちＡとＣで有資格者の配置が必ずしも予定どおりできていないことを意味するのですか。","respondent":"横山品川図書館長","answer":"こちら、評価がＡ・Ｂ・Ｃですので、多少、相対評価もございまして、Ｂグループがかなり、７割に近い有資格者数を持っておりますので、ここに比べますと、数的にもＡ・Ｃは人数が多いので、若干、それよりも低い形ですが。","voiceIndex":76,"id":"exchange-030"},{"speaker":"あべ委員","kind":"質問","question":"Ｂで７割。これは、現実としてはなかなかすごいと思うのですけれども、やはり有資格者、司書を配置していくというのが原則だと思いますので、そこはぜひやっていただければと思います。それで、指定管理の内容というのは、基本的には一定だと思うのですけれども、コロナを受けて、お金の面も含めて、内容的に令和２年度、どういう見直しがかけられているのか教えてください。","respondent":"横山品川図書館長","answer":"ただ、外から見て閉まっているのですけれど、中のバックヤードは動いておりまして、窓口こそ開いていなかったのですが、本を買わなければならない、また除籍等の管理をしなければならないというところで、日頃できない除籍の処理を進めるであるとか。","voiceIndex":78,"id":"exchange-031"},{"speaker":"あべ委員","kind":"質問・要望","question":"図書館は結構、予約貸出はずっと続けていただいて、バックヤードは本当に大変だったと聞いています。新しい、様々な、これまでなかったような仕事も出てくる中で、図書館の貸出業務を続けていただいたことは本当にありがたいですし、ステイホーム中の大きな心の柱になったのではないかと、利用者の方々からも伺っています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと、全体なのですけれど、指定管理のモニタリングに関して、社会保険労務士を入れた運営体制チェックの試行という動きがあったと思うのですけれど、こちらの図書館所管分については、それはどういう対応をされるのかというのと、あと子育て部門のモニタリングシートには、管理委託料などが記載されているのですが、そちらにはないというのは何でなのかというのをお伺いしたいと思います。","respondent":"横山品川図書館長","answer":"外部監査の社会保険労務士等のチェックによるものにつきましては、運営５年間のうちの４年目という形になっておりますので、品川区立図書館については、今、３年目ですので、来年度、外部監査が予定されております。","voiceIndex":81,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"それと裏面の３番ですか、スタッフのレベルアップについても書いているのですけれど、最も大事なことは、やはり長く勤められ、スキルを積み上げられるかどうかだと思うのですけれど、やはりその際というのは待遇も大きな１つの要だと思うのですが、スタッフの雇用形態ですとか平均賃金ですとか、３年以内の離職率などについて、品川区としては現在把握しているのでしょうか。以上、３点伺います。","respondent":"横山品川図書館長","answer":"Ａグループ「総括」に書いてあります年間計画に基づいた継続的な実施という形については、金銭的に特に問題があったなどということではなく、年間を四半期に分けて収支の報告をしていただいているのですが、若干、増減が、年度の初めに多かったり。","voiceIndex":83,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"ただ単に本を貸し出すという機械的な仕事をやっているわけではなくて、やはりレファレンスですとか、相談に応じて情報を集めて、あるいは様々な相談に乗るということだと思うので、やはり専門スキルを積み上げていくというのが図書館の質に関わってくるという大事なところだと思うので、少なくとも３年以内の離職率ですとか継続勤続年数の平均ですとか。","respondent":"横山品川図書館長","answer":"一方で、委員ご指摘のとおり、長く続けるためには待遇が大事だというところも承知しているところですので、安心して勤められるような勤務条件であってほしいというところは、包括的に日々、事業者と連絡を取り合う中でお伝えしていますし。","voiceIndex":85,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"とりわけ専門スキルを身につけるためには、そこで長く働くことが大事なことだと思いますし、やはり職種がころころ変わっては積み上げられないわけですから、ぜひモニタリングシートで、勤続年数ですとか、区がお持ちの数字でしたら出していただきたいと思いますが、再び最後にお伺いして質問を終わりますけれど、いかがでしょうか。","respondent":"齋藤教育次長","answer":"総括シートは企画部で調整しております。どのような形で出すかの様式については企画部で統一的に調整しておりますので、委員の今のお申し出につきましては、企画部にお伝えします。","voiceIndex":87,"id":"exchange-036"},{"speaker":"横山委員","kind":"質問","question":"５ページの、Ｃグループの部分なのですけれども、積極的に評価したことのところで、雑誌スポンサー制度ですとか、またビブリオバトルというところ、課題に積極的に取り組んでいるということなのですが、令和元年度の実施の状況と、現在の状況を教えていただけたらと思います。","respondent":"横山品川図書館長","answer":"ビブリオバトルにつきましては、昨年度、Ａグループ・Ｃグループ合同で五反田文化センターで行いまして、本年度についても、このような状況ではありますけれど、実施しようということで企画をしています。","voiceIndex":89,"id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"新しいことに取り組んでいくときには、なかなかすぐに成果が出るなどというのは難しいかもしれないのですけれど、雑誌スポンサー制度も、昨年は１事業者で７誌ということだったと思うのですけれど、実際の数に結びつくというところまでには少し時間がかかることがあるかも分からないですが、そういったことをやっているということで、そういったこともまた宣伝効果というか、つながっていくかと思いますので。","respondent":"横山品川図書館長","answer":"これからも委員のご意見を励みに進めさせていただきたいと考えています。","voiceIndex":91,"id":"exchange-038"},{"speaker":"あべ委員","kind":"質問","question":"司書も、現場で働きながら、少しずつキャリアアップすることも可能な仕事だと思うのですけれども、品川区の図書館では、司書の資格取得のための何かバックアップの制度みたいなものというのは持っていらっしゃるのでしょうか。","respondent":"横山品川図書館長","answer":"働き方についても、常勤の方でフルタイムという方だけではなく、子育て中に時間を区切って好きな仕事をしてというような働き方をしていらっしゃる方も多いので、そういう方については、やはりしばらく経ってから、その研修を受けようということで。","voiceIndex":93,"id":"exchange-039"},{"speaker":"あべ委員","kind":"質問","question":"先ほどの割合は司書の資格、司書補も入れての数字でしょうか。","respondent":"横山品川図書館長","answer":"報告されているのは司書の資格です。","voiceIndex":95,"id":"exchange-040"},{"speaker":"あべ委員","kind":"意見","question":"何かの折に、司書資格まで到達できればいいのですが、一足飛びに難しければ、やはりステップ・バイ・ステップということもあると思いますので、事業者と、その辺もご本人の経歴形成の面からも、ぜひ後押ししていただければと思います。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-041"},{"speaker":"筒井委員","kind":"質問","question":"Ｃグループのほうが入館者数が増えている、先ほどもお話が出ましたけれども総じて増えているということで、また児童おはなし会の参加者数も増えているということなのですけれども、単純に考えて、この地域の住民が増えた、特にファミリー世帯の数が増えたということは、本当にシンプルな疑問なのですけれど、そういったことはあるのでしょうか。","respondent":"横山品川図書館長","answer":"Ｃグループにつきましては、一般の図書も大崎地域の読書人口の底上げという面もありますし、大崎図書館も大崎図書館分館も、学校の隣という地の利を発揮しているようなところもあるので、生徒はもちろんですけれども、生徒のご兄弟であるとか。","voiceIndex":98,"id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"地の利などもあるということで、当然、Ｃグループでいろいろと事業努力をされているところもあるのですけれども、そういった地の利もあるのかと考えています。ただ、Ａグループ、Ｂグループもぜひ工夫して、来館者数などをぜひ伸ばしていっていただきたいと考えております。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-043"}]},{"id":"topic-06","title":"休憩前に引き続き、文教委員会を再開いたします。 それでは引き続き、(5)令和元年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"休憩前に引き続き、文教委員会を再開いたします。 それでは引き続き、(5)令和元年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"家庭あんしんセンターのほうですけれど、来館者数や事業実施数が継続的に減っているというのは、やはり子ども家庭支援センターへの統合といったものが理由なのでしょうかというのがまず１点。そうだとしたら、その理由は何なのか、伺いたいと思います。","respondent":"崎村子ども家庭支援センター長、三ッ橋子育て応援課長、吉田保育施設調整担当課長","answer":"令和元年度については、３月に新型コロナの関係でフラっと広場を休止した関係で、実績が大きく落ちているものと認識しています。人材育成の促進ですが、令和元年度は人事異動などの関係で新しい職員、新人職員が入りましたので、そちらの人材育成の向上を図っていくものです。これをまた引き続き利用して、処遇改善等に取り組みまして、経費の削減に取り組んでいくという内容です。","voiceIndex":106,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"それぞれ分かりました。直近の事業者交替の、正式には次回、第４回定例会に案件が出てくると思うのですけれど、現在の状況というのはどんな感じでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"９月４日〔同日後刻に「９月３日」と答弁訂正あり〕に指定管理の選定委員会が行われまして、その中で、事業者について、福栄会からの指定管理の申請内容を審査し、また審査委員には外部委員を含めまして、公平性を保つよう審査を行い、今、決定について進めているところです。","voiceIndex":110,"id":"exchange-045"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは、もう少し詳しく教えていただきたいと思います。もう少し詳しい分析をきっとされていると思いますので、ここについて教えてください。それと、幾つもの事業を家庭あんしんセンターでなさっているわけですけれども、管理運営委託料の内訳を、ざっくりでいいのですけれども教えていただけますでしょうか。そこの２点をお願いします。","respondent":"崎村子ども家庭支援センター長、三ッ橋子育て応援課長","answer":"ショートステイにつきましては、昨年度が育児疲れによる利用というのが大きく減っておりまして、平成３０年度が１３０泊中の８０泊ぐらいが育児疲れ、育児不安によるご利用だったのですけれども。管理運営費の内訳ですが、人件費、事業費、事務費となっておりまして、一番多いものが人件費で１億２,０００万円程度、それから事業費が……。","voiceIndex":114,"id":"exchange-046"},{"speaker":"あべ委員","kind":"質問・要望","question":"減っているというよりも、受け入れられていないのではないかというのは、すごく、特に厳しいご家庭が、この利用は多いと思いますので、そこはぜひ、今後、運営を変えていただきたいと思いますが、いかがでしょうか。それで、すみません。そこにはやはり原因があるのではないかと思うのですけれど、そこはどのように捉えていらっしゃいますでしょうか。","respondent":"三ッ橋子育て応援課長、崎村子ども家庭支援センター長","answer":"大井と平塚の差ですけれども、それぞれアフターケア、また丁寧に対応していくという部分が非常に大きいのですが。これはショートステイ全体の検討ということがあるかと思いますが、子育て支援センターで拡充するのか。平塚ファミリー・サポート・センターにつきましては、光熱水費まで含んでおりますので、その関係があります。","voiceIndex":119,"id":"exchange-047"},{"speaker":"あべ委員","kind":"質問・要望","question":"それでも金額的に保っているのはなぜかというもう一方の疑問もあるのですけれども、それ以上にやはり、子どもの数も増えていますし、むしろこうしたものというのは、より使われる、需要が上がっていっておかしくないものだと思っているのですが、実際のサービスの提供量がどんどん減っているということは、何かそこに使いにくさがあるのではないか、あるいは受け止め切れていないのではないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"ひがしやつやま保育園は運用期間を延長して、ほうさん保育園は延長しないということですが、その違いというか、土地が利用できるかどうかだと思うのですけど、ひがしやつやま保育園のほうはどういう事情で使えるようになったのかとか、もう少しその辺をご説明いただきたいというのと、あと参考までに、ほうさん保育園が閉園後の施設の跡地というのは、何に活用することを検討しているのか伺いたいと思います。","respondent":"立木保育課長","answer":"ほうさん保育園のほうにつきましては、５年間の期間限定というところは変わっておりませんで、それ以降の土地利用ができないということで確認しております。それ以後の土地の活用方法につきましては、私のほうには伝わってきておりませんので、お答えすることができません。","voiceIndex":128,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"北品川のほうは、貴重な区の土地ですし、これは都営住宅もありますし、景観を大事にしている地域でもありますので、再開発も考えているということだと思いますけれども、私はやはり、こういう保育施設ですとか高齢者施設ですとか、あるいは低廉で入れる住宅という、公益的な施設というのを維持・存続してもらうというのが大事だと思いますので、再開発自体は必要ないのかと考えていますので。","respondent":"立木保育課長","answer":"それぞれ、ひがしやつやま保育園のほうも、まちづくり部門、それから企画部に確認しています。それから、まちづくりのことに関しましては私は答える立場にございませんが、そういったところは所管に伝えします。","voiceIndex":130,"id":"exchange-050"},{"speaker":"あべ委員","kind":"確認","question":"確認ですけれど、１年足らずになりましたというのは、保護者にはいつ頃お伝えする、あるいはもう既にしているのか。在園の方々は、もう大丈夫だから関係ないというよりも、ご兄弟の関係などもあるので早めにしておいたほうがいいと思うのですけれども、まず保護者への確認について教えてください。","respondent":"立木保育課長","answer":"こちらの運営方針につきましてのお知らせは、これから保護者の方に対してお知らせするのと同時に、これから入園を考えているご家庭の方に対してもお知らせを出していく予定です。","voiceIndex":132,"id":"exchange-051"},{"speaker":"あべ委員","kind":"質問","question":"これから入園を考えている方へのお知らせというのは、どういう形で行うのか。一般的な、全体の一覧に入っていくのか。それとも、さらに近隣の方などにお知らせするのか、詳しく教えてください。","respondent":"立木保育課長","answer":"これから、どちらかの保育園への入園をご希望されるご家庭に関しましては、保育園のご案内等での記載に加えまして、それから入園の希望の方に対しては、通知文でも、手渡しできるものに関しましてはお渡しするような形で、窓口等でもご案内するように考えております。","voiceIndex":134,"id":"exchange-052"},{"speaker":"あべ委員","kind":"質問・要望","question":"それで、基本的に暫定保育園というのは、再開発地の中で計画されることが多いと思いますので、次の再開発の中にできるだけ早く位置づけるような形で、地域内移行ができるような形で、ぜひ庁内でも働きかけをしていただきたいと思うのですけれど、その辺、お考えはいかがでしょうか。","respondent":"立木保育課長、若生保育支援課長","answer":"今後、私立保育園の開園等もありますので、その辺は、子ども・子育て支援事業計画の中でもっとしていくことだと考えていますが、基本的に限定園はこのような形になりますので、私立保育園のほうの新規開設等。こちらの東品川の周辺ですけれども、今後、来年度開設予定の園が３園、東品川でもあります。当然、こちらの閉園も見越した上で、再開発等を踏まえまして、開園の計画は進めているところです。","voiceIndex":136,"id":"exchange-053"},{"speaker":"あべ委員","kind":"質問・要望","question":"考え方なのですけれども、やはり保育園の中の子どもたちというのは１つの社会をつくっているわけですから、１人ずつ３人分あればいいというような、単なる数だけの考え方ではないような、安定した保育をお願いいたします。最後、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-054"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ということは、あそこがまたなくなるということになるわけですが、その辺で、あの地域には、同じ地域には、かなり多く、今、新しく保育園が新設されているので、待機児のほうはもう大丈夫だろうということと、あと、これは款が違うのでしょうけれど、あそこの土地の活用とか、また地元のいろいろな要望等のことになると思うのですが、その辺のスケジュールのことはどんな感じなのか。","respondent":"吉田保育施設調整担当課長","answer":"ほうさん保育園の定期利用につきましては、今後、契約を含めて考えていくところです。それから、現在の南ゆたか保育園、同じ荏原第四中学校跡地に２つの保育園があるうちの南ゆたか保育園なのですけれども、今年度中に、引っ越し元の園舎に戻る予定です。","voiceIndex":140,"id":"exchange-055"},{"speaker":"たけうち委員","kind":"確認","question":"分かりました。前に資料が出ているのがあったかと思って、ちょっと確認させていただきました。では、そこで一応、もういろいろと建て替えの用地としてずっと利用されてきた場所ですが、そこで一旦終わると。その後はこれからということですね。分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-056"},{"speaker":"筒井委員","kind":"質問","question":"ほうさん保育園のほうは、令和３年４月より卒園まで在籍できないクラスの入園を停止となっているのですけれど、ひがしやつやま保育園の場合、入園停止の措置というのは行わないのでしょうか。","respondent":"立木保育課長","answer":"令和４年に入園するお子様に関しましては、今の状態ですと卒園できないということになりますが、来年度以降の取扱いにつきましては、また次年度、検討するという形ですので、来年度に関しましては入園停止の措置は行わない予定です。","voiceIndex":143,"id":"exchange-057"},{"speaker":"筒井委員","kind":"質問","question":"その理由は、さらに延長する可能性があるということですか。","respondent":"立木保育課長","answer":"ひがしやつやま保育園に関しましては、まちづくりの動きの中で、また今後延ばせる可能性というのも探っていくという中では、今現在は、１年は延ばせるというところは確認できているのですが、その先までは、今のところはちょっとまだ不明ですので、それはまた来年度。","voiceIndex":145,"id":"exchange-058"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。ただ、なるべく、閉園時期というのがはっきりとしましたら、やはり保護者の方とか、当然お子さんにも大きな影響を与えることになりますので、ひろまち保育園の問題もありましたので、そこはしっかりと、きちんとした説明と、ご理解をいただくような工夫というか取組みを行っていただきたいと思います。その点、いかがでしょうか。","respondent":"立木保育課長","answer":"そういったところから、今年度、来年４月の入園に向けて事前にお知らせをするということで、今回のご報告をさせていただいているところですので、今後もこのような形で早め早めの周知は心がけてまいりたいと思います。","voiceIndex":147,"id":"exchange-059"},{"speaker":"芹澤副委員長","kind":"質問","question":"なかなかハードなスケジュールだったというようなことが書いてあって、こういった、また同じようなボタンのかけ違えということにはならないようにしてほしいと思っているのですけれども、ほうさん保育園の令和４年度の一部の転園される方に対しての周知というか、スケジュール感はどのようなお考えなのでしょうか。","respondent":"立木保育課長","answer":"一応、このようなスケジュールであれば、ほうさん保育園の在園のご家庭、それから、それ以外の、これから来年度、翌年度に向けて保育園の検討をされるご家庭に対しても影響は少ないだろうと思われますので、夏ぐらいのご案内等を考えているところです。","voiceIndex":149,"id":"exchange-060"},{"speaker":"芹澤副委員長","kind":"意見","question":"期間限定というのは、もともと５年間というのが、ひろまち保育園のときもそうでしたけれども、それが前提にあって、今、ひがしやつやま保育園のように延長できるところは延長していくという姿勢は、保護者の方々にとっても非常にありがたいと思いますので、そこは模索していきながらも、前提はやはり５年で終わりになるというのを、引き続きしっかりと周知をしていただいて、終わる際、転園が必要な場合には。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":151,"id":"exchange-061"}]},{"id":"topic-07","title":"の２の所管事務調査","agenda":"の２の所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、Ａ３の５ページですか、一体型と併存型というところがありましたけれど、支援のしやすさというところの併存型のほうの説明が、これは文章だと分かりにくいので、どういうことを言っているのかというのをもう少し説明いただきたいと思います。","respondent":"崎村子ども家庭支援センター長、加島児童相談所移管担当課長","answer":"例えば、居所不明の児童がいた場合に、我々が家庭訪問しても分からないといったときに、警察の方とご相談して、警察ですと全国的にネットワークがありますので、そちらのほうに照会していただいたり、そういった。支援のしやすさの部分について重ねて説明します。「複数の機関が存在することにより」という部分ですが、こちらが一体型の特徴と表裏一体となっております。","voiceIndex":157,"id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"それを聞いて私も、やはり何が一番大事かというと、ここを利用する、あるいは利用せざるを得ない状況になっている子どもたち自身にとってどうなのかというのが一番大事な点なのではないかと改めて思ったのですけれど、一般に学校の近くとか、クラスメートに遭遇する可能性も高い、子どもがよく出入りする公園とか、そういう場所に児童相談所が適しているかというと。","respondent":"加島児童相談所移管担当課長","answer":"そういった中で、土を踏んで遊べる環境を、区内の中でどこまで用意できるかということを考えたとき、公園の緑、それから目黒川の水の流れる環境というのは、一時保護された子どもたちにとって、１つの心の安らぎとなるのではないかと考えております。","voiceIndex":160,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、一体型か併存型かというのは、本当に慎重に検討していったほうがいいと思うのですけれど、品川児童相談所を会派で視察しに行ったときに言われていたのは、やはり、かなり職員が疲弊するというか、すごく、とにかく重たい仕事なので、特に家庭自体が重たい問題を抱えているというケースがほとんどですから、人材育成といいますか、なかなか新人の方が入っても。","respondent":"加島児童相談所移管担当課長","answer":"併存型か一体型かはただいま検討を行っているところですので、設計上、子ども家庭支援センター機能の相談員数が執務室に収まり切るかというところと捉えてお答えいたします。設計上は、今現在、開設時点では収容できると考えております。","voiceIndex":162,"id":"exchange-064"},{"speaker":"あべ委員","kind":"質問・要望","question":"ごめんなさい。確認の意味も含めて、組織について教えていただきたいのですけれども、要保護児童対策地域協議会の３層構造ということで、１層目は虐待防止ネットワーク推進協議会。それで、２層目の協議会地域分科会というのは子どもだけの組織なのでしょうか。これは、直接的につながっているものなのですか。ちょっと、そのイメージがつきにくかったので、もう少しこの３層について詳しく教えてください。","respondent":"崎村子ども家庭支援センター長","answer":"他の高齢者や障害者の部門について、こういった地域分科会のようなものが開かれているのかというところは把握していないところなのですけれども、３層構造では、代表者会議が、全体が４つの虐待の部分で一緒に行っていて、２層目。","voiceIndex":164,"id":"exchange-065"},{"speaker":"あべ委員","kind":"質問","question":"それで、１３地域あるということは、例えば児童相談所の方も入っていらっしゃるとおっしゃっていましたけれど、１３会議にそれぞれ児童相談所の方が出てきているということなのですか。そうすると、結構大変で、本当に１３でやっていいのかという気にもなってしまうのですけれど、その辺の組織について、今、何か課題とか、今後こうしたいというのがあれば教えてください。","respondent":"崎村子ども家庭支援センター長","answer":"やはり、その地域でどういった方がいるのかというのを、児童相談所としても把握していただくというのは大切なことであろうかと考えています。それで、お声をかけさせていただいて、児童相談所の業務のお話ですとか現在の虐待の状況などをご説明していただいているところです。","voiceIndex":166,"id":"exchange-066"},{"speaker":"あべ委員","kind":"質問・要望","question":"年間どのぐらいの頻度で開かれているかというのも教えてください。それで、２番（１）「児童相談所の主な業務」と、1)から7)までありますけれども、例えば1)とか4)とか6)というのは、子ども家庭支援センターの中でもかなり力を入れて担っていってほしいと思うようなところなのですけれど、そういった意味でも、すみ分け、機能というのは、どういうふうに考えていらっしゃいますか。","respondent":"崎村子ども家庭支援センター長、加島児童相談所移管担当課長","answer":"地域分科会なのですけれども、これは年１回、各１３地域で行っているものです。基礎自治体だからこそ、予防の視点を持って、早い段階から子どもと家庭と関わり、そしてまた児童相談所、現在は児童虐待が発生した後に対応しておりますが、そうではなく。","voiceIndex":168,"id":"exchange-067"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひその方向で行ければ行っていただきたいと期待しております。里親の支援ですとか、あるいは家庭機能の回復プログラムですとか、あるいは子育て困難家庭への、ヘルパー的な、物理的なサポートなどもそういうところでできるといいなと考えております。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-068"},{"speaker":"たけうち委員","kind":"質問","question":"逆に言うと、協力依頼等が来たけれども、実際に対応してみたら、区の子ども家庭支援センターの見解では、今のところ、まだ、全くゼロとは言えないけれども、それほどではないのではないか。経過的にあれしなければいけないかもしれないけれどという、その割合というのですか、ざっくりで結構なのですけれども、どのような感じなのでしょうか。","respondent":"崎村子ども家庭支援センター長","answer":"昨年１０月から、児童相談所から子ども家庭支援センターに送致といったことが開始されまして、その対応なのですけれども、主に送致で送られてきますのが、近隣からの泣き声の通告。","voiceIndex":172,"id":"exchange-069"},{"speaker":"たけうち委員","kind":"質問","question":"分かりました。その辺はどうなのですか。","respondent":"加島児童相談所移管担当課長","answer":"こちらの他区の情報をつかむ中では、大田区、目黒区ともに児童相談所の開設の意向を持っていますが、まだ現在、開設予定時期までは明らかになっておりません。","voiceIndex":174,"id":"exchange-070"},{"speaker":"たけうち委員","kind":"質問","question":"いずれにしても、どちらがいいのかというのは非常に難しいところで、我々としては身近な地域でやっていただけるということがベストなので、この流れでいいと思うのですが、その上で東京都のほうがあったほうが重層的にいいのかというイメージもあるし、いろいろな、でも情報がダブってどうなのかということで、できたのならなくせばいいのではないかという考えもあるのでしょうけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-071"},{"speaker":"横山委員","kind":"質問・要望","question":"幾つか伺っていきます。５ページの児童相談所のところなのですけれども、現在、先行３区、荒川区・江戸川区・世田谷区のそれぞれの運営状況を区がつかんでいる部分がありましたらお願いいたします。東京都からの支援というか人材の研修の部分ですとか、そういったところをどんなふうに先行３区が連携しているのかというところも、もし分かればお願いしたいと思います。その辺りはいかがでしょうか。","respondent":"加島児童相談所移管担当課長、崎村子ども家庭支援センター長","answer":"半減しておりますので、こういった、そもそも在宅に復帰したときへの支援計画ですとか、そういったものをきちんと念頭に置いて敷衍されているという姿勢は、私どもも検討の過程で組み込んでまいりたいと考えております。こちらは特に詳しく分析をしているわけではないのですけれども、考えられるのは、この間、一時保護から家庭復帰をする際には、必ず児童相談所から個別ケース検討会議の開催を依頼されます。","voiceIndex":177,"id":"exchange-072"},{"speaker":"横山委員","kind":"質問・要望","question":"東京都であったり先行の３区であったり、先行区の連携だったり人材育成の部分だったり、そういうところは、ぜひなるべく引き出していただいて、ご協力いただいてお願いしたいということは、ぜひ要望させていただきたいと思います。３ページのところなのですけれども、先ほどご説明の中に、保健センター、保健所からの、こちらは連絡が増えているということなのでしょうか。その辺り、確認をさせてください。","respondent":"崎村子ども家庭支援センター長","answer":"そういった家庭内事故の報告が多くなっているといったところで、１１３件の内訳としては、そういったところでご説明させていただいたところです。４ページの児童虐待防止会議や虐待ケース進行管理会議につきましては、月１回実施しています。","voiceIndex":180,"id":"exchange-073"},{"speaker":"横山委員","kind":"質問・要望","question":"細かい報告というか報告の精度みたいなところについても、児童相談所と子ども家庭支援センターでそれぞれ必要としている情報というのがあるかと思うのですけれども、細かく全てというのはなかなか現実的に難しいと思うのですが、この部分は、子ども家庭支援センターとしては、児童相談所からすごく普通に欲しい情報であったり、個別ケースによっても変わってくるかと思うのですけれども。","respondent":"加島児童相談所移管担当課長","answer":"それぞれでケースに対する緊急度がきちんと一定の形で把握されるように、世田谷区などでは、共通のリスクアセスメントシートを用いた形で、ケースの緊急度を視覚化しているとも聞いておりますので、私どもはそのような方法で、両機関の情報共有。","voiceIndex":182,"id":"exchange-074"},{"speaker":"せお委員","kind":"質問・要望","question":"１点だけお伺いしたいのですが、児童相談所の５ページのところで、児童相談所ができた頃というのは、子どもや家庭などの相談というのは全般的なことだとは思うのですけれど、今はこのような、皆さんご存じのとおり、児童相談所というのは虐待関連の支援をしていくというところがメインとならざるを得ないというか、件数が多いですので、そういったところで、主な業務のところで。","respondent":"加島児童相談所移管担当課長","answer":"こちらの子どもの障害等の体制につきまして、今現在受けております、東京都品川児童相談所における障害相談の内容の詳細の把握などをきちんとした上で、今後、児童相談所、またはどちらの機関で行うのが適切かというのを、関係課とも協議してまいりたいと考えます。","voiceIndex":184,"id":"exchange-075"},{"speaker":"せお委員","kind":"質問・要望","question":"東京都ではないのですけれど、ほかの地方の自治体などでは、児童相談所から業務を委託して、愛の手帳の判定を委託してやってもらっているというところもあったりするので、そういったところも考えてもらいながら、あとは東京都品川児童相談所や、先行３区など、そちらの業務内容の調査をしていただいて、検討していっていただきたいと思っています。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-076"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5014#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":69433,"voices":191}}]);
